INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wenakita/CreatorVault/lottery-vrf-ops', 'lottery-vrf-ops', 'wenakita', 'CreatorVault', 'community', 'lottery-vrf-ops wenakita CreatorVault community lottery-vrf-ops is a technical skill that enables developers to manage lottery operations using VRF. It benefits developers working with blockchain and smart contracts. lottery-vrf-ops是一种基于VRF的彩票操作技能，用于配置和管理彩票系统。 lottery-vrf-opsはVRFベースのロトリー操作スキルで、ロトリーシステムの設定と管理に使用されます。 lottery-vrf-ops는 VRF 기반의 복권 운영 스킬로 복권 시스템을 설정하고 관리하는 데 사용됩니다. lottery-vrf-ops es una herramienta para desarrolladores que permite la configuración de VRF en proyectos de lottery. Ofrece una guía de configuración para una integración exitosa lottery-vrf-ops est un outil pour les développeurs qui permet la configuration de VRF dans les projets de lottery. Il propose un guide de configuration pour une intégration réussie lottery-vrf-ops ist ein Tool für Entwickler, das die Konfiguration von VRF in Lottery-Projekten ermöglicht. Es bietet einen Konfigurationsleitfaden für eine erfolgreiche Integration O lottery-vrf-ops é uma ferramenta para operações de VRF em loterias, permitindo a configuração de parâmetros como chain, contract addresses e RPC URL lottery-vrf-ops - это инструмент для операций VRF в лотереях, позволяющий настраивать параметры, такие как chain, контрактные адреса и RPC URL lottery-vrf-ops هو أداة لإدارة اللوتو باستخدام VRF، مما يسمح بإعداد 매개ترات مثل chain، عناوين العقد و RPC URL how to use lottery-vrf-ops lottery-vrf-ops setup guide what is lottery-vrf-ops lottery-vrf-ops alternative lottery-vrf-ops vs chainlink vrf lottery-vrf-ops install lottery-vrf-ops configuration vrf hub setup blockchain lottery operations lottery-vrf-ops VRF 彩票操作 AI工具 RPC URL 签名者地址 本地VRF 跨链VRF Configures VRF hubs with vrfCoordinator, subscriptionId, and keyHash Supports local and cross-chain VRF modes with useLocalVRF and vrfIntegrator Collects inputs such as chain, contract addresses, RPC URL, and signer/admin address Confirms current mode on the lottery manager with useLocalVRF and localVRFConsumer Manages callbackGasLimit and requestConfirmation for seamless operations Integrates with blockchain networks for secure and transparent lottery operations lottery-vrf-ops is a skill that facilitates the configuration and management of Verifiable Random Functions (VRF) for lottery operations on blockchain networks');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AndrijaSkontra/ai-driven-project-template/deployment', 'community', 'AndrijaSkontra', 'ai-driven-project-template', 'AndrijaSkontra/ai-driven-project-template', 'deployment', 0, 0, 57, '2026-03-08T01:57:15.510Z', '2026-03-08T02:10:25.642Z', 'd2b8fadf64b801fdc7f792307c77ce517a1292be1e96083bf9cd03ae611b1769', '{"id":"AndrijaSkontra/ai-driven-project-template/deployment","name":"deployment","description":{"en":"The deployment skill handles unified deployment to multiple platforms, benefiting developers who need to deploy APIs and serverless functions to Cloudflare Workers and Supabase Edge Functions.","zh":"统一部署技能支持同时部署到Cloudflare Workers和Supabase Edge Functions，使用Wrangler和Supabase CLI实现自动化部署","ja":"統一デプロイメントスキルは、Cloudflare WorkersとSupabase Edge Functionsへの同時デプロイをサポートし、WranglerとSupabase CLIを使用して自動化されたデプロイメントを実現します","ko":"통합 배포 스킬은 Cloudflare Workers와 Supabase Edge Functions에 대한 동시 배포를 지원하며 Wrangler와 Supabase CLI를 사용하여 자동화된 배포를 구현합니다","es":"El despliegue de AI Agent permite implementar aplicaciones en Cloudflare Workers y Supabase Edge Functions de manera simultánea","fr":"Le déploiement d''Agent IA permet de déployer des applications sur Cloudflare Workers et Supabase Edge Functions de manière simultanée","de":"Die Bereitstellung von AI-Agent ermöglicht die Implementierung von Anwendungen in Cloudflare Workers und Supabase Edge Functions gleichzeitig","pt":"O skill de implantação permite implantar aplicações em nuvem em Cloudflare Workers e Supabase Edge Functions. Aprenda a configurar e implantar APIs e funções de forma eficiente","ru":"Навык развертывания позволяет развертывать приложения в облаке в Cloudflare Workers и Supabase Edge Functions. Узнайте, как настроить и развернуть API и функции эффективно","ar":"مهارة التوزيع تسمح بتوزيع التطبيقات السحابية في Cloudflare Workers و Supabase Edge Functions. تعلم كيفية تثبيت وتنفيذ واجهات برمجة التطبيقات والدوال بفعالية"},"seo":{"title":{"en":"Deployment: Unified Setup Guide for AI Agents","zh":"部署设置指南：云flare Workers和Supabase Edge Functions","ja":"デプロイメントベストプラクティス：Cloudflare WorkersとSupabase Edge Functions","ko":"배포 설정 가이드: Cloudflare Workers와 Supabase Edge Functions","es":"Guía de Implementación de Despliegue de AI Agent","fr":"Guide de Mise en Place de Déploiement d''Agent IA","de":"Leitfaden für die Bereitstellung von AI-Agent-Deployment","pt":"Guia de Implantação de AI Ferramentas: Deploy em Nuvem","ru":"Руководство по развертыванию ИИ Агентов: Настройка и разв...","ar":"دليل توزيع أدوات الذكاء الاصطناعي: إعداد وتثبيت التطبيقات"},"description":{"en":"Streamline your deployment process to Cloudflare Workers and Supabase Edge Functions with our expert guide - learn how to deploy APIs and serverless function...","zh":"学习如何使用统一部署技能同时部署到Cloudflare Workers和Supabase Edge Functions，实现CI/CD和自动化测试","ja":"Cloudflare WorkersとSupabase Edge Functionsへの同時デプロイ方法を学び、CI/CDと自動テストを実現する","ko":"Cloudflare Workers와 Supabase Edge Functions에 대한 단일 배포 스킬을 사용하여 CI/CD 및 자동 테스트를 구현하는 방법을 알아보세요","es":"Aprende a implementar despliegues en Cloudflare Workers y Supabase Edge Functions con nuestra guía de despliegue de AI Agent","fr":"Découvrez comment déployer des applications sur Cloudflare Workers et Supabase Edge Functions avec notre guide de déploiement d''Agent IA","de":"Erfahren Sie, wie Sie Bereitstellungen in Cloudflare Workers und Supabase Edge Functions mit unserem Leitfaden für AI-Agent-Deployment durchführen","pt":"Aprenda a implantar aplicações em nuvem com o skill de implantação. Descubra como configurar e implantar APIs e funções em Cloudflare Workers e Supabase Edge...","ru":"Узнайте, как развертывать приложения в облаке с помощью навыка развертывания. Откройте для себя, как настроить и развернуть API и функции в Cloudflare Worker...","ar":"تعلم كيفية توزيع التطبيقات السحابية باستخدام مهارة التوزيع. اكتشف كيفية تثبيت وتنفيذ واجهات برمجة التطبيقات والدوال في Cloudflare Workers و Supabase Edge Fun..."},"definition":{"en":"Deployment is the process of releasing software applications or functions to production environments, such as Cloudflare Workers and Supabase Edge Functions, using tools like Wrangler and Supabase CLI","zh":"统一部署技能是一种支持多平台部署的技能，包括Cloudflare Workers和Supabase Edge Functions","ja":"統一デプロイメントスキルは、複数のプラットフォームへのデプロイをサポートするスキルであり、Cloudflare WorkersとSupabase Edge Functionsが含まれます","ko":"통합 배포 스킬은 여러 플랫폼에 대한 배포를 지원하는 스킬로 Cloudflare Workers와 Supabase Edge Functions를 포함합니다","es":"Despliegue de AI Agent es una habilidad que maneja la implementación de aplicaciones en múltiples plataformas","fr":"Le déploiement d''Agent IA est une compétence qui gère le déploiement d''applications sur plusieurs plateformes","de":"Die Bereitstellung von AI-Agent ist eine Fähigkeit, die die Implementierung von Anwendungen auf mehreren Plattformen handhabt","pt":"Implantação é o processo de configurar e implantar aplicações em nuvem em plataformas como Cloudflare Workers e Supabase Edge Functions","ru":"Развертывание - это процесс настройки и развертывания приложений в облаке на платформах, таких как Cloudflare Workers и Supabase Edge Functions","ar":"التوزيع هو عملية تثبيت وتنفيذ التطبيقات السحابية في منصات مثل Cloudflare Workers و Supabase Edge Functions"},"features":{"en":["Deploys API applications (Hono) to Cloudflare Workers via Wrangler","Deploys serverless functions (Deno) to Supabase Edge Functions via Supabase CLI","Supports simultaneous deployment to both Cloudflare Workers and Supabase Edge Functions","Enables deployment to production, publishing APIs or functions, and setting up CI/CD deployments","Allows testing deployments on feature branches"],"zh":["支持Cloudflare Workers API应用程序（Hono）部署","支持Supabase Edge Functions服务器端函数（Deno）部署","同时部署到Cloudflare Workers和Supabase Edge Functions","使用Wrangler和Supabase CLI实现自动化部署","支持CI/CD和自动化测试"],"ja":["Cloudflare Workers APIアプリケーション（Hono）へのデプロイをサポート","Supabase Edge Functionsサーバーレス関数（Deno）へのデプロイをサポート","Cloudflare WorkersとSupabase Edge Functionsへの同時デプロイ","WranglerとSupabase CLIを使用した自動化されたデプロイメント","CI/CDと自動テストをサポート"],"ko":["Cloudflare Workers API 애플리케이션（Hono）배포 지원","Supabase Edge Functions 서버리스 함수（Deno）배포 지원","Cloudflare Workers와 Supabase Edge Functions에 대한 동시 배포","Wrangler와 Supabase CLI를 사용한 자동화된 배포","CI/CD 및 자동 테스트 지원"],"es":["Despliegue en Cloudflare Workers via Wrangler","Despliegue en Supabase Edge Functions via Supabase CLI","Despliegue simultáneo en ambas plataformas","Soporte para implementaciones de producción","Publicación de APIs y funciones","Configuración de despliegues de CI/CD"],"fr":["Déploiement sur Cloudflare Workers via Wrangler","Déploiement sur Supabase Edge Functions via Supabase CLI","Déploiement simultané sur les deux plateformes","Prise en charge des déploiements de production","Publication d''API et de fonctions","Configuration des déploiements de CI/CD"],"de":["Bereitstellung in Cloudflare Workers über Wrangler","Bereitstellung in Supabase Edge Functions über Supabase CLI","Gleichzeitige Bereitstellung auf beiden Plattformen","Unterstützung für Produktionsbereitstellungen","Veröffentlichung von APIs und Funktionen","Konfiguration von CI/CD-Bereitstellungen"],"pt":["Implantação em Cloudflare Workers via Wrangler","Implantação em Supabase Edge Functions via Supabase CLI","Implantação simultânea em ambas as plataformas","Suporte a deploy em produção e teste","Integração com pipelines de CI/CD"],"ru":["Развертывание в Cloudflare Workers через Wrangler","Развертывание в Supabase Edge Functions через Supabase CLI","Одновременное развертывание на обеих платформах","Поддержка развертывания в производстве и тесте","Интеграция с конвейерами CI/CD"],"ar":["تثبيت في Cloudflare Workers عبر Wrangler","تثبيت في Supabase Edge Functions عبر Supabase CLI","تثبيت同时ي في كلا المنصتين","دعم تثبيت في الإنتاج والاختبار","تكامل مع أنابيب CI/CD"]},"keywords":{"en":["how to use deployment","deployment setup guide","Cloudflare Workers deployment","Supabase Edge Functions deployment","deployment vs traditional hosting","unified deployment strategy","deployment best practices","CI/CD deployment tutorial","serverless function deployment"],"zh":["部署设置","Cloudflare Workers","Supabase Edge Functions","Wrangler","Supabase CLI","CI/CD","自动化测试","AI工具","AIエージェント"],"ja":["デプロイメント設定","Cloudflare Workers","Supabase Edge Functions","Wrangler","Supabase CLI","CI/CD","自動テスト","AIエージェント","AIツール"],"ko":["배포 설정","Cloudflare Workers","Supabase Edge Functions","Wrangler","Supabase CLI","CI/CD","자동 테스트","AI 에이전트","AI 도구"],"es":["despliegue de AI Agent","despliegue en Cloudflare Workers","despliegue en Supabase Edge Functions","Wrangler","Supabase CLI","despliegue simultáneo","implementación de producción","publicación de APIs","configuración de CI/CD"],"fr":["déploiement d''Agent IA","déploiement sur Cloudflare Workers","déploiement sur Supabase Edge Functions","Wrangler","Supabase CLI","déploiement simultané","mise en production","publication d''API","configuration de CI/CD"],"de":["Bereitstellung von AI-Agent","Bereitstellung in Cloudflare Workers","Bereitstellung in Supabase Edge Functions","Wrangler","Supabase CLI","gleichzeitige Bereitstellung","Produktionsbereitstellung","Veröffentlichung von APIs","Konfiguration von CI/CD"],"pt":["implantação em nuvem","Cloudflare Workers","Supabase Edge Functions","Wrangler","Supabase CLI","CI/CD","deploy em produção","teste de deploy"],"ru":["развертывание в облаке","Cloudflare Workers","Supabase Edge Functions","Wrangler","Supabase CLI","CI/CD","развертывание в производстве","тестирование развертывания"],"ar":["توزيع سحابي","Cloudflare Workers","Supabase Edge Functions","Wrangler","Supabase CLI","CI/CD","تثبيت في الإنتاج","اختبار التثبيت"]}},"owner":"AndrijaSkontra","repo":"ai-driven-project-template","repoPath":"AndrijaSkontra/ai-driven-project-template","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.510Z","topics":[],"category":"community","skillMd":{"name":"deployment","description":"Deploy applications to Cloudflare Workers and/or Supabase Edge Functions. Supports unified multi-platform deployment. Use when deploying to production, publishing APIs/functions, or when user requests deployment.","bodyPreview":"# Unified Deployment Skill\n\nThis skill handles deployment to multiple platforms:\n\n- **Cloudflare Workers**: API application (Hono) deployment via Wrangler\n- **Supabase Edge Functions**: Serverless functions (Deno) deployment via Supabase CLI\n- **Both**: Deploy to both platforms simultaneously\n\n## When to Use\n\n- Deploying to production\n- Publishing APIs or functions\n- Setting up CI/CD deployments\n- Testing deployments on feature branches\n\n## Pre-deployment Checklist\n\n### For Cloudflare Workers\n\nB","body":"# Unified Deployment Skill\n\nThis skill handles deployment to multiple platforms:\n\n- **Cloudflare Workers**: API application (Hono) deployment via Wrangler\n- **Supabase Edge Functions**: Serverless functions (Deno) deployment via Supabase CLI\n- **Both**: Deploy to both platforms simultaneously\n\n## When to Use\n\n- Deploying to production\n- Publishing APIs or functions\n- Setting up CI/CD deployments\n- Testing deployments on feature branches\n\n## Pre-deployment Checklist\n\n### For Cloudflare Workers\n\nBefore deploying to Cloudflare, verify:\n\n1. Environment variables in .env:\n   - `CLOUDFLARE_API` (API token)\n   - `CLOUDFLARE_ACCOUNT_ID` (Account ID)\n2. `wrangler.jsonc` configuration is valid\n3. Dependencies installed in `apps/api` (`bun install`)\n4. Bun is installed\n\n### For Supabase Edge Functions\n\nBefore deploying to Supabase, verify:\n\n1. Environment variables in .env:\n   - `SUPABASE_URL` (Project URL)\n   - `SUPABASE_PROJECT_REF` (Project reference ID)\n2. Supabase CLI is installed (`npm install -g supabase` or `brew install supabase/tap/supabase`)\n3. Logged into Supabase CLI (`supabase login`)\n4. Project is linked (script will attempt to link automatically)\n5. Functions exist in `supabase/functions/` directory\n\n## Branch-Based Deployments\n\nThe deployment skill automatically detects your git branch and deploys accordingly:\n\n### Branch Detection\n\n| Branch            | Environment | Description                       |\n| ----------------- | ----------- | --------------------------------- |\n| `main` / `master` | Production  | Deploys to production resources   |\n| Any other branch  | Preview     | Creates branch-specific resources |\n\n### Cloudflare Workers Branch Naming\n\nFeature branches deploy to separate workers with sanitized names:\n\n| Git Branch          | Worker Name             | URL                                           |\n| ------------------- | ----------------------- | --------------------------------------------- |\n| `main`              | `api`                   | `https://api.*.workers.dev`                   |\n| `feature/user-auth` | `api-feature-user-auth` | `https://api-feature-user-auth.*.workers.dev` |\n| `fix/login-bug`     | `api-fix-login-bug`     | `https://api-fix-login-bug.*.workers.dev`     |\n\n**Naming Rules:**\n\n- Max 63 characters (DNS limit)\n- Only lowercase alphanumeric and hyphens\n- Slashes and underscores converted to hyphens\n- Leading/trailing hyphens removed\n\n### Supabase Preview Branches\n\nFor feature branches, the script:\n\n1. Checks if a Supabase preview branch exists\n2. Prompts to create one if it doesn''t\n3. Deploys functions to the branch environment\n\n**Important:** Supabase preview branches have their own:\n\n- Project reference (different URL)\n- `anon` API key\n- `service_role` API key\n- Isolated database\n\nAfter deploying to a Supabase branch, run the following to get credentials:\n\n```bash\nsupabase branches get <branch-name> --project-ref $SUPABASE_PROJECT_REF\n```\n\n### Cleanup Commands\n\n**Delete Cloudflare Preview Worker:**\n\n```bash\nwrangler delete --name api-feature-user-auth\n```\n\n**Delete Supabase Preview Branch:**\n\n```bash\nsupabase branches delete feature-user-auth --project-ref $SUPABASE_PROJECT_REF\n```\n\n### Connecting Cloudflare to Supabase Branches\n\nWhen your Cloudflare Worker connects to Supabase, and you deploy to a feature branch:\n\n1. The Cloudflare Worker deploys as `api-<branch-name>`\n2. You need to update the worker''s environment variables with the branch-specific Supabase credentials\n\n**Option 1: Use Wrangler Secrets (Recommended)**\n\n```bash\n# Get branch credentials\nsupabase branches get feature-user-auth --project-ref $SUPABASE_PROJECT_REF\n\n# Set secrets on branch worker\nwrangler secret put SUPABASE_URL --name api-feature-user-auth\nwrangler secret put SUPABASE_ANON_KEY --name api-feature-user-auth\n```\n\n**Option 2: Use separate .dev.vars files**\nCreate branch-specific local configuration for testing.\n\n## Deployment Process\n\n### Step 1: Environment Verification\n\n- Read the .env file from project root to verify credentials exist\n- Check platform-specific environment variables based on deployment target\n\n### Step 2: Execute Deployment Script\n\nThe unified deployment script supports interactive platform selection.\n\nChoose the appropriate script based on the user''s platform:\n\n**For Unix/Mac/Linux:**\n\n```bash\n.claude/skills/deployment/scripts/deploy.sh\n```\n\n**For Windows PowerShell:**\n\n```powershell\n.claude/skills/deployment/scripts/deploy.ps1\n```\n\n**Automated Deployment (Non-interactive):**\nSet `DEPLOY_TARGET` environment variable to skip interactive prompt:\n\n```bash\n# Deploy to Cloudflare only\nDEPLOY_TARGET=cloudflare .claude/skills/deployment/scripts/deploy.sh\n\n# Deploy to Supabase only\nDEPLOY_TARGET=supabase .claude/skills/deployment/scripts/deploy.sh\n\n# Deploy to both platforms\nDEPLOY_TARGET=both .claude/skills/deployment/scripts/deploy.sh\n```\n\n### Step 3: Platform Selection\n\nIf running interactively, the script will prompt:\n\n```\nSelect deployment platform:\n  1) Cloudflare Workers\n  2) Supabase Edge Functions\n  3) Both platforms\n\nEnter choice [1-3]:\n```\n\n### Step 4: Deployment Execution\n\n**Cloudflare Workers:**\n\n- Navigate to `apps/api` directory\n- Execute `bun run deploy`\n- Deploy with Wrangler and minification\n- Return deployment URL (format: `https://api.*.workers.dev`)\n\n**Supabase Edge Functions:**\n\n- Navigate to project root\n- Link project if not already linked\n- Execute `supabase functions deploy`\n- Deploy all functions in `supabase/functions/`\n- Return functions URL (format: `https://<ref>.supabase.co/functions/v1/`)\n\n### Step 5: Verify Deployment Success\n\n- Check the output for success messages\n- Display deployment URLs for each platform\n- Show deployment summary\n- Report any errors encountered\n\n## Error Handling\n\n### Cloudflare Workers Errors\n\n- **Missing .env file**: Prompt user to create `.env` with required Cloudflare variables\n- **Invalid API token**: Direct user to https://dash.cloudflare.com/profile/api-tokens\n  - Token needs \"Workers Scripts > Edit\" permission\n- **Wrangler errors**: Display full error and check:\n  - API token permissions\n  - Account ID is correct\n  - Network connectivity\n- **Bun not found**: Install from https://bun.sh\n- **node_modules missing**: Run `bun install` in `apps/api`\n\n### Supabase Edge Functions Errors\n\n- **Supabase CLI not installed**: Install via:\n  - `npm install -g supabase`\n  - `brew install supabase/tap/supabase` (Mac)\n  - `scoop install supabase` (Windows with Scoop)\n- **Not logged in**: Run `supabase login` to authenticate\n- **Project not linked**: Script will attempt auto-linking with `SUPABASE_PROJECT_REF`\n  - If fails, run manually: `supabase link --project-ref <ref>`\n- **Missing SUPABASE_PROJECT_REF**: Add to .env file\n- **Functions directory not found**: Ensure `supabase/functions/` exists with function subdirectories\n\n## Environment Variables Reference\n\n### Cloudflare Workers\n\n```bash\nCLOUDFLARE_API=\"your-api-token\"\nCLOUDFLARE_ACCOUNT_ID=\"your-account-id\"\n```\n\n### Supabase Edge Functions\n\n```bash\nSUPABASE_URL=\"https://your-ref.supabase.co\"\nSUPABASE_PROJECT_REF=\"your-ref\"\nSUPABASE_ANON_KEY=\"your-anon-key\"  # Optional, for API integration\nSUPABASE_SERVICE_ROLE_KEY=\"your-service-key\"  # Optional, for admin operations\n```\n\n## Safety Guidelines\n\n- Always verify environment variables before deploying\n- Show user what platform(s) will be deployed to\n- Report deployment URLs after successful deploy\n- Keep .env file secure and never commit it\n- Supabase service role keys should NEVER be exposed publicly\n- Test locally before deploying to production\n\n## Available Endpoints After Deployment\n\n### Cloudflare Workers API\n\n- **Base URL**: `https://api.*.workers.dev`\n- **Health Check**: `GET /`\n- **Database Test**: `GET /db-test` (tests Supabase connection)\n\n### Supabase Edge Functions\n\n- **Base URL**: `https://<ref>.supabase.co/functions/v1`\n- **Hello World**: `GET /hello-world` or `POST /hello-world`\n"},"lastSynced":"2026-03-08T02:10:25.642Z","agentAnalysis":{"suitability":{"en":"Perfect for Cloud-Native Agents needing unified deployment to Cloudflare Workers and Supabase Edge Functions.","zh":"适用于需要统一部署到Cloudflare Workers和Supabase Edge Functions的云原生代理。","ja":"Cloudflare WorkersおよびSupabase Edge Functionsへの統一デプロイが必要なクラウドネイティブエージェントに適しています。","ko":"Cloudflare Workers와 Supabase Edge Functions에 대한統一 배포가 필요한 클라우드 네이티브 에이전트에 적합합니다.","es":"Perfecto para Agentes Nativos en la Nube que necesitan una implementación unificada en Cloudflare Workers y Supabase Edge Functions.","fr":"Parfait pour les agents Cloud-Native nécessitant un déploiement unifié vers Cloudflare Workers et Supabase Edge Functions.","de":"Perfekt für Cloud-Native-Agents, die eine einheitliche Bereitstellung in Cloudflare Workers und Supabase Edge Functions benötigen.","pt":"Perfeito para Agentes Cloud-Native que necessitam de implantação unificada para Cloudflare Workers e Supabase Edge Functions.","ru":"Идеально подходит для облачных агентов, которым требуется унифицированное развертывание в Cloudflare Workers и Supabase Edge Functions.","ar":"مثالي للوكلاء الأصليين السحابي الذين يحتاجون إلى توزيع موحد إلى Cloudflare Workers و Supabase Edge Functions."},"recommendation":{"en":"Empowers agents to deploy APIs and serverless functions via Wrangler and Supabase CLI, supporting simultaneous deployment to both platforms with protocols like CI/CD.","zh":"赋予代理部署API和无服务器函数的能力，通过Wrangler和Supabase CLI支持同时部署到两个平台，采用CI/CD等协议。","ja":"エージェントにAPIおよびサーバーレス関数をデプロイする能力を与え、WranglerおよびSupabase CLIを使用してCI/CDなどのプロトコルで両方のプラットフォームに同時にデプロイすることをサポートします。","ko":"에이전트에 API 및 서버리스 함수를 배포할 수 있는 능력을 부여하며, Wrangler 및 Supabase CLI를 사용하여 CI/CD 등의 프로토콜로 두 플랫폼에 동시에 배포할 수 있도록 지원합니다.","es":"Habilita a los agentes a implementar API y funciones sin servidor a través de Wrangler y Supabase CLI, admitiendo la implementación simultánea en ambas plataformas con protocolos como CI/CD.","fr":"Permet aux agents de déployer des API et des fonctions sans serveur via Wrangler et Supabase CLI, en prenant en charge le déploiement simultané sur les deux plateformes avec des protocoles tels que CI/CD.","de":"Ermöglicht es Agents, APIs und serverlose Funktionen über Wrangler und Supabase CLI bereitzustellen, wobei die simultane Bereitstellung auf beiden Plattformen mit Protokollen wie CI/CD unterstützt wird.","pt":"Habilita os agentes a implantar APIs e funções sem servidor via Wrangler e Supabase CLI, suportando implantação simultânea em ambas as plataformas com protocolos como CI/CD.","ru":"Наделяет агентов возможностью развертывать API и бессерверные функции через Wrangler и Supabase CLI, поддерживая одновременное развертывание на обеих платформах с протоколами типа CI/CD.","ar":"تمكين الوكلاء من نشر APIs ووظائف خالية من الخادم عبر Wrangler و Supabase CLI ، ودعم التوزيع المتزامن على كلا المنصتين ببروتوكولات مثل CI/CD."},"useCases":{"en":["Deploying API applications to Cloudflare Workers","Publishing serverless functions to Supabase Edge Functions","Setting up automated CI/CD deployments for feature branches"],"zh":["将API应用程序部署到Cloudflare Workers","将服务器函数发布到Supabase Edge Functions","为功能分支设置自动化的CI/CD部署"],"ja":["APIアプリケーションをCloudflare Workersにデプロイする","サーバーレス関数をSupabase Edge Functionsに公開する","機能ブランチの自動CI/CDデプロイを設定する"],"ko":["API 애플리케이션을 Cloudflare Workers에 배포하는 것","서버리스 함수를 Supabase Edge Functions에 게시하는 것","기능 분기에 대한 자동화된 CI/CD 배포를 설정하는 것"],"es":["Implementar aplicaciones de API en Cloudflare Workers","Publicar funciones sin servidor en Supabase Edge Functions","Configurar implementaciones de CI/CD automatizadas para ramas de características"],"fr":["Déployer des applications d''API sur Cloudflare Workers","Publier des fonctions sans serveur sur Supabase Edge Functions","Configurer des déploiements CI/CD automatisés pour les branches de fonctionnalités"],"de":["API-Anwendungen in Cloudflare Workers bereitstellen","Serverlose Funktionen in Supabase Edge Functions veröffentlichen","Automatisierte CI/CD-Bereitstellungen für Funktionszweige einrichten"],"pt":["Implantação de aplicações API em Cloudflare Workers","Publicação de funções sem servidor em Supabase Edge Functions","Configuração de implantações automatizadas CI/CD para branches de recursos"],"ru":["Развертывание приложений API в Cloudflare Workers","Публикация бессерверных функций в Supabase Edge Functions","Настройка автоматических развертываний CI/CD для веток функций"],"ar":["توزيع تطبيقات API على Cloudflare Workers","نشر دوال خالية من الخادم إلى Supabase Edge Functions","إعداد توزيعات CI/CD التلقائية لفرع الميزات"]},"limitations":{"en":["Requires Wrangler for Cloudflare Workers","Requires Supabase CLI for Supabase Edge Functions","Limited to Cloudflare Workers and Supabase Edge Functions"],"zh":["需要Wrangler用于Cloudflare Workers","需要Supabase CLI用于Supabase Edge Functions","仅限Cloudflare Workers和Supabase Edge Functions"],"ja":["Cloudflare WorkersではWranglerが必要","Supabase Edge FunctionsではSupabase CLIが必要","Cloudflare WorkersおよびSupabase Edge Functionsのみ"],"ko":["Cloudflare Workers에서는 Wrangler가 필요합니다","Supabase Edge Functions에서는 Supabase CLI가 필요합니다","Cloudflare Workers 및 Supabase Edge Functions만"],"es":["Requiere Wrangler para Cloudflare Workers","Requiere Supabase CLI para Supabase Edge Functions","Limitado a Cloudflare Workers y Supabase Edge Functions"],"fr":["Nécessite Wrangler pour Cloudflare Workers","Nécessite Supabase CLI pour Supabase Edge Functions","Limité à Cloudflare Workers et Supabase Edge Functions"],"de":["Benötigt Wrangler für Cloudflare Workers","Benötigt Supabase CLI für Supabase Edge Functions","Begrenzt auf Cloudflare Workers und Supabase Edge Functions"],"pt":["Requer Wrangler para Cloudflare Workers","Requer Supabase CLI para Supabase Edge Functions","Limitado a Cloudflare Workers e Supabase Edge Functions"],"ru":["Требует Wrangler для Cloudflare Workers","Требует Supabase CLI для Supabase Edge Functions","Ограничен Cloudflare Workers и Supabase Edge Functions"],"ar":["يتطلب Wrangler من أجل Cloudflare Workers","يتطلب Supabase CLI من أجل Supabase Edge Functions","محدود ب Cloudflare Workers و Supabase Edge Functions"]},"version":4},"contentHash":"d2b8fadf64b801fdc7f792307c77ce517a1292be1e96083bf9cd03ae611b1769","qualityScore":57}');
