INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('AndrijaSkontra/ai-driven-project-template/deployment', 'deployment', 'AndrijaSkontra', 'ai-driven-project-template', 'community', 'deployment AndrijaSkontra ai-driven-project-template community The deployment skill handles unified deployment to multiple platforms, benefiting developers who need to deploy APIs and serverless functions to Cloudflare Workers and Supabase Edge Functions. 统一部署技能支持同时部署到Cloudflare Workers和Supabase Edge Functions，使用Wrangler和Supabase CLI实现自动化部署 統一デプロイメントスキルは、Cloudflare WorkersとSupabase Edge Functionsへの同時デプロイをサポートし、WranglerとSupabase CLIを使用して自動化されたデプロイメントを実現します 통합 배포 스킬은 Cloudflare Workers와 Supabase Edge Functions에 대한 동시 배포를 지원하며 Wrangler와 Supabase CLI를 사용하여 자동화된 배포를 구현합니다 El despliegue de AI Agent permite implementar aplicaciones en Cloudflare Workers y Supabase Edge Functions de manera simultánea Le déploiement d''Agent IA permet de déployer des applications sur Cloudflare Workers et Supabase Edge Functions de manière simultanée Die Bereitstellung von AI-Agent ermöglicht die Implementierung von Anwendungen in Cloudflare Workers und Supabase Edge Functions gleichzeitig O skill de implantação permite implantar aplicações em nuvem em Cloudflare Workers e Supabase Edge Functions. Aprenda a configurar e implantar APIs e funções de forma eficiente Навык развертывания позволяет развертывать приложения в облаке в Cloudflare Workers и Supabase Edge Functions. Узнайте, как настроить и развернуть API и функции эффективно مهارة التوزيع تسمح بتوزيع التطبيقات السحابية في Cloudflare Workers و Supabase Edge Functions. تعلم كيفية تثبيت وتنفيذ واجهات برمجة التطبيقات والدوال بفعالية how to use deployment deployment setup guide Cloudflare Workers deployment Supabase Edge Functions deployment deployment vs traditional hosting unified deployment strategy deployment best practices CI/CD deployment tutorial serverless function deployment 部署设置 Cloudflare Workers Supabase Edge Functions Wrangler Supabase CLI CI/CD 自动化测试 AI工具 AIエージェント Deploys API applications (Hono) to Cloudflare Workers via Wrangler Deploys serverless functions (Deno) to Supabase Edge Functions via Supabase CLI Supports simultaneous deployment to both Cloudflare Workers and Supabase Edge Functions Enables deployment to production, publishing APIs or functions, and setting up CI/CD deployments Allows testing deployments on feature branches Deployment is the process of releasing software applications or functions to production environments, such as Cloudflare Workers and Supabase Edge Functions, using tools like Wrangler and Supabase CLI');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('deadlock-mod-manager/deadlock-mod-manager/opensrc', 'community', 'deadlock-mod-manager', 'deadlock-mod-manager', 'deadlock-mod-manager/deadlock-mod-manager', 'opensrc', 0, 0, 57, '2026-03-08T01:57:15.517Z', '2026-03-08T02:10:35.889Z', 'ceb02950c4a30434297d257c8bb9ab6bb3322ca9461b5020988fcb6b43dfbd65', '{"id":"deadlock-mod-manager/deadlock-mod-manager/opensrc","name":"opensrc","description":{"en":"opensrc is a CLI tool that fetches source code for packages and repositories, providing AI coding agents with deeper implementation context. It helps developers understand library internals and debug issues.","zh":"opensrc是一个CLI工具，用于获取包/仓库的源代码，为AI编码代理提供更深入的实现背景","ja":"opensrcは、AIエージェントに更に深い実装背景を提供するためのCLIツールです。パッケージ/リポジトリのソースコードを取得します","ko":"opensrc는 AI 에이전트에게 更に 깊은 구현 배경을 제공하는 CLI 도구입니다. 패키지/리포지토리의 소스 코드를 가져옵니다","es":"opensrc es una herramienta de línea de comandos para recuperar el código fuente de paquetes y repositorios, lo que permite a los agentes de inteligencia artificial una comprensión más profunda del contexto de implementación","fr":"opensrc est un outil en ligne de commande pour récupérer le code source des paquets et des référentiels, ce qui permet aux outils d''IA de mieux comprendre le contexte de mise en œuvre","de":"opensrc ist ein CLI-Tool zum Abrufen des Quellcodes von Paketen und Repositorien, um KI-Agents eine tiefere Implementierungskontext zu ermöglichen","pt":"O opensrc é uma ferramenta CLI que permite acessar o código-fonte de pacotes, fornecendo contexto de implementação para agentes de codificação de IA.","ru":"Opensrc — это инструмент CLI, который позволяет получить исходный код пакетов, предоставляя контекст реализации для ИИ агентов.","ar":"opensrc هي أداة سطر الأوامر تتيح الوصول إلى код المصدر للحزم، مما يوفر سياق التنفيذ للوكلاء الذكيين."},"seo":{"title":{"en":"opensrc: CLI Tool for AI Agents | Fetch Source Code","zh":"opensrc Setup Guide: AI编码代理的CLI工具","ja":"opensrc セットアップガイド: AIエージェントのためのCLIツール","ko":"opensrc 설정 가이드: AI 에이전트를 위한 CLI 도구","es":"Guía de configuración de opensrc para agentes de intelige...","fr":"Guide d''installation d''opensrc pour les outils d''IA","de":"Einrichtungsleitfaden für opensrc zur Verbesserung von KI...","pt":"Guia de Configuração do opensrc: Ferramenta CLI para Códi...","ru":"Настройка opensrc: Инструмент CLI для Получения Исходного...","ar":"دليل إعداد opensrc: أداة سطر الأوامر للوصول إلى код المصد..."},"description":{"en":"Unlock deeper implementation context with opensrc. Learn how to fetch source code for packages and repos with this mod manager for Deadlock.","zh":"了解opensrc的功能和特点，了解如何使用CLI工具来获取包/仓库的源代码","ja":"opensrcの機能と特徴を紹介します。CLIツールを使用してパッケージ/リポジトリのソースコードを取得する方法を学びましょう","ko":"opensrc의 기능과 특징을紹介합니다. CLI 도구를 사용하여 패키지/리포지토리의 소스 코드를 가져오는 방법을 알아보세요","es":"Descubre cómo opensrc te ayuda a entender el código fuente de paquetes y repositorios para mejorar la implementación de tus agentes de inteligencia artificial","fr":"Découvrez comment opensrc vous aide à comprendre le code source des paquets et des référentiels pour améliorer la mise en œuvre de vos outils d''IA","de":"Erfahren Sie, wie opensrc Ihnen hilft, den Quellcode von Paketen und Repositorien zu verstehen, um die Implementierung Ihrer KI-Agents zu verbessern","pt":"Aprenda a usar o opensrc, uma ferramenta CLI que fornece contexto de implementação para agentes de codificação de IA, ajudando a depurar e entender bibliotecas.","ru":"Узнайте, как использовать opensrc, инструмент CLI, который предоставляет контекст реализации для ИИ агентов, помогающий отлаживать и понимать библиотеки.","ar":"تعرف على كيفية استخدام opensrc، أداة سطر الأوامر التي توفر سياق التنفيذ للوكلاء الذكيين، مما يساعد على تصحيح الأخطاء وفهم المكتبات."},"definition":{"en":"opensrc is a command-line interface tool designed to fetch source code for packages and repositories, giving AI coding agents deeper implementation context.","zh":"opensrc是一种CLI工具，用于获取包/仓库的源代码","ja":"opensrcは、パッケージ/リポジトリのソースコードを取得するCLIツールです","ko":"opensrc는 패키지/리포지토리의 소스 코드를 가져오는 CLI 도구입니다","es":"opensrc es una herramienta de código abierto que permite a los agentes de inteligencia artificial acceder al código fuente de paquetes y repositorios","fr":"opensrc est un outil open source qui permet aux outils d''IA d''accéder au code source des paquets et des référentiels","de":"opensrc ist ein Open-Source-Tool, das es KI-Agents ermöglicht, auf den Quellcode von Paketen und Repositorien zuzugreifen","pt":"O opensrc é uma ferramenta de linha de comando que fornece acesso ao código-fonte de pacotes.","ru":"Opensrc — это инструмент командной строки, который предоставляет доступ к исходному коду пакетов.","ar":"opensrc هي أداة سطر الأوامر توفر الوصول إلى код المصدر للحزم."},"features":{"en":["Fetches source code for npm packages using the npm install command","Auto-detects installed packages for seamless integration","Provides deeper implementation context for AI coding agents","Supports debugging issues where types alone are insufficient","Enables exploration of implementation patterns in dependencies","References actual source code of a package for accurate analysis"],"zh":["支持获取npm包的源代码","自动检测包的依赖关系","支持调试和探索实现模式","提供更深入的实现背景"],"ja":["npmパッケージのソースコードを取得可能","パッケージの依存関係を自動で検出","デバッグと実装パターンの探索をサポート","更に深い実装背景を提供"],"ko":["npm 패키지의 소스 코드를 가져올 수 있음","패키지의 의존 관계를 자동으로 감지","디버깅과 구현 패턴의 탐색을 지원","更に 깊은 구현 배경을 제공"],"es":["Recuperación del código fuente de paquetes y repositorios","Mejora de la comprensión del contexto de implementación para agentes de inteligencia artificial","Compatibilidad con npm y otros gestores de paquetes","Uso de la línea de comandos para una integración fácil","Permite a los desarrolladores depurar problemas de implementación","Facilita la exploración de patrones de implementación en dependencias"],"fr":["Récupération du code source des paquets et des référentiels","Amélioration de la compréhension du contexte de mise en œuvre pour les outils d''IA","Compatibilité avec npm et d''autres gestionnaires de paquets","Utilisation de la ligne de commande pour une intégration facile","Permet aux développeurs de déboguer les problèmes de mise en œuvre","Facilite l''exploration des modèles de mise en œuvre dans les dépendances"],"de":["Abrufen des Quellcodes von Paketen und Repositorien","Verbesserung des Verständnisses des Implementierungskontexts für KI-Agents","Kompatibilität mit npm und anderen Paketmanagern","Verwendung der Kommandozeile für eine einfache Integration","Ermöglicht Entwicklern, Implementierungsprobleme zu debuggen","Erleichtert die Erforschung von Implementierungsmustern in Abhängigkeiten"],"pt":["Fornece contexto de implementação para agentes de codificação de IA","Permite depurar problemas onde os tipos alone são insuficientes","Explora padrões de implementação em dependências","Referencia o código-fonte real de um pacote"],"ru":["Предоставляет контекст реализации для ИИ агентов","Позволяет отлаживать проблемы, где типы alone недостаточны","Изучает паттерны реализации в зависимостях","Ссылается на фактический исходный код пакета"],"ar":["توفر سياق التنفيذ للوكلاء الذكيين","تسمح بتصحيح الأخطاء حيث أن الأنواع وحدها غير كافية","تستكشف أنماط التنفيذ في الإعتماديات","ترجع إلى код المصدر الفعلي للحزمة"]},"keywords":{"en":["how to use opensrc","what is opensrc","opensrc alternative","opensrc vs mod manager","opensrc install","opensrc setup guide","fetch source code","npm package manager","AI coding agents"],"zh":["opensrc","AI编码代理","CLI工具","源代码获取","npm包","依存关系","调试","实现模式"],"ja":["opensrc","AIエージェント","CLIツール","ソースコード取得","npmパッケージ","依存関係","デバッグ","実装パターン"],"ko":["opensrc","AI 에이전트","CLI 도구","소스 코드 가져오기","npm 패키지","의존 관계","디버깅","구현 패턴"],"es":["opensrc","agentes de inteligencia artificial","código fuente","paquetes","repositorios","npm","CLI","implementación","depuración","patrones de implementación"],"fr":["opensrc","outils d''IA","code source","paquets","référentiels","npm","CLI","mise en œuvre","débogage","modèles de mise en œuvre"],"de":["opensrc","KI-Agents","Quellcode","Pakete","Repositorien","npm","CLI","Implementierung","Fehlerbehebung","Implementierungsmuster"],"pt":["opensrc","ferramenta CLI","código-fonte de pacotes","agentes de codificação de IA","depuração de problemas","padrões de implementação"],"ru":["opensrc","инструмент CLI","исходный код пакетов","ИИ агенты","отладка проблем","паттерны реализации"],"ar":["opensrc","أداة سطر الأوامر","كود المصدر للحزم","الوكلاء الذكيين","تصحيح الأخطاء","أنماط التنفيذ"]}},"owner":"deadlock-mod-manager","repo":"deadlock-mod-manager","repoPath":"deadlock-mod-manager/deadlock-mod-manager","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.517Z","topics":[],"category":"community","skillMd":{"name":"opensrc","description":"Fetch source code for npm, PyPI, or crates.io packages and GitHub/GitLab repos to provide AI agents with implementation context beyond types and docs. Use when needing to understand how a library works internally, debug dependency issues, or explore package implementations.","bodyPreview":"# opensrc\n\nCLI tool to fetch source code for packages/repos, giving AI coding agents deeper implementation context.\n\n## When to Use\n\n- Need to understand how a library/package works internally (not just its interface)\n- Debugging issues where types alone are insufficient\n- Exploring implementation patterns in dependencies\n- Agent needs to reference actual source code of a package\n\n## Quick Start\n\n```bash\n# Install globally or use npx\nnpm install -g opensrc\n\n# Fetch npm package (auto-detects inst","body":"# opensrc\n\nCLI tool to fetch source code for packages/repos, giving AI coding agents deeper implementation context.\n\n## When to Use\n\n- Need to understand how a library/package works internally (not just its interface)\n- Debugging issues where types alone are insufficient\n- Exploring implementation patterns in dependencies\n- Agent needs to reference actual source code of a package\n\n## Quick Start\n\n```bash\n# Install globally or use npx\nnpm install -g opensrc\n\n# Fetch npm package (auto-detects installed version from lockfile)\nnpx opensrc zod\n\n# Fetch from other registries\nnpx opensrc pypi:requests       # Python/PyPI\nnpx opensrc crates:serde        # Rust/crates.io\n\n# Fetch GitHub repo directly\nnpx opensrc vercel/ai           # owner/repo shorthand\nnpx opensrc github:owner/repo   # explicit prefix\nnpx opensrc https://github.com/colinhacks/zod  # full URL\n\n# Fetch specific version/ref\nnpx opensrc zod@3.22.0\nnpx opensrc owner/repo@v1.0.0\n```\n\n## Commands\n\n| Command                 | Description                     |\n| ----------------------- | ------------------------------- |\n| `opensrc <packages...>` | Fetch source for packages/repos |\n| `opensrc list`          | List all fetched sources        |\n| `opensrc remove <name>` | Remove specific source          |\n| `opensrc clean`         | Remove all sources              |\n\n## Output Structure\n\nAfter fetching, sources stored in `opensrc/` directory:\n\n```\nopensrc/\n├── settings.json           # User preferences\n├── sources.json            # Index of fetched packages/repos\n└── repos/\n    └── github.com/\n        └── owner/\n            └── repo/       # Cloned source code\n```\n\n## File Modifications\n\nOn first run, opensrc prompts to modify:\n\n- `.gitignore` - adds `opensrc/` to ignore list\n- `tsconfig.json` - excludes `opensrc/` from compilation\n- `AGENTS.md` - adds section pointing agents to source code\n\nUse `--modify` or `--modify=false` to skip prompt.\n\n## Key Behaviors\n\n1. **Version Detection** - For npm, auto-detects installed version from `node_modules`, `package-lock.json`, `pnpm-lock.yaml`, or `yarn.lock`\n2. **Repository Resolution** - Resolves package to its git repo via registry API, clones at matching tag\n3. **Monorepo Support** - Handles packages in monorepos via `repository.directory` field\n4. **Shallow Clone** - Uses `--depth 1` for efficient cloning, removes `.git` after clone\n5. **Tag Fallback** - Tries `v{version}`, `{version}`, then default branch if tag not found\n\n## Common Workflows\n\n### Fetching a Package\n\n```bash\n# Agent needs to understand zod''s implementation\nnpx opensrc zod\n# → Detects version from lockfile\n# → Finds repo URL from npm registry\n# → Clones at matching git tag\n# → Source available at opensrc/repos/github.com/colinhacks/zod/\n```\n\n### Updating Sources\n\n```bash\n# Re-run same command to update to currently installed version\nnpx opensrc zod\n# → Checks if version changed\n# → Re-clones if needed\n```\n\n### Multiple Sources\n\n```bash\n# Fetch multiple at once\nnpx opensrc react react-dom next\nnpx opensrc zod pypi:pydantic vercel/ai\n```\n\n## References\n\nFor detailed information:\n\n- [CLI Usage & Options](references/cli-usage.md) - Full command reference\n- [Architecture](references/architecture.md) - Code structure and extension\n- [Registry Support](references/registry-support.md) - npm, PyPI, crates.io details\n"},"lastSynced":"2026-03-08T02:10:35.889Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Coding Agents requiring in-depth library implementation analysis and debugging capabilities.","zh":"适合需要对库进行深入实现分析和调试能力的AI编码代理。","ja":"AIコーディングエージェントがライブラリの実装分析とデバッグ機能を深入して行う必要がある場合に最適です。","ko":"라이브러리 구현 분석 및 디버깅 기능에 대한 심층적인 분석이 필요한 AI 코딩 에이전트에 적합합니다.","es":"Ideal para Agentes de Codificación de IA que requieren un análisis de implementación de bibliotecas en profundidad y capacidades de depuración.","fr":"Idéal pour les agents de codage IA nécessitant une analyse de mise en œuvre de bibliothèque en profondeur et des capacités de débogage.","de":"Ideal für AI-Coding-Agents, die eine tiefgehende Bibliotheksimplementierungsanalyse und Debugging-Fähigkeiten erfordern.","pt":"Ideal para Agentes de Codificação de IA que exigem análise de implementação de bibliotecas em profundidade e capacidades de depuração.","ru":"Идеально для агентов кодирования ИИ, требующих глубокого анализа реализации библиотек и возможностей отладки.","ar":"مثالي لعميل الترميز الاصطناعي الذي يتطلب تحليل تنفيذ مكتبات متعمق وقدرات فحص الأخطاء."},"recommendation":{"en":"Empowers agents to fetch source code for packages and repositories, providing deeper implementation context through CLI tool integration, enabling the analysis of library internals and debugging issues beyond types alone, leveraging npm packages and repository source code.","zh":"赋予代理从包和存储库中获取源代码的能力，通过CLI工具集成提供更深入的实现背景，实现库内部和类型以外问题的分析和调试，利用npm包和存储库源代码。","ja":"エージェントがパッケージやリポジトリからソースコードを取得する能力を提供し、CLIツールの統合を通じて実装の詳細な背景を提供し、ライブラリ内部や型以外の問題の分析やデバッグを可能にし、npmパッケージやリポジトリのソースコードを利用します。","ko":"에이전트가 패키지 및 리포지토리에서 소스 코드를 가져올 수 있는 기능을 제공하여 CLI 도구 통합을 통해 구현에 대한 더 깊은 이해를 제공하고, 라이브러리 내부 및 유형 외의 문제에 대한 분석 및 디버깅을 가능하게 하며, npm 패키지 및 리포지토리 소스 코드를 활용합니다.","es":"Habilita a los agentes a obtener el código fuente de paquetes y repositorios, proporcionando un contexto de implementación más profundo a través de la integración de herramientas CLI, lo que permite el análisis de los internos de la biblioteca y la depuración de problemas más allá de los tipos solos, aprovechando los paquetes npm y el código fuente del repositorio.","fr":"Permet aux agents de récupérer le code source des packages et des référentiels, fournissant un contexte de mise en œuvre plus approfondi via l''intégration d''outils CLI, ce qui permet l''analyse des internes de la bibliothèque et le débogage de problèmes au-delà des types seuls, en exploitant les packages npm et le code source du référentiel.","de":"Ermächtigt die Agenten, den Quellcode von Paketen und Repositorys abzurufen und so einen tieferen Implementierungskontext durch die Integration von CLI-Tools bereitzustellen, wodurch die Analyse der Bibliotheksinternas und die Fehlersuche über Typen hinaus ermöglicht wird, indem npm-Pakete und Repository-Quellcode genutzt werden.","pt":"Habilita os agentes a buscar o código-fonte de pacotes e repositórios, fornecendo um contexto de implementação mais profundo por meio da integração de ferramentas CLI, permitindo a análise de internos de bibliotecas e a depuração de problemas além dos tipos, utilizando pacotes npm e código-fonte de repositórios.","ru":"Позволяет агентам получать исходный код пакетов и репозиториев, обеспечивая более глубокий контекст реализации через интеграцию с инструментами CLI, что позволяет анализировать внутреннюю структуру библиотек и исправлять ошибки за пределами типов, используя пакеты npm и исходный код репозиториев.","ar":"تمكين الوكلاء من استرداد رمز المصدر للحزم والمستودعات، مع توفير سياق تنفيذ أعمق من خلال دمج أدوات CLI، مما يتيح تحليل内部 المكتبات وتصحيح المشكلات أبعد من الأنواع، باستخدام حزم npm ورمز المصدر للمستودعات."},"useCases":{"en":["Debugging issues where types alone are insufficient","Exploring implementation patterns in dependencies","Fetching npm package source code for agent reference"],"zh":["类型信息不足时的调试问题","探索依赖关系中的实现模式","为代理引用获取npm包的源代码"],"ja":["型情報だけでは不十分なデバッグ問題","依存関係における実装パターンの探索","エージェントの参照用にnpmパッケージのソースコードを取得"],"ko":["유형 정보만으로는 불충분한 디버깅 문제","의존성에서 구현 패턴을 탐색","에이전트 참조용으로 npm 패키지 소스 코드 가져오기"],"es":["Depuración de problemas donde los tipos solos son insuficientes","Exploración de patrones de implementación en dependencias","Obtención del código fuente de paquetes npm para referencia del agente"],"fr":["Débogage de problèmes où les types seuls sont insuffisants","Exploration de modèles d''implémentation dans les dépendances","Récupération du code source de packages npm pour référence de l''agent"],"de":["Fehlersuche bei Problemen, bei denen die Typen allein unzureichend sind","Erkundung von Implementierungsmustern in Abhängigkeiten","Abrufen des Quellcodes von npm-Paketen für die Referenz des Agents"],"pt":["Depuração de problemas em que os tipos sozinhos são insuficientes","Exploração de padrões de implementação em dependências","Recuperação do código-fonte do pacote npm para referência do agente"],"ru":["Отладка проблем, в которых типы сами по себе недостаточны","Изучение шаблонов реализации в зависимостях","Получение исходного кода пакета npm для справки агента"],"ar":["فحص أخطاء حيث أن الأنواع وحدها غير كافية","استكشاف أنماط التنفيذ في الإعتماديات","استرجاع رمز المصدر لحزمة npm لمرجع الوكيل"]},"limitations":{"en":["Requires npm installation or npx usage","Limited to fetching source code for packages and repositories"],"zh":["需要npm安装或npx使用","仅限于获取包和存储库的源代码"],"ja":["npmのインストールまたはnpxの使用が必要","パッケージやリポジトリのソースコードの取得のみ"],"ko":["npm 설치 또는 npx 사용이 필요","패키지 및 리포지토리 소스 코드 가져오기만 제한"],"es":["Requiere la instalación de npm o el uso de npx","Limitado a la obtención del código fuente de paquetes y repositorios"],"fr":["Nécessite l''installation de npm ou l''utilisation de npx","Limité à la récupération du code source de packages et de référentiels"],"de":["Benötigt die Installation von npm oder die Verwendung von npx","Begrenzt auf das Abrufen des Quellcodes von Paketen und Repositorys"],"pt":["Exige instalação do npm ou uso do npx","Limitado à recuperação do código-fonte para pacotes e repositórios"],"ru":["Требует установки npm или использования npx","Ограничен получением исходного кода для пакетов и репозиториев"],"ar":["يتطلب تركيب npm أو استخدام npx","محدود باسترجاع رمز المصدر للحزم والمستودعات"]},"version":4},"contentHash":"ceb02950c4a30434297d257c8bb9ab6bb3322ca9461b5020988fcb6b43dfbd65","qualityScore":57}');
