INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('deadlock-mod-manager/deadlock-mod-manager/opensrc', 'opensrc', 'deadlock-mod-manager', 'deadlock-mod-manager', 'community', 'opensrc deadlock-mod-manager deadlock-mod-manager community opensrc is a CLI tool that fetches source code for packages and repositories, providing AI coding agents with deeper implementation context. It helps developers understand library internals and debug issues. opensrc是一个CLI工具，用于获取包/仓库的源代码，为AI编码代理提供更深入的实现背景 opensrcは、AIエージェントに更に深い実装背景を提供するためのCLIツールです。パッケージ/リポジトリのソースコードを取得します opensrc는 AI 에이전트에게 更に 깊은 구현 배경을 제공하는 CLI 도구입니다. 패키지/리포지토리의 소스 코드를 가져옵니다 opensrc es una herramienta de línea de comandos para recuperar el código fuente de paquetes y repositorios, lo que permite a los agentes de inteligencia artificial una comprensión más profunda del contexto de implementación opensrc est un outil en ligne de commande pour récupérer le code source des paquets et des référentiels, ce qui permet aux outils d''IA de mieux comprendre le contexte de mise en œuvre opensrc ist ein CLI-Tool zum Abrufen des Quellcodes von Paketen und Repositorien, um KI-Agents eine tiefere Implementierungskontext zu ermöglichen O opensrc é uma ferramenta CLI que permite acessar o código-fonte de pacotes, fornecendo contexto de implementação para agentes de codificação de IA. Opensrc — это инструмент CLI, который позволяет получить исходный код пакетов, предоставляя контекст реализации для ИИ агентов. opensrc هي أداة سطر الأوامر تتيح الوصول إلى код المصدر للحزم، مما يوفر سياق التنفيذ للوكلاء الذكيين. how to use opensrc what is opensrc opensrc alternative opensrc vs mod manager opensrc install opensrc setup guide fetch source code npm package manager AI coding agents opensrc AI编码代理 CLI工具 源代码获取 npm包 依存关系 调试 实现模式 Fetches source code for npm packages using the npm install command Auto-detects installed packages for seamless integration Provides deeper implementation context for AI coding agents Supports debugging issues where types alone are insufficient Enables exploration of implementation patterns in dependencies References actual source code of a package for accurate analysis opensrc is a command-line interface tool designed to fetch source code for packages and repositories, giving AI coding agents deeper implementation context.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lips85/antigravity-skills-bootstrap/kaizen', 'community', 'lips85', 'antigravity-skills-bootstrap', 'lips85/antigravity-skills-bootstrap', 'kaizen', 0, 0, 57, '2026-03-08T01:57:15.550Z', '2026-03-08T02:11:26.961Z', '27535c5b9235cce48b2fb56d7422539dca55c9949d9c26a0d83adeb6ef4d737c', '{"id":"lips85/antigravity-skills-bootstrap/kaizen","name":"kaizen","description":{"en":"Kaizen is a skill that helps developers apply continuous improvement to their code implementation, architecture, and workflows. It prevents errors at design time, ensuring quality through incremental progress.","zh":"Kaizen是一种持续改进的方法，通过小步骤的改进来实现质量的提升","ja":"Kaizenは継続的改善の手法で、小さな改善の積み重ねによって品質を高める","ko":"Kaizen은 지속적인 개선의 방법으로, 작은 단계의 개선을 통해 품질을 향상시킵니다","es":"Kaizen es una filosofía de mejora continua que se aplica a la implementación de código, arquitectura y diseño de procesos. Mejora tu código con pequeñas mejoras continuas","fr":"Kaizen est une philosophie d''amélioration continue qui s''applique à la mise en œuvre de code, d''architecture et de conception de processus. Améliorez votre code avec de petites améliorations continues","de":"Kaizen ist eine Philosophie der kontinuierlichen Verbesserung, die auf die Implementierung von Code, Architektur und Prozessdesign anwendbar ist. Verbessern Sie Ihren Code mit kleinen, kontinuierlichen Verbesserungen","pt":"O Kaizen é uma abordagem de melhoria contínua que se concentra em pequenas mudanças incrementais para melhorar a qualidade e reduzir erros","ru":"Kaizen - это подход к непрерывному улучшению, который фокусируется на небольших инкрементальных изменениях для улучшения качества и снижения ошибок","ar":"Kaizen هو نهج لتحسين مستمر يركز على تحسينات صغيرة ومستمرة لتحسين الجودة وتقليل الأخطاء"},"seo":{"title":{"en":"Kaizen: Continuous Improvement Setup Guide | AI Agent Skill","zh":"Kaizen Setup Guide: 持续改进的AI工具","ja":"Kaizenの設定方法: AIエージェントによる継続的改善","ko":"Kaizen 설정 가이드: 지속적인 개선의 AI 도구","es":"Guía de configuración de Kaizen para mejora continua","fr":"Guide de configuration de Kaizen pour l''amélioration cont...","de":"Kaizen-Setup-Leitfaden für kontinuierliche Verbesserung","pt":"Guia de Configuração Kaizen para Melhoria Contínua","ru":"ИИ Агенты: Руководство по настройке Kaizen для непрерывно...","ar":"دليل إعداد Kaizen لتحسين مستمر مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how Kaizen streamlines Antigravity skill setup with its npx-based bootstrapper. Learn how to apply continuous improvement to your code and workflows.","zh":"了解Kaizen的核心原则和技术细节，实现代码、架构和工作流的持续改进","ja":"Kaizenの哲学と技術的詳細を学び、コード、設計、プロセスの継続的改善を実現する","ko":"Kaizen의 핵심 원칙과 기술적 세부 사항을 학습하여 코드, 아키텍처, 워크플로우의 지속적인 개선을 달성하세요","es":"Aprende a implementar Kaizen en tus proyectos con nuestra guía de configuración y mejora tu código con pequeñas mejoras continuas","fr":"Découvrez comment mettre en œuvre Kaizen dans vos projets avec notre guide de configuration et améliorez votre code avec de petites améliorations continues","de":"Erfahren Sie, wie Sie Kaizen in Ihren Projekten implementieren können, mit unserem Setup-Leitfaden und verbessern Sie Ihren Code mit kleinen, kontinuierliche...","pt":"Aprenda a configurar o Kaizen para melhorar seu fluxo de trabalho com pequenas mudanças contínuas e erradicação de erros","ru":"Узнайте, как настроить Kaizen для улучшения вашего рабочего процесса с помощью небольших изменений и предотвращения ошибок","ar":"تعرف على كيفية إعداد Kaizen لتحسين تدفق العمل الخاص بك من خلال تحسينات صغيرة ومستمرة وتقليل الأخطاء"},"definition":{"en":"Kaizen is a philosophy that emphasizes small, continuous improvements to achieve quality and prevent errors, guiding code implementation, architecture, and workflow decisions.","zh":"Kaizen是一种强调持续改进和错误预防的软件开发方法","ja":"Kaizenは継続的改善とエラー予防を重視するソフトウェア開発手法","ko":"Kaizen은 지속적인 개선과 오류 예방을 강조하는 소프트웨어 개발 방법입니다","es":"Kaizen es una filosofía que busca la mejora continua a través de pequeñas mejoras en la implementación de código, arquitectura y diseño de procesos","fr":"Kaizen est une philosophie qui vise à l''amélioration continue à travers de petites améliorations dans la mise en œuvre de code, d''architecture et de conception de processus","de":"Kaizen ist eine Philosophie, die die kontinuierliche Verbesserung durch kleine Verbesserungen bei der Implementierung von Code, Architektur und Prozessdesign anstrebt","pt":"Kaizen é uma filosofia de melhoria contínua que busca melhorar processos e fluxos de trabalho por meio de pequenas mudanças incrementais","ru":"Kaizen - это философия непрерывного улучшения, которая направлена на улучшение процессов и рабочих потоков посредством небольших инкрементальных изменений","ar":"Kaizen هو فلسفة لتحسين مستمر تهدف إلى تحسين العمليات وتدفقات العمل من خلال تحسينات صغيرة ومستمرة"},"features":{"en":["Applies to code implementation and refactoring","Guides architecture and design decisions","Improves process and workflow efficiency","Enhances error handling and validation","Follows the principle of many small improvements over one big change"],"zh":["代码实现和重构的持续改进","架构和设计决策的优化","过程和工作流的改进","错误处理和验证的增强"],"ja":["コード実装とリファクタリングの継続的改善","設計とアーキテクチャの最適化","プロセスとワークフローの改善","エラー処理とバリデーションの強化"],"ko":["코드 구현과 리팩토링의 지속적인 개선","아키텍처와 설계 결정의 최적화","프로세스와 워크플로우의 개선","오류 처리와 유효성 검사의 강화"],"es":["Implementación de código con enfoque en la mejora continua","Diseño de arquitectura con principios de Kaizen","Procesos y flujos de trabajo mejorados con Kaizen","Manejo de errores y validación con enfoque en la prevención","Aplicación de la filosofía de Kaizen en la refactorización de código"],"fr":["Mise en œuvre de code avec un focus sur l''amélioration continue","Conception d''architecture avec les principes de Kaizen","Processus et flux de travail améliorés avec Kaizen","Gestion des erreurs et validation avec un focus sur la prévention","Application de la philosophie de Kaizen dans la refactorisation de code"],"de":["Implementierung von Code mit Fokus auf kontinuierliche Verbesserung","Architekturdesign mit Kaizen-Prinzipien","Prozesse und Workflows verbessert mit Kaizen","Fehlerbehandlung und Validierung mit Fokus auf Prävention","Anwendung der Kaizen-Philosophie bei der Refaktorisierung von Code"],"pt":["Implementação de código com refatoração contínua","Arquitetura e decisões de design baseadas em melhoria contínua","Melhoria de processos e fluxos de trabalho","Tratamento e validação de erros","Integração com ferramentas de CLI para automação"],"ru":["Реализация кода с непрерывной рефакторингом","Архитектура и решения по дизайну на основе непрерывного улучшения","Улучшение процессов и рабочих потоков","Обработка и валидация ошибок","Интеграция с инструментами CLI для автоматизации"],"ar":["تنفيذ الكود مع إعادة هيكلة مستمرة","هندسة وتصميم بناء على تحسين مستمر","تحسين العمليات وتدفقات العمل","معالجة وتأكيد الأخطاء","التكامل مع أدوات CLI للآليّة"]},"keywords":{"en":["what is kaizen","how to use kaizen","kaizen setup guide","kaizen alternative","kaizen vs agile","kaizen install","continuous improvement methodology","error-proof design","npx-based bootstrapper"],"zh":["Kaizen","持续改进","AI工具","代码优化","架构设计","错误预防","软件开发方法"],"ja":["Kaizen","継続的改善","AIエージェント","コード最適化","設計アーキテクチャ","エラー予防","ソフトウェア開発手法"],"ko":["Kaizen","지속적인 개선","AI 도구","코드 최적화","아키텍처 설계","오류 예방","소프트웨어 개발 방법"],"es":["kaizen","mejora continua","implementación de código","diseño de arquitectura","procesos y flujos de trabajo","manejo de errores","refactorización de código","herramientas de desarrollo","filosofía de desarrollo"],"fr":["kaizen","amélioration continue","mise en œuvre de code","conception d''architecture","processus et flux de travail","gestion des erreurs","refactorisation de code","outils de développement","philosophie de développement"],"de":["kaizen","kontinuierliche Verbesserung","Implementierung von Code","Architekturdesign","Prozesse und Workflows","Fehlerbehandlung","Refaktorisierung von Code","Entwicklungstools","Entwicklungsphilosophie"],"pt":["kaizen","melhoria contínua","refatoração de código","arquitetura de software","fluxo de trabalho","tratamento de erros","ferramentas de CLI","desenvolvimento de software","metodologias ágeis"],"ru":["каizen","непрерывное улучшение","рефакторинг кода","архитектура программного обеспечения","рабочий поток","обработка ошибок","инструменты CLI","разработка программного обеспечения","гибкие методологии"],"ar":["kaizen","تحسين مستمر","إعادة هيكلة الكود","هندسة البرمجيات","تدفق العمل","معالجة الأخطاء","أدوات CLI","تطوير البرمجيات","منهجيات مرنة"]}},"owner":"lips85","repo":"antigravity-skills-bootstrap","repoPath":"lips85/antigravity-skills-bootstrap","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.550Z","topics":[],"category":"community","skillMd":{"name":"kaizen","description":"Guide for continuous improvement, error proofing, and standardization. Use this skill when the user wants to improve code quality, refactor, or discuss process improvements.","bodyPreview":"# Kaizen: Continuous Improvement\n\n## Overview\n\nSmall improvements, continuously. Error-proof by design. Follow what works. Build only what''s needed.\n\n**Core principle:** Many small improvements beat one big change. Prevent errors at design time, not with fixes.\n\n## When to Use\n\n**Always applied for:**\n\n- Code implementation and refactoring\n- Architecture and design decisions\n- Process and workflow improvements\n- Error handling and validation\n\n**Philosophy:** Quality through incremental progress","body":"# Kaizen: Continuous Improvement\n\n## Overview\n\nSmall improvements, continuously. Error-proof by design. Follow what works. Build only what''s needed.\n\n**Core principle:** Many small improvements beat one big change. Prevent errors at design time, not with fixes.\n\n## When to Use\n\n**Always applied for:**\n\n- Code implementation and refactoring\n- Architecture and design decisions\n- Process and workflow improvements\n- Error handling and validation\n\n**Philosophy:** Quality through incremental progress and prevention, not perfection through massive effort.\n\n## The Four Pillars\n\n### 1. Continuous Improvement (Kaizen)\n\nSmall, frequent improvements compound into major gains.\n\n#### Principles\n\n**Incremental over revolutionary:**\n\n- Make smallest viable change that improves quality\n- One improvement at a time\n- Verify each change before next\n- Build momentum through small wins\n\n**Always leave code better:**\n\n- Fix small issues as you encounter them\n- Refactor while you work (within scope)\n- Update outdated comments\n- Remove dead code when you see it\n\n**Iterative refinement:**\n\n- First version: make it work\n- Second pass: make it clear\n- Third pass: make it efficient\n- Don''t try all three at once\n\n<Good>\n```typescript\n// Iteration 1: Make it work\nconst calculateTotal = (items: Item[]) => {\n  let total = 0;\n  for (let i = 0; i < items.length; i++) {\n    total += items[i].price * items[i].quantity;\n  }\n  return total;\n};\n\n// Iteration 2: Make it clear (refactor)\nconst calculateTotal = (items: Item[]): number => {\nreturn items.reduce((total, item) => {\nreturn total + (item.price \\* item.quantity);\n}, 0);\n};\n\n// Iteration 3: Make it robust (add validation)\nconst calculateTotal = (items: Item[]): number => {\nif (!items?.length) return 0;\n\nreturn items.reduce((total, item) => {\nif (item.price < 0 || item.quantity < 0) {\nthrow new Error(''Price and quantity must be non-negative'');\n}\nreturn total + (item.price \\* item.quantity);\n}, 0);\n};\n\n````\nEach step is complete, tested, and working\n</Good>\n\n<Bad>\n```typescript\n// Trying to do everything at once\nconst calculateTotal = (items: Item[]): number => {\n  // Validate, optimize, add features, handle edge cases all together\n  if (!items?.length) return 0;\n  const validItems = items.filter(item => {\n    if (item.price < 0) throw new Error(''Negative price'');\n    if (item.quantity < 0) throw new Error(''Negative quantity'');\n    return item.quantity > 0; // Also filtering zero quantities\n  });\n  // Plus caching, plus logging, plus currency conversion...\n  return validItems.reduce(...); // Too many concerns at once\n};\n````\n\nOverwhelming, error-prone, hard to verify\n</Bad>\n\n#### In Practice\n\n**When implementing features:**\n\n1. Start with simplest version that works\n2. Add one improvement (error handling, validation, etc.)\n3. Test and verify\n4. Repeat if time permits\n5. Don''t try to make it perfect immediately\n\n**When refactoring:**\n\n- Fix one smell at a time\n- Commit after each improvement\n- Keep tests passing throughout\n- Stop when \"good enough\" (diminishing returns)\n\n**When reviewing code:**\n\n- Suggest incremental improvements (not rewrites)\n- Prioritize: critical → important → nice-to-have\n- Focus on highest-impact changes first\n- Accept \"better than before\" even if not perfect\n\n### 2. Poka-Yoke (Error Proofing)\n\nDesign systems that prevent errors at compile/design time, not runtime.\n\n#### Principles\n\n**Make errors impossible:**\n\n- Type system catches mistakes\n- Compiler enforces contracts\n- Invalid states unrepresentable\n- Errors caught early (left of production)\n\n**Design for safety:**\n\n- Fail fast and loudly\n- Provide helpful error messages\n- Make correct path obvious\n- Make incorrect path difficult\n\n**Defense in layers:**\n\n1. Type system (compile time)\n2. Validation (runtime, early)\n3. Guards (preconditions)\n4. Error boundaries (graceful degradation)\n\n#### Type System Error Proofing\n\n<Good>\n```typescript\n// Error: string status can be any value\ntype OrderBad = {\n  status: string; // Can be \"pending\", \"PENDING\", \"pnding\", anything!\n  total: number;\n};\n\n// Good: Only valid states possible\ntype OrderStatus = ''pending'' | ''processing'' | ''shipped'' | ''delivered'';\ntype Order = {\nstatus: OrderStatus;\ntotal: number;\n};\n\n// Better: States with associated data\ntype Order =\n| { status: ''pending''; createdAt: Date }\n| { status: ''processing''; startedAt: Date; estimatedCompletion: Date }\n| { status: ''shipped''; trackingNumber: string; shippedAt: Date }\n| { status: ''delivered''; deliveredAt: Date; signature: string };\n\n// Now impossible to have shipped without trackingNumber\n\n````\nType system prevents entire classes of errors\n</Good>\n\n<Good>\n```typescript\n// Make invalid states unrepresentable\ntype NonEmptyArray<T> = [T, ...T[]];\n\nconst firstItem = <T>(items: NonEmptyArray<T>): T => {\n  return items[0]; // Always safe, never undefined!\n};\n\n// Caller must prove array is non-empty\nconst items: number[] = [1, 2, 3];\nif (items.length > 0) {\n  firstItem(items as NonEmptyArray<number>); // Safe\n}\n````\n\nFunction signature guarantees safety\n</Good>\n\n#### Validation Error Proofing\n\n<Good>\n```typescript\n// Error: Validation after use\nconst processPayment = (amount: number) => {\n  const fee = amount * 0.03; // Used before validation!\n  if (amount <= 0) throw new Error(''Invalid amount'');\n  // ...\n};\n\n// Good: Validate immediately\nconst processPayment = (amount: number) => {\nif (amount <= 0) {\nthrow new Error(''Payment amount must be positive'');\n}\nif (amount > 10000) {\nthrow new Error(''Payment exceeds maximum allowed'');\n}\n\nconst fee = amount \\* 0.03;\n// ... now safe to use\n};\n\n// Better: Validation at boundary with branded type\ntype PositiveNumber = number & { readonly \\_\\_brand: ''PositiveNumber'' };\n\nconst validatePositive = (n: number): PositiveNumber => {\nif (n <= 0) throw new Error(''Must be positive'');\nreturn n as PositiveNumber;\n};\n\nconst processPayment = (amount: PositiveNumber) => {\n// amount is guaranteed positive, no need to check\nconst fee = amount \\* 0.03;\n};\n\n// Validate at system boundary\nconst handlePaymentRequest = (req: Request) => {\nconst amount = validatePositive(req.body.amount); // Validate once\nprocessPayment(amount); // Use everywhere safely\n};\n\n````\nValidate once at boundary, safe everywhere else\n</Good>\n\n#### Guards and Preconditions\n\n<Good>\n```typescript\n// Early returns prevent deeply nested code\nconst processUser = (user: User | null) => {\n  if (!user) {\n    logger.error(''User not found'');\n    return;\n  }\n\n  if (!user.email) {\n    logger.error(''User email missing'');\n    return;\n  }\n\n  if (!user.isActive) {\n    logger.info(''User inactive, skipping'');\n    return;\n  }\n\n  // Main logic here, guaranteed user is valid and active\n  sendEmail(user.email, ''Welcome!'');\n};\n````\n\nGuards make assumptions explicit and enforced\n</Good>\n\n#### Configuration Error Proofing\n\n<Good>\n```typescript\n// Error: Optional config with unsafe defaults\ntype ConfigBad = {\n  apiKey?: string;\n  timeout?: number;\n};\n\nconst client = new APIClient({ timeout: 5000 }); // apiKey missing!\n\n// Good: Required config, fails early\ntype Config = {\napiKey: string;\ntimeout: number;\n};\n\nconst loadConfig = (): Config => {\nconst apiKey = process.env.API_KEY;\nif (!apiKey) {\nthrow new Error(''API_KEY environment variable required'');\n}\n\nreturn {\napiKey,\ntimeout: 5000,\n};\n};\n\n// App fails at startup if config invalid, not during request\nconst config = loadConfig();\nconst client = new APIClient(config);\n\n````\nFail at startup, not in production\n</Good>\n\n#### In Practice\n\n**When designing APIs:**\n- Use types to constrain inputs\n- Make invalid states unrepresentable\n- Return Result<T, E> instead of throwing\n- Document preconditions in types\n\n**When handling errors:**\n- Validate at system boundaries\n\n- Use guards for preconditions\n- Fail fast with clear messages\n- Log context for debugging\n\n**When configuring:**\n- Required over optional with defaults\n- Validate all config at startup\n- Fail deployment if config invalid\n- Don''t allow partial configurations\n\n### 3. Standardized Work\nFollow established patterns. Document what works. Make good practices easy to follow.\n\n#### Principles\n\n**Consistency over cleverness:**\n- Follow existing codebase patterns\n- Don''t reinvent solved problems\n- New pattern only if significantly better\n- Team agreement on new patterns\n\n**Documentation lives with code:**\n- README for setup and architecture\n- CLAUDE.md for AI coding conventions\n- Comments for \"why\", not \"what\"\n- Examples for complex patterns\n\n**Automate standards:**\n- Linters enforce style\n- Type checks enforce contracts\n- Tests verify behavior\n- CI/CD enforces quality gates\n\n#### Following Patterns\n\n<Good>\n```typescript\n// Existing codebase pattern for API clients\nclass UserAPIClient {\n  async getUser(id: string): Promise<User> {\n    return this.fetch(`/users/${id}`);\n  }\n}\n\n// New code follows the same pattern\nclass OrderAPIClient {\n  async getOrder(id: string): Promise<Order> {\n    return this.fetch(`/orders/${id}`);\n  }\n}\n````\n\nConsistency makes codebase predictable\n</Good>\n\n<Bad>\n```typescript\n// Existing pattern uses classes\nclass UserAPIClient { /* ... */ }\n\n// New code introduces different pattern without discussion\nconst getOrder = async (id: string): Promise<Order> => {\n// Breaking consistency \"because I prefer functions\"\n};\n\n````\nInconsistency creates confusion\n</Bad>\n\n#### Error Handling Patterns\n\n<Good>\n```typescript\n// Project standard: Result type for recoverable errors\ntype Result<T, E> = { ok: true; value: T } | { ok: false; error: E };\n\n// All services follow this pattern\nconst fetchUser = async (id: string): Promise<Result<User, Error>> => {\n  try {\n    const user = await db.users.findById(id);\n    if (!user) {\n      return { ok: false, error: new Error(''User not found'') };\n    }\n    return { ok: true, value: user };\n  } catch (err) {\n    return { ok: false, error: err as Error };\n  }\n};\n\n// Callers use consistent pattern\nconst result = await fetchUser(''123'');\nif (!result.ok) {\n  logger.error(''Failed to fetch user'', result.error);\n  return;\n}\nconst user = result.value; // Type-safe!\n````\n\nStandard pattern across codebase\n</Good>\n\n#### Documentation Standards\n\n<Good>\n```typescript\n/**\n * Retries an async operation with exponential backoff.\n *\n * Why: Network requests fail temporarily; retrying improves reliability\n * When to use: External API calls, database operations\n * When not to use: User input validation, internal function calls\n *\n * @example\n * const result = await retry(\n *   () => fetch(''https://api.example.com/data''),\n *   { maxAttempts: 3, baseDelay: 1000 }\n * );\n */\nconst retry = async <T>(\n  operation: () => Promise<T>,\n  options: RetryOptions\n): Promise<T> => {\n  // Implementation...\n};\n```\nDocuments why, when, and how\n</Good>\n\n#### In Practice\n\n**Before adding new patterns:**\n\n- Search codebase for similar problems solved\n- Check CLAUDE.md for project conventions\n- Discuss with team if breaking from pattern\n- Update docs when introducing new pattern\n\n**When writing code:**\n\n- Match existing file structure\n- Use same naming conventions\n- Follow same error handling approach\n- Import from same locations\n\n**When reviewing:**\n\n- Check consistency with existing code\n- Point to examples in codebase\n- Suggest aligning with standards\n- Update CLAUDE.md if new standard emerges\n\n### 4. Just-In-Time (JIT)\n\nBuild what''s needed now. No more, no less. Avoid premature optimization and over-engineering.\n\n#### Principles\n\n**YAGNI (You Aren''t Gonna Need It):**\n\n- Implement only current requirements\n- No \"just in case\" features\n- No \"we might need this later\" code\n- Delete speculation\n\n**Simplest thing that works:**\n\n- Start with straightforward solution\n- Add complexity only when needed\n- Refactor when requirements change\n- Don''t anticipate future needs\n\n**Optimize when measured:**\n\n- No premature optimization\n- Profile before optimizing\n- Measure impact of changes\n- Accept \"good enough\" performance\n\n#### YAGNI in Action\n\n<Good>\n```typescript\n// Current requirement: Log errors to console\nconst logError = (error: Error) => {\n  console.error(error.message);\n};\n```\nSimple, meets current need\n</Good>\n\n<Bad>\n```typescript\n// Over-engineered for \"future needs\"\ninterface LogTransport {\n  write(level: LogLevel, message: string, meta?: LogMetadata): Promise<void>;\n}\n\nclass ConsoleTransport implements LogTransport { /_... _/ }\nclass FileTransport implements LogTransport { /_ ... _/ }\nclass RemoteTransport implements LogTransport { /_ ..._/ }\n\nclass Logger {\nprivate transports: LogTransport[] = [];\nprivate queue: LogEntry[] = [];\nprivate rateLimiter: RateLimiter;\nprivate formatter: LogFormatter;\n\n// 200 lines of code for \"maybe we''ll need it\"\n}\n\nconst logError = (error: Error) => {\nLogger.getInstance().log(''error'', error.message);\n};\n\n````\nBuilding for imaginary future requirements\n</Bad>\n\n**When to add complexity:**\n- Current requirement demands it\n- Pain points identified through use\n- Measured performance issues\n- Multiple use cases emerged\n\n<Good>\n```typescript\n// Start simple\nconst formatCurrency = (amount: number): string => {\n  return `$${amount.toFixed(2)}`;\n};\n\n// Requirement evolves: support multiple currencies\nconst formatCurrency = (amount: number, currency: string): string => {\n  const symbols = { USD: ''$'', EUR: ''€'', GBP: ''£'' };\n  return `${symbols[currency]}${amount.toFixed(2)}`;\n};\n\n// Requirement evolves: support localization\nconst formatCurrency = (amount: number, locale: string): string => {\n  return new Intl.NumberFormat(locale, {\\n    style: ''currency'',\n    currency: locale === ''en-US'' ? ''USD'' : ''EUR'',\n  }).format(amount);\n};\n````\n\nComplexity added only when needed\n</Good>\n\n#### Premature Abstraction\n\n<Bad>\n```typescript\n// One use case, but building generic framework\nabstract class BaseCRUDService<T> {\n  abstract getAll(): Promise<T[]>;\n  abstract getById(id: string): Promise<T>;\n  abstract create(data: Partial<T>): Promise<T>;\n  abstract update(id: string, data: Partial<T>): Promise<T>;\n  abstract delete(id: string): Promise<void>;\n}\n\nclass GenericRepository<T> { /_300 lines _/ }\nclass QueryBuilder<T> { /_ 200 lines_/ }\n// ... building entire ORM for single table\n\n````\nMassive abstraction for uncertain future\n</Bad>\n\n<Good>\n```typescript\n// Simple functions for current needs\nconst getUsers = async (): Promise<User[]> => {\n  return db.query(''SELECT * FROM users'');\n};\n\nconst getUserById = async (id: string): Promise<User | null> => {\n  return db.query(''SELECT * FROM users WHERE id = $1'', [id]);\n};\n\n// When pattern emerges across multiple entities, then abstract\n````\n\nAbstract only when pattern proven across 3+ cases\n</Good>\n\n#### Performance Optimization\n\n<Good>\n```typescript\n// Current: Simple approach\nconst filterActiveUsers = (users: User[]): User[] => {\n  return users.filter(user => user.isActive);\n};\n\n// Benchmark shows: 50ms for 1000 users (acceptable)\n// ✓ Ship it, no optimization needed\n\n// Later: After profiling shows this is bottleneck\n// Then optimize with indexed lookup or caching\n\n````\nOptimize based on measurement, not assumptions\n</Good>\n\n<Bad>\n```typescript\n// Premature optimization\nconst filterActiveUsers = (users: User[]): User[] => {\n  // \"This might be slow, so let''s cache and index\"\n  const cache = new WeakMap();\n  const indexed = buildBTreeIndex(users, ''isActive'');\n  // 100 lines of optimization code\n  // Adds complexity, harder to maintain\n  // No evidence it was needed\n};\\\n````\n\nComplex solution for unmeasured problem\n</Bad>\n\n#### In Practice\n\n**When implementing:**\n\n- Solve the immediate problem\n- Use straightforward approach\n- Resist \"what if\" thinking\n- Delete speculative code\n\n**When optimizing:**\n\n- Profile first, optimize second\n- Measure before and after\n- Document why optimization needed\n- Keep simple version in tests\n\n**When abstracting:**\n\n- Wait for 3+ similar cases (Rule of Three)\n- Make abstraction as simple as possible\n- Prefer duplication over wrong abstraction\n- Refactor when pattern clear\n\n## Integration with Commands\n\nThe Kaizen skill guides how you work. The commands provide structured analysis:\n\n- **`/why`**: Root cause analysis (5 Whys)\n- **`/cause-and-effect`**: Multi-factor analysis (Fishbone)\n- **`/plan-do-check-act`**: Iterative improvement cycles\n- **`/analyse-problem`**: Comprehensive documentation (A3)\n- **`/analyse`**: Smart method selection (Gemba/VSM/Muda)\n\nUse commands for structured problem-solving. Apply skill for day-to-day development.\n\n## Red Flags\n\n**Violating Continuous Improvement:**\n\n- \"I''ll refactor it later\" (never happens)\n- Leaving code worse than you found it\n- Big bang rewrites instead of incremental\n\n**Violating Poka-Yoke:**\n\n- \"Users should just be careful\"\n- Validation after use instead of before\n- Optional config with no validation\n\n**Violating Standardized Work:**\n\n- \"I prefer to do it my way\"\n- Not checking existing patterns\n- Ignoring project conventions\n\n**Violating Just-In-Time:**\n\n- \"We might need this someday\"\n- Building frameworks before using them\n- Optimizing without measuring\n\n## Remember\n\n**Kaizen is about:**\n\n- Small improvements continuously\n- Preventing errors by design\n- Following proven patterns\n- Building only what''s needed\n\n**Not about:**\n\n- Perfection on first try\n- Massive refactoring projects\n- Clever abstractions\n- Premature optimization\n\n**Mindset:** Good enough today, better tomorrow. Repeat.\n"},"lastSynced":"2026-03-08T02:11:26.961Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Refactoring Agents seeking to implement continuous improvement in their workflows and architectures","zh":"适合寻求在工作流和架构中实施持续改进的代码重构代理","ja":"ワークフローとアーキテクチャに継続的な改善を実装しようとするコードリファクタリングエージェントに最適","ko":"워크플로우와 아키텍처에 지속적인 개선을 구현하려는 코드 리팩토링 에이전트에 적합","es":"Ideal para Agentes de Refactorización de Código que buscan implementar la mejora continua en sus flujos de trabajo y arquitecturas","fr":"Idéal pour les Agents de Réfactoration de Code cherchant à mettre en œuvre l''amélioration continue dans leurs flux de travail et architectures","de":"Ideal für Code-Refactoring-Agents, die kontinuierliche Verbesserungen in ihren Workflows und Architekturen umsetzen möchten","pt":"Ideal para Agentes de Refatoração de Código que buscam implementar melhoria contínua em seus fluxos de trabalho e arquiteturas","ru":"Идеально для агентов рефакторинга кода, стремящихся реализовать непрерывное совершенствование в своих рабочих процессах и архитектурах","ar":"مثالية لعمليات إعادة هيكلة الكود التي تهدف إلى تنفيذ التحسين المستمر في سير عملها وهيكلتها"},"recommendation":{"en":"Empowers agents to prevent errors at design time through incremental progress, ensuring quality code implementation and architecture by following principles like error-proofing by design and building only what''s needed, utilizing workflows and process improvements","zh":"赋予代理在设计时通过增量进展防止错误，确保通过遵循错误防范设计和仅构建所需内容等原则实现高质量代码和架构，并利用工作流和流程改进","ja":"エージェントにデザイン時にはインクリメンタルな進歩を通じてエラーを防ぐことを可能にし、エラープルーフのデザインや必要なものだけを構築するなどの原則に従うことで、高品質のコードとアーキテクチャを実現し、ワークフローとプロセスの改善を利用する","ko":"에이전트가 설계 시점에 증분적 진도를 통해 오류를 방지할 수 있도록 하여, 오류 방지 설계 및 필요한 것만 구축하는 등 원칙을 따르며, 작업 흐름 및 프로세스 개선을 활용하여 고품질 코드 및 아키텍처 구현을 보장","es":"Habilita a los agentes a prevenir errores en el momento del diseño a través del progreso incremental, garantizando la implementación de código y arquitectura de calidad siguiendo principios como la protección contra errores por diseño y la construcción solo de lo necesario, utilizando flujos de trabajo y mejoras de procesos","fr":"Permet aux agents de prévenir les erreurs au moment de la conception grâce à la progression incrémentale, en garantissant la mise en œuvre de code et d''architecture de qualité en suivant des principes tels que la protection contre les erreurs par conception et la construction de ce qui est nécessaire, en utilisant des flux de travail et des améliorations de processus","de":"Ermächtigt die Agenten, Fehler bei der Auslegung durch inkrementellen Fortschritt zu vermeiden, indem sie eine qualitativ hochwertige Code- und Architekturimplementierung gewährleisten, indem sie Grundsätze wie Fehlervermeidung durch Auslegung und nur das Bauen, was benötigt wird, befolgen, unter Nutzung von Workflows und Prozessverbesserungen","pt":"Habilita os agentes a prevenir erros no tempo de design por meio do progresso incremental, garantindo a implementação de código de qualidade e arquitetura seguindo princípios como a prova de erros por design e a construção apenas do que é necessário, utilizando fluxos de trabalho e melhorias de processo","ru":"Наделяет агентов возможностью предотвращать ошибки на этапе проектирования посредством инкрементного прогресса, обеспечивая качественную реализацию кода и архитектуры, следуя принципам, таким как защита от ошибок по设计у и построение только того, что необходимо, используя рабочие процессы и улучшения процесса","ar":"تمكّن الوكلاء من منع الأخطاء في وقت التصميم من خلال التقدم التدريجي، وضمان تنفيذ код جيد وعمارة متابعة لمبادئ مثل إثبات الأخطاء حسب التصميم وبناء ما هو مطلوب فقط، واستخدام سير العمل وتحسينات العملية"},"useCases":{"en":["Refactoring code for readability and maintainability","Implementing error handling and validation mechanisms","Optimizing workflows for development teams"],"zh":["为可读性和可维护性重构代码","实施错误处理和验证机制","为开发团队优化工作流"],"ja":["可読性とメンテナンス性のためにコードをリファクタリングする","エラーハンドリングと検証メカニズムを実装する","開発チームのためのワークフローを最適化する"],"ko":["가독성 및 유지보수성을 위해 코드 리팩토링","오류 처리 및 검증 메커니즘 구현","개발 팀을 위한 워크플로 최적화"],"es":["Reestructuración de código para una mayor legibilidad y mantenibilidad","Implementación de mecanismos de control y validación de errores","Optimización de flujos de trabajo para equipos de desarrollo"],"fr":["Réfactoration de code pour une meilleure lisibilité et maintenabilité","Mise en œuvre de mécanismes de gestion et de validation d''erreurs","Optimisation des flux de travail pour les équipes de développement"],"de":["Umstrukturierung von Code für bessere Lesbarkeit und Wartbarkeit","Implementierung von Fehlerbehandlungs- und Validierungsmechanismen","Optimierung von Workflows für Entwicklungsteams"],"pt":["Refatoração de código para legibilidade e manutenção","Implementação de mecanismos de tratamento e validação de erros","Otimização de fluxos de trabalho para equipes de desenvolvimento"],"ru":["Рефакторинг кода для читаемости и поддержки","Реализация механизмов обработки и проверки ошибок","Оптимизация рабочих процессов для команд разработки"],"ar":["إعادة هيكلة الكود لسهولة القراءة والصيانة","تنفيذ آليات معالجة وتحقق الأخطاء","تحسين سير العمل لفريق التطوير"]},"limitations":{"en":["Requires continuous monitoring and evaluation","Dependent on incremental progress and feedback loops"],"zh":["需要持续监控和评估","依赖于增量进展和反馈环"],"ja":["継続的なモニタリングと評価が必要","インクリメンタルな進歩とフィードバックループに依存"],"ko":["지속적인 모니터링 및 평가가 필요","증분적 진도 및 피드백 루프에 의존"],"es":["Requiere un seguimiento y evaluación continuos","Depende del progreso incremental y de los bucles de retroalimentación"],"fr":["Nécessite un suivi et une évaluation continus","Dépend de la progression incrémentale et des boucles de rétroaction"],"de":["Erfordert kontinuierliche Überwachung und Bewertung","Hängt von inkrementellem Fortschritt und Feedback-Schleifen ab"],"pt":["Requer monitoramento e avaliação contínua","Depende do progresso incremental e laços de feedback"],"ru":["Требует непрерывного мониторинга и оценки","Зависит от инкрементного прогресса и обратных связей"],"ar":["يتطلب مراقبة وتقييم مستمرين","يعتمد على التقدم التدريجي ودورات التغذية الراجعة"]},"version":4},"contentHash":"27535c5b9235cce48b2fb56d7422539dca55c9949d9c26a0d83adeb6ef4d737c","qualityScore":57}');
