INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('atalovesyou/claude-skills-pack/python-testing-patterns', 'python-testing-patterns', 'atalovesyou', 'claude-skills-pack', 'community', 'python-testing-patterns atalovesyou claude-skills-pack community The python-testing-patterns skill provides a comprehensive guide to implementing robust testing strategies in Python using pytest, fixtures, and mocking. It benefits developers writing unit tests, setting up test suites, and implementing test-driven development. 全面了解 Python 测试模式，包括使用 pytest、fixtures 和 mocking 实现强健的测试策略 Python テストパターンの包括的なガイド。pytest、fixtures、mocking を使用して堅牢なテスト戦略を実装します Python 테스트 패턴에 대한 종합 가이드. pytest, fixtures, mocking을 사용하여 강력한 테스트 전략을 구현합니다 Implementa patrones de prueba robustos en Python con pytest, fixtures y TDD. Configura test suites y infraestructura de prueba para tus proyectos Implémentez des modèles de test robustes en Python avec pytest, fixtures et TDD. Configurez vos suites de test et infrastructure de test pour vos projets Implementieren Sie robuste Testmuster in Python mit pytest, Fixtures und TDD. Konfigurieren Sie Ihre Test-Suiten und Test-Infrastruktur für Ihre Projekte mit AI-Tools Guia abrangente para implementar estratégias de teste robustas em Python com pytest, fixtures e TDD Полное руководство по реализации шаблонов тестирования Python с помощью pytest, фикстур и ТDD دليل شاملة لتنفيذ نماذج اختبار قوية في بايثون باستخدام pytest و TDD how to use python-testing-patterns python-testing-patterns setup guide python-testing-patterns vs unittest pytest testing framework test-driven development best practices python-testing-patterns install python testing patterns tutorial python-testing-patterns alternative python testing with fixtures and mocking Python 测试模式 pytest fixtures mocking 参数化 测试驱动开发 单元测试 集成测试 AI工具 Python 测试框架 Implements test-driven development (TDD) practices Uses pytest for unit testing and test infrastructure setup Utilizes fixtures and mocking for external dependencies and services Supports parameterization for efficient test execution Enables testing of async code and concurrent operations python-testing-patterns is a skill that offers a comprehensive guide to implementing robust testing strategies in Python, including unit tests, test-driven development, and mocking.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ducnm-mimhus/Avada-Simple-Sales-Pop/theme-extension', 'community', 'ducnm-mimhus', 'Avada-Simple-Sales-Pop', 'ducnm-mimhus/Avada-Simple-Sales-Pop', 'theme-extension', 0, 0, 57, '2026-03-08T01:57:15.552Z', '2026-03-08T02:11:31.383Z', '26b6f47dec9fab443ea989b0599e5f640c71059b16155225d689a7904f79237b', '{"id":"ducnm-mimhus/Avada-Simple-Sales-Pop/theme-extension","name":"theme-extension","description":{"en":"The theme-extension skill utilizes Shopify''s native Liquid rendering for optimal storefront performance, benefiting developers who need to render static/semi-static content and SEO-critical product displays.","zh":"主题扩展开发使用Shopify的原生Liquid渲染技术，优化店面性能。适用于静态/半静态内容、SEO关键内容和产品展示。","ja":"テーマエクステンション開発は、ShopifyのネイティブLiquidレンダリングを使用してストアのパフォーマンスを最適化します。静的/半静的コンテンツ、SEO关键コンテンツ、製品表示に適しています。","ko":"테마 확장 개발은 Shopify의 네이티브 Liquid 렌더링을 사용하여 상점 성능을 최적화합니다. 정적/반정적 콘텐츠, SEO关键 콘텐츠, 제품 표시에 적합합니다.","es":"Las extensiones de tema utilizan la renderización nativa de Liquid de Shopify para un rendimiento óptimo en la tienda en línea","fr":"Les extensions de thème utilisent le rendu Liquid natif de Shopify pour un rendement optimal sur le site de commerce électronique","de":"Theme-Extensions verwenden die native Liquid-Renderung von Shopify für ein optimales Leistung in dem Online-Shop","pt":"Desenvolva extensões de tema para melhorar o desempenho da loja virtual com renderização Liquid nativa do Shopify.","ru":"Разработайте расширения темы для увеличения скорости магазина с помощью родной Liquid-рендеринга Shopify.","ar":"طور ملحقات قوالب لتطوير أداء المتجر الإلكتروني باستخدام تقنية Liquid الأصلية من Shopify."},"seo":{"title":{"en":"theme-extension: Optimal Storefront Performance Setup Gui...","zh":"主题扩展开发设置指南 - 优化商店性能","ja":"テーマエクステンション開発ベストプラクティス - AIエージェントを使用した最適化","ko":"테마 확장 개발 가이드 - 최적의 상점 성능을 위한 설정","es":"Guía de Configuración de Theme Extension para Desarrollad...","fr":"Guide de Mise en Place de l''Extension de Thème pour les D...","de":"Einrichtungsleitfaden für Theme-Extension-Entwickler","pt":"Guia de Configuração de Extensões de Tema para Desenvolve...","ru":"Настройка Расширений Темы для ИИ Агентов: Лучшие Практики","ar":"دليل تطوير Extensions主题 لمنصات التجارة الإلكترونية"},"description":{"en":"Unlock optimal storefront performance with theme-extension! Learn how to leverage Shopify''s native Liquid rendering for SEO-critical content and static produ...","zh":"了解如何使用主题扩展开发创建高性能的商店。主题扩展使用Shopify的原生Liquid渲染技术，优化店面性能。","ja":"テーマエクステンション開発を使用して、高パフォーマンスのストアを作成する方法を学びます。テーマエクステンションは、ShopifyのネイティブLiquidレンダリングを使用してストアのパフォーマンスを最適化します。","ko":"테마 확장 개발을 사용하여 고성능의 상점을 생성하는 방법에 대해 알아보세요. 테마 확장은 Shopify의 네이티브 Liquid 렌더링을 사용하여 상점 성능을 최적화합니다.","es":"Aprende a utilizar las extensiones de tema para mejorar el rendimiento de tu tienda en línea con Shopify y Liquid","fr":"Découvrez comment utiliser les extensions de thème pour améliorer les performances de votre boutique en ligne avec Shopify et Liquid","de":"Erfahren Sie, wie Sie Theme-Extensions verwenden, um die Leistung Ihres Online-Shops mit Shopify und Liquid zu verbessern","pt":"Aprenda a criar extensões de tema para melhorar o desempenho da loja virtual com renderização Liquid nativa do Shopify","ru":"Узнайте, как создать расширения темы для увеличения скорости магазина с помощью родной Liquid-рендеринга Shopify для ИИ Агентов","ar":"تعلم كيفية إنشاء ملحقات قوالب لتطوير أداء المتجر الإلكتروني باستخدام تقنية Liquid الأصلية من Shopify"},"definition":{"en":"theme-extension is a development approach that uses Shopify''s native Liquid rendering for server-rendered content, ensuring optimal storefront performance.","zh":"主题扩展是一种使用Shopify的原生Liquid渲染技术的开发方式，用于创建高性能的商店。","ja":"テーマエクステンションは、ShopifyのネイティブLiquidレンダリングを使用して、高パフォーマンスのストアを作成する開発方法です。","ko":"테마 확장은 Shopify의 네이티브 Liquid 렌더링을 사용하여 고성능의 상점을 생성하는 개발 방법입니다.","es":"Una extensión de tema es una tecnología que utiliza la renderización de Liquid de Shopify para mejorar el rendimiento de la tienda en línea","fr":"Une extension de thème est une technologie qui utilise le rendu Liquid de Shopify pour améliorer les performances du site de commerce électronique","de":"Eine Theme-Extension ist eine Technologie, die die Liquid-Renderung von Shopify verwendet, um die Leistung des Online-Shops zu verbessern","pt":"Extensões de tema são componentes que usam a renderização Liquid nativa do Shopify para melhorar o desempenho da loja virtual","ru":"Расширения темы - это компоненты, которые используют родную Liquid-рендеринг Shopify для увеличения скорости магазина","ar":"ملحقات القوالب هي مكونات تستخدم تقنية Liquid الأصلية من Shopify لتطوير أداء المتجر الإلكتروني"},"features":{"en":["Utilizes Shopify''s native Liquid rendering for optimal storefront performance","Supports server-rendered content for static/semi-static and SEO-critical product displays","Follows a specific directory structure for theme extension development","Allows for static and semi-static content rendering","Enables SEO-critical content rendering for product displays","Uses a theme extension approach for optimal performance"],"zh":["使用Shopify的原生Liquid渲染技术","优化店面性能","适用于静态/半静态内容","适用于SEO关键内容","适用于产品展示","支持服务器端渲染"],"ja":["ShopifyのネイティブLiquidレンダリングを使用","ストアのパフォーマンスを最適化","静的/半静的コンテンツに適する","SEO关键コンテンツに適する","製品表示に適する","サーバーサイドレンダリングをサポート"],"ko":["Shopify의 네이티브 Liquid 렌더링을 사용","상점 성능을 최적화","정적/반정적 콘텐츠에 적합","SEO关键 콘텐츠에 적합","제품 표시에 적합","서버사이드 렌더링을 지원"],"es":["Utiliza la renderización nativa de Liquid de Shopify","Optimiza el rendimiento de la tienda en línea","Ideal para contenido estático y semi-estático","Mejora la experiencia del usuario con un renderizado servidor","Compatibilidad con Shopify para una integración perfecta"],"fr":["Utilise le rendu Liquid natif de Shopify","Optimise les performances du site de commerce électronique","Idéal pour le contenu statique et semi-statique","Améliore l''expérience utilisateur avec un rendu serveur","Compatibilité avec Shopify pour une intégration parfaite"],"de":["Verwendet die native Liquid-Renderung von Shopify","Optimiert die Leistung des Online-Shops","Ideal für statischen und semi-statischen Inhalt","Verbessert die Benutzererfahrung durch Server-Rendering","Kompatibilität mit Shopify für eine perfekte Integration"],"pt":["Renderização Liquid nativa do Shopify","Conteúdo renderizado no servidor antes de alcançar o navegador do cliente","Melhor desempenho da loja virtual","Suporte a conteúdo estático e semi-estático","Otimização para SEO"],"ru":["Родная Liquid-рендеринг Shopify","Контент, отображаемый на сервере до того, как достигнет браузера клиента","Улучшение скорости магазина","Поддержка статического и полустатического контента","Оптимизация для ИИ Агентов и поисковых систем"],"ar":["تقنية Liquid الأصلية من Shopify","المحتوى المُعرّض على الخادم قبل وصوله إلى متصفح العميل","تطوير أداء المتجر الإلكتروني","دعم المحتوى الثابت والشبه-ثابت","تحسين الأداء للعوامل الإلكترونية"]},"keywords":{"en":["how to use theme-extension","what is theme-extension","theme-extension alternative","theme-extension vs scripttag","theme-extension install","theme-extension setup guide","shopify liquid rendering","optimal storefront performance"],"zh":["主题扩展开发","Shopify Liquid","商店性能优化","静态内容开发","SEO关键内容开发","产品展示开发","服务器端渲染","AIエージェント"],"ja":["テーマエクステンション開発","Shopify Liquid","ストアパフォーマンス最適化","静的コンテンツ開発","SEO关键コンテンツ開発","製品表示開発","サーバーサイドレンダリング","AIエージェント"],"ko":["테마 확장 개발","Shopify Liquid","상점 성능 최적화","정적 콘텐츠 개발","SEO关键 콘텐츠 개발","제품 표시 개발","서버사이드 렌더링","AI 에이전트"],"es":["theme extension","Shopify","Liquid","rendimiento de tienda en línea","desarrollo de comercio electrónico","extensiones de tema para Shopify","mejora del rendimiento de la tienda","Herramientas de AI para desarrolladores","Agentes de IA para comercio electrónico"],"fr":["extension de thème","Shopify","Liquid","performances du site de commerce électronique","développement de commerce électronique","extensions de thème pour Shopify","amélioration des performances du site","Outils d''IA pour les développeurs","Agents d''IA pour le commerce électronique"],"de":["Theme-Extension","Shopify","Liquid","Leistung des Online-Shops","Entwicklung von E-Commerce","Theme-Extensions für Shopify","Leistungsverbesserung des Online-Shops","AI-Tools für Entwickler","KI-Agents für E-Commerce"],"pt":["extensões de tema","renderização Liquid","Shopify","desenvolvimento de loja virtual","otimização de SEO","melhor desempenho da loja virtual","conteúdo estático","conteúdo semi-estático"],"ru":["расширения темы","Liquid-рендеринг","Shopify","разработка магазина","оптимизация для ИИ Агентов","увеличение скорости магазина","статический контент","полустатический контент"],"ar":["ملحقات قوالب","تقنية Liquid","Shopify","تطوير المتجر الإلكتروني","تحسين الأداء للعوامل الإلكترونية","تطوير أداء المتجر الإلكتروني","المحتوى الثابت","المحتوى الشبه-ثابت"]}},"owner":"ducnm-mimhus","repo":"Avada-Simple-Sales-Pop","repoPath":"ducnm-mimhus/Avada-Simple-Sales-Pop","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.552Z","topics":[],"category":"community","skillMd":{"name":"theme-extension","description":"Use this skill when the user asks about theme extension, app blocks, Liquid templates, app embed, storefront rendering, app proxy, or any Theme App Extension development work. Provides patterns for Liquid-first storefront rendering with minimal JavaScript.","bodyPreview":"# Theme App Extension Development\n\n## Overview\n\nTheme App Extensions use Shopify''s native Liquid rendering for **optimal storefront performance**. Content is server-rendered before reaching the customer''s browser.\n\n### When to Use\n\n| Approach | Use For |\n|----------|---------|\n| **Theme Extension** | Static/semi-static content, SEO-critical content, product displays |\n| **Scripttag** | Highly interactive widgets, real-time updates, complex UI |\n\n---\n\n## Directory Structure\n\n```\nextensions/theme-","body":"# Theme App Extension Development\n\n## Overview\n\nTheme App Extensions use Shopify''s native Liquid rendering for **optimal storefront performance**. Content is server-rendered before reaching the customer''s browser.\n\n### When to Use\n\n| Approach | Use For |\n|----------|---------|\n| **Theme Extension** | Static/semi-static content, SEO-critical content, product displays |\n| **Scripttag** | Highly interactive widgets, real-time updates, complex UI |\n\n---\n\n## Directory Structure\n\n```\nextensions/theme-extension/\n├── blocks/                    # App blocks (merchant can position)\n│   ├── feature-block.liquid   # Main feature block\n│   └── badge.liquid           # Small badge/snippet\n├── snippets/                  # Reusable Liquid snippets\n│   └── component.liquid       # Shared components\n├── assets/                    # JS/CSS files\n│   ├── app-embed.js           # Minimal JS (forms, interactions)\n│   └── styles.css             # Scoped styles\n└── locales/\n    └── en.default.json        # Translations\n```\n\n---\n\n## App Block Pattern\n\n### Block Schema\n\n```liquid\n{% schema %}\n{\n  \"name\": \"Feature Name\",\n  \"target\": \"section\",\n  \"enabled_by_default\": false,\n  \"settings\": [\n    {\n      \"type\": \"range\",\n      \"id\": \"items_per_page\",\n      \"label\": \"Items per page\",\n      \"min\": 3,\n      \"max\": 20,\n      \"default\": 10\n    },\n    {\n      \"type\": \"color\",\n      \"id\": \"primary_color\",\n      \"label\": \"Primary color\",\n      \"default\": \"#000000\"\n    }\n  ]\n}\n{% endschema %}\n\n{% comment %} Block content {% endcomment %}\n<div class=\"app-feature\" data-resource-id=\"{{ product.id }}\">\n  {% render ''app-component'', resource: product, settings: block.settings %}\n</div>\n\n{% stylesheet %}\n  .app-feature { /* scoped styles */ }\n{% endstylesheet %}\n\n{% javascript %}\n  // Minimal JS only when needed\n{% endjavascript %}\n```\n\n### Block Targets\n\n| Target | Use For |\n|--------|---------|\n| `section` | Product page, collection page content |\n| `body` | Global elements (popups, floating buttons) |\n\n---\n\n## App Embed (Global Script)\n\nFor loading global CSS and minimal JS across all pages:\n\n```liquid\n{% schema %}\n{\n  \"name\": \"App Embed\",\n  \"target\": \"body\",\n  \"enabled_by_default\": true,\n  \"settings\": []\n}\n{% endschema %}\n\n{% comment %} Load styles globally {% endcomment %}\n{{ ''styles.css'' | asset_url | stylesheet_tag }}\n\n{% comment %} Minimal JS - forms, interactions only {% endcomment %}\n<script src=\"{{ ''app-embed.js'' | asset_url }}\" defer></script>\n\n{% comment %} Pass data to JS {% endcomment %}\n<script>\n  window.APP_CONFIG = {\n    shopDomain: ''{{ shop.permanent_domain }}'',\n    customerId: ''{{ customer.id | default: \"\" }}'',\n    locale: ''{{ request.locale.iso_code }}''\n  };\n</script>\n```\n\n---\n\n## App Proxy Integration\n\n### Configure in shopify.app.toml\n\n```toml\n[app_proxy]\nurl = \"https://<firebase-url>/clientApi\"\nsubpath = \"app-name\"\nsubpath_prefix = \"apps\"\n```\n\n### Fetch Data via App Proxy\n\n```liquid\n{% comment %}\n  App proxy URL: /apps/app-name/endpoint\n  Shopify adds shop param automatically\n{% endcomment %}\n\n{% assign api_url = shop.url | append: ''/apps/app-name/data/'' | append: resource.id %}\n```\n\n### Backend Handler\n\n```javascript\n// clientApi controller - receives ''shop'' query param from app proxy\nexport async function getData(ctx) {\n  const shopDomain = ctx.query.shop;\n  const {id} = ctx.params;\n\n  const shop = await shopRepository.getShopByShopifyDomain(shopDomain);\n  if (!shop) {\n    ctx.body = {success: false, error: ''Shop not found''};\n    return;\n  }\n\n  const data = await service.getData(shop.id, id);\n  ctx.body = data;\n}\n```\n\n---\n\n## Async Data Fetching with Loading States\n\nWhen blocks need dynamic data from app proxy, use loading states for good UX.\n\n### HTML Structure\n\n```liquid\n{% comment %}\n  Generic async widget pattern\n  - Unique IDs using resource ID (product, collection, page, etc.)\n  - Data attributes for JS configuration\n  - Loading/content/error states\n{% endcomment %}\n\n{% assign widget_id = product.id | default: collection.id | default: ''global'' %}\n\n<div class=\"app-widget\"\n     data-resource-id=\"{{ widget_id }}\"\n     data-resource-type=\"{{ resource_type | default: ''product'' }}\"\n     data-shop=\"{{ shop.permanent_domain }}\"\n     id=\"app-widget-{{ widget_id }}\">\n\n  <div class=\"app-widget__loading\" id=\"app-loading-{{ widget_id }}\">\n    <span class=\"app-widget__spinner\"></span>\n    {{ ''app.loading'' | t | default: ''Loading...'' }}\n  </div>\n\n  <div class=\"app-widget__content\" id=\"app-content-{{ widget_id }}\" style=\"display: none;\">\n    {%- comment -%} Content populated by JS {%- endcomment -%}\n  </div>\n\n  <div class=\"app-widget__error\" id=\"app-error-{{ widget_id }}\" style=\"display: none;\">\n    {{ ''app.error'' | t | default: ''Unable to load content'' }}\n  </div>\n</div>\n```\n\n### JavaScript Pattern\n\n```javascript\n(function() {\n  // Configuration\n  var PROXY_PATH = ''/apps/proxy'';  // Your app proxy path\n  var ENDPOINT = ''/data'';          // Your endpoint\n\n  // Get elements\n  var containers = document.querySelectorAll(''.app-widget'');\n\n  containers.forEach(function(container) {\n    var resourceId = container.dataset.resourceId;\n    var resourceType = container.dataset.resourceType;\n    var shop = container.dataset.shop;\n\n    var loadingEl = document.getElementById(''app-loading-'' + resourceId);\n    var contentEl = document.getElementById(''app-content-'' + resourceId);\n    var errorEl = document.getElementById(''app-error-'' + resourceId);\n\n    async function fetchData() {\n      try {\n        var params = new URLSearchParams({\n          resource_id: resourceId,\n          resource_type: resourceType,\n          shop: shop\n        });\n\n        var response = await fetch(PROXY_PATH + ENDPOINT + ''?'' + params);\n        var result = await response.json();\n\n        if (!result.success) {\n          throw new Error(result.error || ''Request failed'');\n        }\n\n        if (!result.data) {\n          container.dataset.hidden = ''true'';\n          return;\n        }\n\n        renderContent(result.data, result.settings);\n        loadingEl.style.display = ''none'';\n        contentEl.style.display = ''block'';\n      } catch (error) {\n        console.error(''Widget error:'', error);\n        loadingEl.style.display = ''none'';\n        errorEl.style.display = ''block'';\n      }\n    }\n\n    function renderContent(data, settings) {\n      // Build your HTML from data\n      contentEl.innerHTML = buildHTML(data, settings);\n    }\n\n    // Initialize on DOM ready\n    if (document.readyState === ''loading'') {\n      document.addEventListener(''DOMContentLoaded'', fetchData);\n    } else {\n      fetchData();\n    }\n  });\n})();\n```\n\n### CSS Utilities\n\n```css\n/* Loading spinner */\n.app-widget__spinner {\n  width: 16px;\n  height: 16px;\n  border: 2px solid #e5e5e5;\n  border-top-color: var(--app-accent-color, #008060);\n  border-radius: 50%;\n  animation: app-spin 0.8s linear infinite;\n}\n\n@keyframes app-spin {\n  to { transform: rotate(360deg); }\n}\n\n/* Hide widget when no data */\n.app-widget[data-hidden=\"true\"] {\n  display: none;\n}\n\n/* Loading state */\n.app-widget__loading {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 16px;\n  color: #666;\n}\n\n/* Error state */\n.app-widget__error {\n  padding: 16px;\n  color: #c00;\n  text-align: center;\n}\n```\n\n### Key Points\n\n| Aspect | Recommendation |\n|--------|----------------|\n| Unique IDs | Use resource ID (product, collection, etc.) for uniqueness |\n| Loading state | Always show spinner while fetching |\n| Error handling | Show user-friendly error, hide widget on failure |\n| Empty state | Use `data-hidden=\"true\"` to hide when no data |\n| Translations | Use Liquid `t` filter for user-facing text |\n\n---\n\n## Liquid-First Rendering\n\n### Server-Side Data Display\n\n```liquid\n{% comment %} Data from metafields or app proxy {% endcomment %}\n{% assign items = product.metafields.app_namespace.items.value %}\n\n{% if items.size > 0 %}\n  <div class=\"items-list\">\n    {% for item in items %}\n      {% render ''item-card'', item: item %}\n    {% endfor %}\n  </div>\n{% else %}\n  <p class=\"no-items\">{{ ''app.no_items'' | t }}</p>\n{% endif %}\n```\n\n### Reusable Snippets\n\n```liquid\n{% comment %} snippets/rating-display.liquid {% endcomment %}\n{% comment %}\n  @param value {number} - Value to display\n  @param max {number} - Maximum value\n  @param size {string} - ''small'' | ''medium'' | ''large''\n{% endcomment %}\n\n<div class=\"rating-display rating-display--{{ size | default: ''medium'' }}\">\n  {% for i in (1..max) %}\n    {% if i <= value %}\n      <span class=\"rating-unit rating-unit--filled\"></span>\n    {% else %}\n      <span class=\"rating-unit rating-unit--empty\"></span>\n    {% endif %}\n  {% endfor %}\n</div>\n```\n\n---\n\n## Minimal JavaScript Pattern\n\n### When JS is Needed\n\n| Use JS For | Keep in Liquid |\n|------------|----------------|\n| Form submission | Static content display |\n| File upload | Badges and indicators |\n| Pagination/load more | Product lists |\n| Real-time validation | SEO content |\n\n### Minimal JS Structure\n\n```javascript\n// assets/app-embed.js\n\n(function() {\n  ''use strict'';\n\n  const config = window.APP_CONFIG || {};\n\n  // Form handling\n  function initForms() {\n    document.querySelectorAll(''[data-app-form]'').forEach(form => {\n      form.addEventListener(''submit'', handleSubmit);\n    });\n  }\n\n  async function handleSubmit(e) {\n    e.preventDefault();\n    const form = e.target;\n    const data = new FormData(form);\n\n    try {\n      const response = await fetch(form.action, {\n        method: ''POST'',\n        body: JSON.stringify(Object.fromEntries(data)),\n        headers: {''Content-Type'': ''application/json''}\n      });\n\n      const result = await response.json();\n      if (result.success) {\n        showMessage(form, ''success'', result.data.message);\n      } else {\n        showMessage(form, ''error'', result.error);\n      }\n    } catch (err) {\n      showMessage(form, ''error'', ''Something went wrong'');\n    }\n  }\n\n  // Initialize when DOM ready\n  if (document.readyState === ''loading'') {\n    document.addEventListener(''DOMContentLoaded'', initForms);\n  } else {\n    initForms();\n  }\n})();\n```\n\n---\n\n## Translations\n\n### Locale File Structure\n\n```json\n{\n  \"app\": {\n    \"title\": \"Feature Title\",\n    \"submit\": \"Submit\",\n    \"success\": \"Submitted successfully\",\n    \"error\": \"Something went wrong\",\n    \"no_items\": \"No items yet\"\n  }\n}\n```\n\n### Using Translations\n\n```liquid\n{% comment %} In Liquid {% endcomment %}\n{{ ''app.title'' | t }}\n\n{% comment %} With variables {% endcomment %}\n{{ ''app.count'' | t: count: items.size }}\n```\n\n---\n\n## Performance Guidelines\n\n### Do''s\n\n| Practice | Why |\n|----------|-----|\n| Render in Liquid | Server-side = faster |\n| Use snippets | Reusable, cacheable |\n| Defer JS loading | Non-blocking |\n| Scope CSS | Avoid conflicts |\n\n### Don''ts\n\n| Avoid | Why |\n|-------|-----|\n| Heavy JS frameworks | Bundle size |\n| Inline styles | Cache miss |\n| Blocking scripts | Slow page load |\n| Fetch on page load | Delays rendering |\n\n---\n\n## Checklist\n\n### Block Development\n\n```\n- Schema defines all settings\n- Uses snippets for reusable parts\n- Translations for all text\n- Scoped CSS (no global pollution)\n- Minimal/no inline JS\n```\n\n### App Proxy Integration\n\n```\n- shopify.app.toml configured\n- Backend validates shop parameter\n- Returns JSON for JS consumption\n- HTML rendering for Liquid consumption\n```\n\n### Performance\n\n```\n- JS deferred or async\n- CSS in stylesheet (not inline)\n- Images lazy loaded\n- No external dependencies\n- Bundle < 20KB total\n```"},"lastSynced":"2026-03-08T02:11:31.383Z","agentAnalysis":{"suitability":{"en":"Ideal for E-commerce Development Agents requiring server-side rendering for high-performance Shopify storefronts.","zh":"适用于需要服务器端渲染以实现高性能Shopify商店的电子商务开发代理。","ja":"高性能Shopifyストアのサーバーサイドレンダリングを必要とするEコマース開発エージェントに適しています。","ko":"고성능 Shopify 스토어를 위한 서버 사이드 렌더링이 필요한 전자상거래 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo de comercio electrónico que requieren renderizado en el lado del servidor para tiendas en línea de alta performance de Shopify.","fr":"Idéal pour les agents de développement de commerce électronique nécessitant un rendu côté serveur pour des storefronts Shopify à haute performance.","de":"Ideal für E-Commerce-Entwicklungsagenten, die Server-seitiges Rendering für hochleistungsstarke Shopify-Storefronts benötigen.","pt":"Ideal para Agentes de Desenvolvimento de Comércio Eletrônico que exigem renderização no lado do servidor para lojas da Shopify de alto desempenho.","ru":"Идеально подходит для агентов разработки электронной коммерции, требующих серверной отрисовки для магазинов Shopify с высокими показателями производительности.","ar":"مثالية للوكلاء الذين يطورون التطبيقات التجارية الإلكترونية التي تتطلب تحويل الخادم الجانبي لمتاجر Shopify ذات الأداء العالي."},"recommendation":{"en":"Enables agents to leverage Shopify''s native Liquid rendering for server-side content delivery, providing optimal storefront performance and SEO-critical product displays without client-side processing overhead.","zh":"使代理能够利用Shopify的原生Liquid渲染实现服务器端内容传递，从而提供最佳的商店性能和SEO关键的产品显示，而无需客户端处理开销。","ja":"エージェントがShopifyのネイティブLiquidレンダリングを利用してサーバーサイドコンテンツ配信を可能にし、クライアントサイドの処理オーバーヘッドなく、最適なストアパフォーマンスとSEOクリティカルな製品表示を提供します。","ko":"에이전트가 Shopify의 네이티브 Liquid 렌더링을 사용하여 서버 사이드 콘텐츠 전달을 가능하게 해 주어, 클라이언트 사이드 처리 오버헤드 없이 최적의 스토어 성능과 SEO에 중요한 제품 표시를 제공합니다.","es":"Permite a los agentes aprovechar el renderizado nativo de Liquid de Shopify para la entrega de contenido en el lado del servidor, proporcionando un rendimiento óptimo de la tienda en línea y mostrando productos críticos para SEO sin sobrecarga de procesamiento en el lado del cliente.","fr":"Permet aux agents d''exploiter le rendu Liquid natif de Shopify pour la livraison de contenu côté serveur, offrant des performances de storefront optimales et des affichages de produits critiques pour le SEO sans surcharge de traitement côté client.","de":"Ermöglicht es den Agenten, Shopifys natives Liquid-Rendering für die serverseitige Inhaltslieferung zu nutzen, wodurch optimaler Storefront-Performance und SEO-kritische Produktanzeige ohne Client-seitige Verarbeitungsüberlastung bereitgestellt wird.","pt":"Permite que os agentes aproveitem a renderização nativa do Liquid da Shopify para entrega de conteúdo no lado do servidor, fornecendo desempenho ótimo da loja e exibições de produtos críticas para SEO sem sobrecarga de processamento do lado do cliente.","ru":"Позволяет агентам использовать родную систему рендеринга Liquid от Shopify для доставки контента на стороне сервера, обеспечивая оптимальную производительность магазина и отображение продуктов, критически важных для SEO, без дополнительной нагрузки на обработку на стороне клиента.","ar":"تمكن الوكلاء من استخدام نظام الليكويد الأصلي من شوبيفاي لتقديم المحتوى على جانب الخادم، مما يوفر أداءً أمثل للمتجر وعرض المنتجات الحاسم لتحسين محركات البحث دون الحاجة إلى معالجة جانب العميل."},"useCases":{"en":["Rendering static/semi-static content blocks","Implementing SEO-optimized product displays","Developing server-rendered theme components"],"zh":["渲染静态/半静态内容块","实施SEO优化的产品显示","开发服务器渲染的主题组件"],"ja":["静的/半静的コンテンツブロックのレンダリング","SEO最適化された製品表示の実装","サーバーサイドレンダリングされたテーマコンポーネントの開発"],"ko":["정적/반정적 콘텐츠 블록 렌더링","SEO 최적화된 제품 표시 구현","서버 사이드 렌더링된 테마 컴포넌트 개발"],"es":["Renderizado de bloques de contenido estáticos/semiestáticos","Implementación de pantallas de productos optimizadas para SEO","Desarrollo de componentes de tema renderizados en el servidor"],"fr":["Renderisation de blocs de contenu statiques/semi-statiques","Mise en œuvre d''affichages de produits optimisés pour le SEO","Développement de composants de thème rendus côté serveur"],"de":["Rendering statischer/halb-statischer Inhaltsblöcke","Implementierung SEO-optimierter Produktanzeigen","Entwicklung serverseitig gerendeter Theme-Komponenten"],"pt":["Renderização de blocos de conteúdo estáticos/semi-estáticos","Implementação de exibições de produtos otimizados para SEO","Desenvolvimento de componentes de temas renderizados no servidor"],"ru":["Отрисовка статических/полу-статических блоков контента","Реализация отображений продуктов, оптимизированных для SEO","Разработка компонентов тем, отрисовываемых на стороне сервера"],"ar":["تجسيد كتل المحتوى الثابت/شبه ثابت","تنفيذ عروض المنتجات المُحسّنة لتحسين محركات البحث","تطوير مكونات السمات المرسومة على الخادم"]},"limitations":{"en":["Not suitable for highly interactive widgets requiring real-time updates","Limited to Shopify''s Liquid templating system","Requires Theme App Extension deployment structure"],"zh":["不适合需要实时更新的高交互式小部件","仅限Shopify的Liquid模板系统","需要主题应用扩展部署结构"],"ja":["リアルタイム更新が必要な高インタラクティブウィジェットには不適","ShopifyのLiquidテンプレートシステムに限定","テーマアプリ拡張デプロイ構造が必要"],"ko":["실시간 업데이트가 필요한 고互동 위젯에는 부적합","Shopify의 Liquid 템플릿 시스템에만限定","테마 앱 확장 배포 구조가 필요"],"es":["No es adecuado para widgets altamente interactivos que requieren actualizaciones en tiempo real","Limitado al sistema de plantillas de Liquid de Shopify","Requiere estructura de implementación de Theme App Extension"],"fr":["N''est pas adapté pour les widgets hautement interactifs nécessitant des mises à jour en temps réel","Limité au système de modèles de Liquid de Shopify","Nécessite une structure de déploiement d''extension d''application de thème"],"de":["Nicht geeignet für hochinteraktive Widgets, die Echtzeit-Aktualisierungen erfordern","Begrenzt auf Shopifys Liquid-Vorlagen-System","Benötigt Theme-App-Extension-Implementierungsstruktur"],"pt":["Não é adequado para widgets altamente interativos que exigem atualizações em tempo real","Limitado ao sistema de modelagem de líquido da Shopify","Exige estrutura de implantação da extensão do aplicativo de tema"],"ru":["Не подходит для высокоинтерактивных виджетов, требующих обновлений в реальном времени","Ограничен системой шаблонов Liquid от Shopify","Требует структуры развертывания расширения темы приложения"],"ar":["لا يناسب الويدجتس التفاعلية عالية التي تتطلب التحديثات في الوقت الفعلي","محدود بنظام القوالب السائلة من شوبيفاي","يتطلب هيكل تطبيق إمتداد تطبيق السمات"]},"version":4},"contentHash":"26b6f47dec9fab443ea989b0599e5f640c71059b16155225d689a7904f79237b","qualityScore":57}');
