INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('niznik-dev/cruijff_kit/analyze-experiment', 'analyze-experiment', 'niznik-dev', 'cruijff_kit', 'community', 'analyze-experiment niznik-dev cruijff_kit community The analyze-experiment skill helps users visualize and analyze results from completed experiments by generating interactive HTML and PNG plots. It benefits researchers and developers working with LLMs analyze-experiment工具帮助用户可视化和分析实验结果，生成交互式HTML和PNG图表 analyze-experiment AIエージェントは、実験結果を可視化し、分析するためのツールです analyze-experiment는 실험 결과를 시각화하고 분석하는 데 사용되는 도구입니다 Analyze-experiment es una herramienta para visualizar y analizar resultados de experimentos con herramientas de investigación social y LLM Analyze-experiment est un outil pour visualiser et analyser les résultats d''expériences avec des outils de recherche sociale et LLM Analyze-experiment ist ein Tool zur Visualisierung und Analyse von Ergebnissen von Experimenten mit Tools für soziale Forschung und LLM O analyze-experiment é uma ferramenta para conduzir pesquisas sociais com LLMs, permitindo a geração de visualizações interativas com inspect-viz. ИИ Агент analyze-experiment предназначен для проведения социальных исследований с LLMs, обеспечивая генерацию интерактивных визуализаций с inspect-viz. analyze-experiment هو أداة للبحث الاجتماعي مع LLMs، تسمح بإنشاء تصورات تفاعلية مع inspect-viz. how to use analyze-experiment what is analyze-experiment analyze-experiment alternative analyze-experiment vs inspect-viz analyze-experiment install analyze-experiment setup guide LLM research tools social research analysis analyze-experiment 可视化工具 实验结果分析 inspect-viz 实验设计 评估日志 Generates interactive HTML plots using inspect-viz Loads evaluation logs from run directories Infers appropriate visualization types based on experimental variables Reads experiment design from experiment_summary.yaml files Logs the process in log files analyze-experiment is a tool for conducting social research with LLMs, providing interactive visualizations and analysis of experiment results');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MichaelVessia/grove/logging-best-practices', 'community', 'MichaelVessia', 'grove', 'MichaelVessia/grove', 'logging-best-practices', 0, 0, 57, '2026-03-08T01:57:15.582Z', '2026-03-08T02:11:53.727Z', '06006d35dda37debf82eff64ecb7bd13085ada13c54b51dc8d99ac970094588b', '{"id":"MichaelVessia/grove/logging-best-practices","name":"logging-best-practices","description":{"en":"The logging-best-practices skill enables instrumentation design for AI agents, utilizing Grove''s structured NDJSON event log. It benefits developers by providing a comprehensive logging solution.","zh":"Grove日志最佳实践提供结构化的NDJSON事件日志，帮助开发者高效记录和调试事件","ja":"Groveのログ記録ベストプラクティスは、構造化されたNDJSONイベントログを提供し、開発者の効率的なイベント記録とデバッグを支援します","ko":"Grove 로깅 최적화 방법은 구조화된 NDJSON 이벤트 로그를 제공하여 개발자의 효율적인 이벤트 기록 및 디버깅을 지원합니다","es":"Grove utiliza un registro de eventos estructurados NDJSON para grabar eventos de depuración, incluyendo renderizado de frames, cambios de estado y comandos de tmux","fr":"Grove utilise un journal d''événements structuré NDJSON pour enregistrer les événements de débogage, y compris le rendu de frames, les changements d''état et les commandes tmux","de":"Grove verwendet ein strukturiertes NDJSON-Event-Log, um Debug-Events aufzuzeichnen, einschließlich Frame-Renderings, Statusänderungen und tmux-Befehlen","pt":"As melhores práticas de logging para desenvolvedores, com foco em instrumentação de design eficaz com Grove.","ru":"Лучшие практики логирования для ИИ Агентов, с фокусом на эффективном проектировании инструментов с Grove.","ar":"أفضل الممارسات لتسجيل السجلات لمنشئي التطبيقات, مع تركيز على تصميم أدوات التطبيق الفعال مع Grove."},"seo":{"title":{"en":"Logging-Best-Practices: NDJSON Event Logging Setup Guide ...","zh":"AI工具：日志最佳实践设置指南","ja":"AIエージェント：ログ記録ベストプラクティスガイド","ko":"AI 에이전트: 로깅 최적화 설정 가이드","es":"Herramientas de registro de AI: Mejores prácticas de logging","fr":"Outils d''agent IA : Guide de configuration du logging","de":"AI-Agent-Tools: Logging-Best-Practices-Setup","pt":"Melhores Práticas de Logging: Guia de Configuração para D...","ru":"Лучшие практики логирования: Настройка для ИИ Агентов","ar":"أفضل الممارسات لتسجيل السجلات: دليل الإعداد لمنشئي التطبيقات"},"description":{"en":"Unlock efficient logging with Grove''s structured NDJSON event log. Learn how to toggle --debug-record and optimize your event logging setup today!","zh":"了解Grove日志最佳实践，实现高效的事件记录和调试，提升开发效率","ja":"Groveのログ記録ベストプラクティスをマスターし、効率的なイベント記録とデバッグを行う","ko":"Grove 로깅 최적화 방법을 익히고 효율적인 이벤트 기록 및 디버깅을 수행하세요","es":"Aprende a implementar las mejores prácticas de logging con Grove, incluyendo la configuración de NDJSON y la grabación de eventos de depuración","fr":"Découvrez comment mettre en œuvre les meilleures pratiques de logging avec Grove, y compris la configuration de NDJSON et l''enregistrement d''événements de dé...","de":"Erfahren Sie, wie Sie mit Grove die besten Logging-Praktiken umsetzen, einschließlich NDJSON-Konfiguration und Debug-Event-Aufzeichnung","pt":"Aprenda a configurar o logging de forma eficaz com as melhores práticas para desenvolvedores. Descubra como otimizar a instrumentação de design com Grove.","ru":"Узнайте, как настроить логирование эффективно с лучшими практиками для ИИ Агентов. Откройте для себя, как оптимизировать проектирование инструментов с Grove.","ar":"تعرف على كيفية_setup تسجيل السجلات بفعالية مع أفضل الممارسات لمنشئي التطبيقات. اكتشف كيفية تحسين تصميم أدوات التطبيق مع Grove."},"definition":{"en":"logging-best-practices is a skill for designing instrumentation, utilizing a structured NDJSON event log toggled by --debug-record for efficient event logging.","zh":"日志最佳实践是指在Grove中使用结构化的NDJSON事件日志进行事件记录和调试","ja":"ログ記録ベストプラクティスとは、Groveで構造化されたNDJSONイベントログを使用してイベントを記録し、デバッグを行うこと","ko":"로깅 최적화 방법은 Grove에서 구조화된 NDJSON 이벤트 로그를 사용하여 이벤트를 기록하고 디버깅하는 것","es":"Las mejores prácticas de logging son técnicas para grabar y almacenar eventos de depuración en aplicaciones, como Grove","fr":"Les meilleures pratiques de logging sont des techniques pour enregistrer et stocker les événements de débogage dans les applications, comme Grove","de":"Die besten Logging-Praktiken sind Techniken zur Aufzeichnung und Speicherung von Debug-Events in Anwendungen wie Grove","pt":"As melhores práticas de logging referem-se a técnicas de registro de eventos estruturados em NDJSON.","ru":"Лучшие практики логирования относятся к методам регистрации структурированных событий в NDJSON.","ar":"أفضل الممارسات لتسجيل السجلات هي تقنيات لتسجيل الأحداث المنظمة في NDJSON."},"features":{"en":["Utilizes Grove''s structured NDJSON event log for efficient logging","Toggles event logging via the --debug-record command","Writes events to .grove/debug-record-{app_start_ts}-{pid}.jsonl files","Discards events at zero cost when logging is disabled using NullEventLogger","Logs every frame render, state change, input, tmux command, and polling event"],"zh":["结构化的NDJSON事件日志","高效的事件记录和调试","通过--debug-record启用日志记录","NullEventLogger用于禁用日志记录","支持每帧渲染、状态变化、输入、tmux命令和轮询事件的记录"],"ja":["構造化されたNDJSONイベントログ","効率的なイベント記録とデバッグ","--debug-recordを使用したログ記録の有効化","NullEventLoggerを使用したログ記録の無効化","毎フレームレンダリング、状態変更、入力、tmuxコマンド、ポーリングイベントの記録をサポート"],"ko":["구조화된 NDJSON 이벤트 로그","효율적인 이벤트 기록 및 디버깅","--debug-record를 사용한 로깅 활성화","NullEventLogger를 사용한 로깅 비활성화","매 프레임 렌더링, 상태 변경, 입력, tmux 명령, 폴링 이벤트 기록 지원"],"es":["Registro de eventos estructurados NDJSON","Grabación de eventos de depuración con --debug-record","Discarding de eventos sin costo con NullEventLogger","Soporte para renderizado de frames, cambios de estado y comandos de tmux","Configuración de logging personalizable"],"fr":["Journal d''événements structuré NDJSON","Enregistrement d''événements de débogage avec --debug-record","Rejet d''événements sans coût avec NullEventLogger","Prise en charge du rendu de frames, des changements d''état et des commandes tmux","Configuration de logging personnalisable"],"de":["Strukturiertes NDJSON-Event-Log","Aufzeichnung von Debug-Events mit --debug-record","Verwerfen von Events ohne Kosten mit NullEventLogger","Unterstützung für Frame-Rendering, Statusänderungen und tmux-Befehle","Anpassbare Logging-Konfiguration"],"pt":["Registro de eventos estruturados em NDJSON","Instrumentação de design com Grove","Otimização de performance com NullEventLogger","Suporte a renderização de frames e mudanças de estado","Integração com comandos tmux e eventos de polling"],"ru":["Регистрация структурированных событий в NDJSON","Проектирование инструментов с Grove","Оптимизация производительности с NullEventLogger","Поддержка рендеринга фреймов и изменений состояния","Интеграция с командами tmux и событиями опроса"],"ar":["تسجيل الأحداث المنظمة في NDJSON","تصميم أدوات التطبيق مع Grove","تحسين الأداء مع NullEventLogger","دعم عرض الإطارات وتغييرات الحالة","تكامل مع أوامر tmux وأحداث الاستطلاع"]},"keywords":{"en":["logging-best-practices setup guide","how to use logging-best-practices","what is logging-best-practices","logging-best-practices alternative","NDJSON event logging tutorial","Grove logging best practices","logging-best-practices install","logging-best-practices vs other logging tools"],"zh":["Grove日志最佳实践","AI工具日志记录","NDJSON事件日志","结构化日志记录","高效事件记录","Grove调试"],"ja":["Groveログ記録ベストプラクティス","AIエージェントログ記録","NDJSONイベントログ","構造化ログ記録","効率的なイベント記録","Groveデバッグ"],"ko":["Grove 로깅 최적화","AI 에이전트 로깅","NDJSON 이벤트 로그","구조화된 로깅","효율적인 이벤트 기록","Grove 디버깅"],"es":["mejores prácticas de logging","registro de eventos","Grove logging","NDJSON","debugging","depuración de aplicaciones","herramientas de registro de AI"],"fr":["meilleures pratiques de logging","journal d''événements","Grove logging","NDJSON","débogage","débogage d''applications","outils d''agent IA"],"de":["beste Logging-Praktiken","Event-Log","Grove Logging","NDJSON","Debugging","Anwendungs-Debugging","AI-Agent-Tools"],"pt":["melhores práticas de logging","instrumentação de design","Grove","NDJSON","registro de eventos","desenvolvedores","logging de aplicativos","otimização de performance"],"ru":["лучшие практики логирования","проектирование инструментов","Grove","NDJSON","регистрация событий","ИИ Агенты","логирование приложений","оптимизация производительности"],"ar":["أفضل الممارسات لتسجيل السجلات","تصميم أدوات التطبيق","Grove","NDJSON","تسجيل الأحداث","منشئي التطبيقات","تسجيل السجلات للتطبيقات","تحسين الأداء"]}},"owner":"MichaelVessia","repo":"grove","repoPath":"MichaelVessia/grove","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.582Z","topics":[],"category":"community","skillMd":{"name":"logging-best-practices","description":">","bodyPreview":"# Grove Logging Best Practices\n\nThis skill is for instrumentation design.\n\nIf the task is reproducing a bug from an existing trace, use\n`.agents/skills/replay-debug/SKILL.md` instead.\n\n## Architecture Overview\n\nGrove uses a structured NDJSON event log toggled by `--debug-record`. When\nenabled, every frame render, state change, input, tmux command, and polling\nevent is written to `.grove/debug-record-{app_start_ts}-{pid}.jsonl`. When\ndisabled, a `NullEventLogger` discards all events at zero cost.","body":"# Grove Logging Best Practices\n\nThis skill is for instrumentation design.\n\nIf the task is reproducing a bug from an existing trace, use\n`.agents/skills/replay-debug/SKILL.md` instead.\n\n## Architecture Overview\n\nGrove uses a structured NDJSON event log toggled by `--debug-record`. When\nenabled, every frame render, state change, input, tmux command, and polling\nevent is written to `.grove/debug-record-{app_start_ts}-{pid}.jsonl`. When\ndisabled, a `NullEventLogger` discards all events at zero cost.\n\nKey files:\n- `src/infrastructure/event_log.rs` -- `Event`, `EventLogger`, `FileEventLogger`, `NullEventLogger`\n- `src/ui/tui/logging_state.rs` -- state/dialog/tmux/toast event helpers\n- `src/ui/tui/logging_input.rs` -- input pipeline logging helpers\n- `src/ui/tui/logging_frame.rs` -- per-frame debug record payload\n- `src/ui/tui/update.rs` -- update timing + message handling logging\n- `src/main.rs` -- `--debug-record` flag parsing, path generation\n\n## Core Principles\n\n### 1. Wide Events Per Boundary (CRITICAL)\n\nEach log event should be a single, context-rich JSON object capturing\neverything relevant to that moment. Don''t scatter multiple narrow log lines\nacross a code path. Instead, build up context and emit one event at the\nboundary.\n\n**Good**: one `frame/rendered` event with seq, hash, mode, focus, degradation,\ndimensions, input queue state, and the full frame buffer.\n\n**Bad**: separate events for \"frame started\", \"frame mode is X\", \"frame\nfocus is Y\", \"frame done\".\n\n### 2. Event Identity: event + kind (CRITICAL)\n\nEvery event has two classification fields:\n\n- `event`: the category (e.g., `frame`, `tick`, `input`, `tmux_cmd`, `error`)\n- `kind`: the specific occurrence (e.g., `rendered`, `scheduled`, `interactive_key_received`)\n\nThis pair is the event''s identity. Choose names that read naturally as\n`event/kind`: `frame/rendered`, `tick/scheduled`, `input/interactive_forwarded`.\n\nUse `LogEvent::new(\"event\", \"kind\")` to create events. The timestamp is\ncaptured automatically.\n\n### 3. Rich Data Fields (CRITICAL)\n\nInclude high-cardinality fields (session names, frame hashes, input sequence\nnumbers) and high-dimensionality (many fields per event). The debug record\nexists for post-hoc diagnosis of issues you haven''t anticipated yet.\n\nAdd data with `.with_data(key, value)` or `.with_data_fields(vec![...])`:\n\n```rust\nself.event_log.log(\n    LogEvent::new(\"preview_poll\", \"capture_completed\")\n        .with_data(\"session\", Value::from(session.as_str()))\n        .with_data(\"capture_ms\", Value::from(capture_ms))\n        .with_data(\"changed\", Value::from(changed))\n        .with_data(\"output_bytes\", Value::from(output_bytes))\n        .with_data(\"total_ms\", Value::from(total_ms)),\n);\n```\n\n### 4. Timing at Boundaries (CRITICAL)\n\nMeasure and log durations for operations that touch external systems or do\nsignificant work. Use `Instant::now()` before and after, then log the delta\nas `_ms` suffixed fields.\n\nCommon patterns:\n- `capture_ms` / `total_ms` on preview captures\n- `tmux_send_ms` on input forwarding\n- `duration_ms` on tmux command completion\n- `draw_ms` / `view_ms` / `frame_log_ms` on frame rendering\n- `update_ms` on message handling\n- `input_to_preview_ms` / `tmux_to_preview_ms` for end-to-end input latency\n\n### 5. Zero Cost When Disabled (HIGH)\n\nAll logging goes through `self.event_log.log()` which dispatches to either\n`FileEventLogger` (writes to disk) or `NullEventLogger` (no-op). This means:\n\n- Don''t gate event construction behind `if self.debug_record_enabled` checks.\n  The `NullEventLogger` handles this.\n- Don''t do expensive computation solely for logging. If you need to compute\n  something expensive (like hashing frame lines), and it''s only useful for\n  logging, consider whether it should be part of the normal frame path.\n- Frame line extraction in `log_frame_render()` is an exception, it walks the\n  terminal buffer and is only called when debug recording is active.\n\n### 6. Sequence Numbers for Correlation (HIGH)\n\nUse monotonic sequence numbers to correlate events across the pipeline.\nInput events use `seq` (from `self.input_seq_counter`) to trace a keystroke\nfrom receipt through action selection, tmux forwarding, and preview update.\nFrames use `seq` (from `self.frame_render_seq`) for ordering.\n\nWhen adding a new pipeline, assign a counter and propagate `seq` through\nall related events so they can be joined during analysis.\n\n### 7. Consistent Field Names (HIGH)\n\nReuse existing field names when logging the same concept:\n\n| Concept | Field name | Type |\n|---|---|---|\n| Tmux session | `session` | string |\n| Workspace name | `workspace` | string |\n| Input sequence | `seq` | u64 |\n| Duration | `*_ms` suffix | u64 |\n| Success/failure | `ok` | bool |\n| Error message | `error` or `message` | string |\n| Queue state | `pending_depth` | usize |\n| Queue age | `oldest_pending_age_ms` | u64 |\n| Boolean state | `changed`, `repeat`, `cursor_visible` | bool |\n\n## Event Categories\n\n### Frame events (`frame/*`)\n\nLogged per frame render. Two events per frame:\n\n1. `frame/rendered` -- full frame state (only when `--debug-record` is active):\n   `seq`, `frame_lines`, `frame_hash`, `width`, `height`, `line_count`,\n   `non_empty_line_count`, `degradation`, `mode`, `focus`, `selected_workspace`,\n   `interactive_session`, `sidebar_width_pct`, `preview_offset`,\n   `preview_auto_scroll`, `output_changing`, `pending_input_depth`,\n   `oldest_pending_input_seq`, `oldest_pending_input_age_ms`, `app_start_ts`\n\n2. `frame/timing` -- performance metrics (always logged):\n   `draw_ms`, `view_ms`, `frame_log_ms`, `degradation`, `pending_depth`\n\n### Tick events (`tick/*`)\n\nPolling lifecycle: `scheduled`, `retained`, `processed`, `skipped`,\n`interactive_debounce_scheduled`. Always include `pending_depth` and\n`oldest_pending_age_ms` on scheduling events.\n\n### Input events (`input/*`)\n\nFull input pipeline: `interactive_key_received`, `interactive_action_selected`,\n`interactive_forwarded`, `interactive_input_to_preview`,\n`interactive_inputs_coalesced`. Always include `seq` and `session`.\n\n### Tmux events (`tmux_cmd/*`)\n\nCommand lifecycle: `execute` (with `command` string), `completed` (with\n`command`, `duration_ms`, `ok`, and `error` if failed).\n\n### State/mode events\n\nLow-frequency state transitions: `state_change/selection_changed`,\n`state_change/focus_changed`, `mode_change/mode_changed`,\n`mode_change/interactive_entered`, `mode_change/interactive_exited`.\n\n### Error events (`error/*`)\n\nFailures that need diagnosis: `error/tmux_error`. Include enough context\nto reproduce (command, session, error message).\n\n## Adding a New Event\n\n1. Choose `event` category and `kind` name. Check existing events in\n   `src/ui/tui/` to avoid category drift.\n\n2. Build the event at the boundary (completion of the operation, not the start):\n\n```rust\nself.event_log.log(\n    LogEvent::new(\"my_category\", \"my_kind\")\n        .with_data(\"relevant_field\", Value::from(value))\n        .with_data(\"duration_ms\", Value::from(elapsed_ms)),\n);\n```\n\n3. Include timing if the operation is non-trivial. Capture `Instant::now()`\n   before the operation and compute the delta after.\n\n4. Include queue/pipeline state if the event is part of a flow\n   (`pending_depth`, `seq`).\n\n5. If the new event changes replay interpretation, also update\n   `.agents/skills/replay-debug/SKILL.md`.\n\n## Anti-Patterns\n\n1. **Narrow events**: Don''t emit \"started\" / \"finished\" pairs when a single\n   completion event with `duration_ms` suffices. Exception: operations that\n   may never complete (like `tmux_cmd/execute` paired with `completed`).\n\n2. **Missing context**: Don''t log an error without the operation that caused\n   it. Include the command string, session name, and relevant state.\n\n3. **Unstructured strings**: Never `eprintln!()` for diagnostic info. Use\n   `self.event_log.log()` with structured data. The only `eprintln!` in the\n   codebase is for the debug record path at startup.\n\n4. **Logging in hot loops without gating**: Frame line extraction is expensive.\n   If you add similarly expensive logging, guard it behind\n   `self.debug_record_start_ts.is_some()` like `log_frame_render()` does.\n\n5. **Inconsistent field names**: Don''t use `elapsed` when the convention is\n   `duration_ms`. Don''t use `target_session` when the convention is `session`.\n\n6. **Missing sequence numbers**: If the event is part of an input or frame\n   pipeline, include `seq` so events can be correlated during analysis.\n\n## Frame Data: What and Why\n\nThe `frame/rendered` event captures the full terminal buffer because:\n\n- Visual bugs (flicker, blank frames, layout corruption) can only be diagnosed\n  by seeing exactly what was rendered\n- Frame hash enables change detection without comparing full content\n- `non_empty_line_count` catches blank frame regressions\n- `degradation` tracks frame budget health\n- `pending_input_depth` + `oldest_pending_input_age_ms` reveal input queue\n  pressure at render time\n\nThis is intentionally heavy data. It''s gated behind `--debug-record` and\nonly used during active debugging sessions.\n"},"lastSynced":"2026-03-08T02:11:53.727Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring comprehensive logging solutions with structured NDJSON event logs","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要全面日志解决方案和结构化的NDJSON事件日志","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しており、包括的なログ解決策と構造化されたNDJSONイベントログが必要","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합하며, 포괄적인 로깅 솔루션 및 구조화된 NDJSON 이벤트 로그가 필요","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren soluciones de registro integral con registros de eventos NDJSON estructurados","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant des solutions de journalisation complètes avec des journaux d''événements NDJSON structurés","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die umfassende Protokolllösungen mit strukturierten NDJSON-Ereignisprotokollen erfordern","pt":"Ideal para agentes de IA como Cursor, Windsurf e Claude Code que exigem soluções de registro abrangentes com logs de eventos NDJSON estruturados","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих комплексных решений для ведения журнала с структурированными журналами событий NDJSON","ar":"مثالي لعمليات الوكيل الإصطناعي مثل Cursor و Windsurf و Claude Code التي تتطلب حلول تسجيل شاملة مع سجلات أحداث NDJSON المنظمة"},"recommendation":{"en":"Empowers agents to instrument their desi