INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mohitmishra786/aurora-dev/frontend', 'frontend', 'mohitmishra786', 'aurora-dev', 'community', 'frontend mohitmishra786 aurora-dev community The frontend skill implements user interfaces with modern frameworks and best practices, benefiting developers who need to build responsive and interactive UI components. 前端开发涉及构建响应式UI组件、状态管理和CSS/Tailwind样式 フロントエンド開発は、レスポンシブなUIコンポーネント、状態管理、CSS/Tailwindスタイルを含みます 프론트엔드 개발은 반응형 UI 컴포넌트, 상태 관리, CSS/Tailwind 스타일을 포함합니다 El agente frontend implementa interfaces de usuario con frameworks modernos y mejores prácticas, incluyendo componentes reutilizables y gestión de estado L''agent frontend met en place des interfaces utilisateur avec des frameworks modernes et des meilleures pratiques, y compris des composants réutilisables et une gestion d''état Der Frontend-Agent implementiert Benutzeroberflächen mit modernen Frameworks und Best Practices, einschließlich wiederverwendbarer Komponenten und Zustandsverwaltung O agente frontend é um especialista em desenvolvimento de interfaces de usuário. Implementa componentes reutilizáveis e gerencia estado com tecnologias modernas. Агент фронтенда - специалист по созданию интерфейсов пользователя. Реализует многоразовые компоненты и управляет состоянием с помощью современных технологий. وكيل الواجهة الأمامية هو خبير في إنشاء واجهات المستخدم. ينفذ مكونات قابلة لإعادة الاستخدام ويدير الحالة باستخدام تقنيات حديثة. how to use frontend frontend vs backend frontend setup guide what is frontend development frontend alternative to React install frontend dependencies frontend UI component development frontend state management best practices frontend CSS/Tailwind styling tutorial 前端开发 UI组件 状态管理 CSS/Tailwind 响应式设计 原子设计模式 Zustand Redux Pinia React Query SWR Builds reusable UI components with atomic design pattern Implements global state management using Zustand, Redux, or Pinia Adds responsive design and styling with CSS/Tailwind Supports server state management with React Query or SWR Creates animations and interactive elements for enhanced user experience Frontend is a set of technologies and techniques used to build user interfaces and user experiences for web applications, utilizing frameworks like React and CSS/Tailwind.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kyle93afc/drawingregisterMJ/windows-app-developer', 'community', 'kyle93afc', 'drawingregisterMJ', 'kyle93afc/drawingregisterMJ', 'windows-app-developer', 0, 0, 57, '2026-03-08T01:57:15.587Z', '2026-03-08T02:11:58.109Z', '104e22d8ed6802a2ec34a50dfeb305b18ee7d705c3ad6a1d6d8035377fca17d1', '{"id":"kyle93afc/drawingregisterMJ/windows-app-developer","name":"windows-app-developer","description":{"en":"The Windows-App-Developer skill provides expertise in building modern Windows desktop applications using WinUI 3, WPF, and Windows App SDK, benefiting developers who need to create native Windows integrations and modern packaging with MSIX.","zh":"Windows 应用开发涉及使用 WinUI 3、WPF 和 Windows App SDK 构建现代 Windows 桌面应用程序，包括 XAML 布局和 MVVM 架构","ja":"Windows アプリ開発は、WinUI 3、WPF、Windows App SDK を使用してモダンな Windows デスクトップ アプリケーションを構築することを含み、XAML レイアウトと MVVM アーキテクチャを使用","ko":"Windows 애플리케이션 개발은 WinUI 3, WPF 및 Windows App SDK를 사용하여 현대적인 Windows 데스크톱 애플리케이션을 구축하는 것을 포함하며, XAML 레이아웃 및 MVVM 아키텍처를 사용","es":"El desarrollador de aplicaciones de Windows proporciona experiencia en la creación de aplicaciones de escritorio de Windows modernas con WinUI 3 y WPF.","fr":"Le développeur d''applications Windows offre une expertise dans la création d''applications de bureau Windows modernes avec WinUI 3 et WPF.","de":"Der Windows-App-Entwickler bietet Erfahrung bei der Erstellung moderner Windows-Desktop-Anwendungen mit WinUI 3 und WPF.","pt":"O Desenvolvedor de Aplicativos do Windows fornece especialização em desenvolvimento de UI baseado em XAML, arquitetura MVVM e integração nativa do Windows.","ru":"ИИ Агент для разработки приложений Windows обеспечивает специализацию в разработке интерфейса пользователя на основе XAML, архитектуре MVVM и родной интеграции с Windows.","ar":"مطور تطبيقات ويندوز يوفر تخصصا في تطوير واجهة المستخدم القائمة على XA