INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fakebizprez/cleanUpUntitled/google-apps-script', 'google-apps-script', 'fakebizprez', 'cleanUpUntitled', 'community', 'google-apps-script fakebizprez cleanUpUntitled community google-apps-script is a cloud-based JavaScript platform for automating Google Workspace services, benefiting developers and businesses. It provides server-side V8 runtime with automatic OAuth integration. Google Apps Script 是一个基于云的 JavaScript 平台，用于自动化 Google Workspace 服务，如 Sheets、Docs、Gmail、Drive 和 Calendar Google Apps Script は、Google Sheets、Docs、Gmail、Drive、Calendar などの Google Workspace サービスを自動化するためのクラウドベースの JavaScript プラットフォームです Google Apps Script는 Google Sheets, Docs, Gmail, Drive, Calendar 등의 Google Workspace 서비스를 자동화하기 위한 클라우드 기반의 JavaScript 플랫폼입니다 Google Apps Script es una plataforma de JavaScript en la nube para automatizar servicios de Google Workspace. Permite la automatización de tareas en Google Sheets, Docs, Gmail y más. Google Apps Script est une plateforme JavaScript basée sur le cloud pour automatiser les services Google Workspace. Elle permet l''automatisation de tâches dans Google Sheets, Docs, Gmail et plus. Google Apps Script ist eine Cloud-basierte JavaScript-Plattform zur Automatisierung von Google-Workspace-Diensten. Sie ermöglicht die Automatisierung von Aufgaben in Google Sheets, Docs, Gmail und mehr. O Google Apps Script é uma plataforma baseada em JavaScript para automação de serviços do Google Workspace, com integração OAuth e tempo de execução V8 Google Apps Script — облачная платформа JavaScript для автоматизации сервисов Google Workspace, с интеграцией OAuth и временем выполнения V8 سكريبت تطبيقات جوجل هو منصة جافاسكريبت سحابية لتلقيم خدمات جوجل ووركسبيس، مع دمج أوث ووقت تشغيل V8 how to use google-apps-script google-apps-script tutorial google-apps-script alternative google-apps-script vs zapier google-apps-script install google-apps-script setup guide automating google sheets with google-apps-script google-apps-script for gmail automation google-apps-script documentation Google Apps Script Google Workspace 自动化 JavaScript 平台 Google Sheets 自动化 Google Docs 编程 Gmail 消息管理 Google Drive 文件操作 Automates Google Sheets operations, including reading, writing, and formatting Creates and edits Google Docs programmatically Manages Gmail messages and sends emails Works with Google Drive files and folders Automates Google Calendar tasks google-apps-script is a cloud-based JavaScript platform for automating Google Workspace services, including Sheets, Docs, Gmail, Drive, and Calendar.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jaydee829/agentic_librarian/project-memory', 'community', 'jaydee829', 'agentic_librarian', 'jaydee829/agentic_librarian', 'project-memory', 0, 0, 57, '2026-03-08T01:57:15.595Z', '2026-03-08T02:12:05.217Z', '8e57092a9ba4fb581864fe5b4644eb42806660783baa8c278cc95941494e7d9e', '{"id":"jaydee829/agentic_librarian/project-memory","name":"project-memory","description":{"en":"project-memory is an agentic book recommender system designed for AI agents. It benefits developers seeking to integrate memory-aware behavior into their applications.","zh":"Project Memory是一个基于AI的书籍推荐系统，提供创建记忆基础设施、配置记忆行为和多工具支持等功能","ja":"Project MemoryはAIベースの本のレコメンドシステムで、記憶インフラストラクチャの作成、記憶行為の設定、多ツールサポートなどを提供","ko":"Project Memory는 AI 기반의 도서 추천 시스템으로, 기억 인프라스트럭처 생성, 기억 행동 설정, 다중 도구 지원 등","es":"Project Memory es un sistema de recomendación de libros basado en AI que permite crear infraestructura de memoria y configurar comportamientos. Aprende a configurar este sistema para mejorar tus recomendaciones de libros","fr":"Project Memory est un système de recommandation de livres basé sur l''IA qui permet de créer une infrastructure de mémoire et de configurer des comportements. Apprenez à configurer ce système pour améliorer vos recommandations de livres","de":"Project Memory ist ein Buchempfehlungssystem basierend auf KI, das die Erstellung einer Speicherinfrastruktur und die Konfiguration von Verhaltensweisen ermöglicht. Erfahren Sie, wie Sie dieses System konfigurieren, um Ihre Buchempfehlungen zu verbessern","pt":"O Project Memory é um sistema de recomendação de livros baseado em IA que utiliza infraestrutura de memória e comportamento baseado em GEMINI.md para fornecer recomendações personalizadas.","ru":"Project Memory - это система рекомендации книг на основе ИИ, которая использует инфраструктуру памяти и поведение на основе GEMINI.md для предоставления персонализированных рекомендаций.","ar":"مشروع الذاكرة هو نظام توصية الكتب الذكي الذي يستند إلى الذكاء الاصطناعي ويشمل بنية تحتية للذاكرة وسلوك مبني على GEMINI.md لتقديم توصيات personnalisée"},"seo":{"title":{"en":"project-memory: Setup Guide for AI Agents | AI Agent Skill","zh":"Project Memory Setup Guide - AIエージェント书籍推荐系统","ja":"Project Memory Setup Guide - AIエージェントによる本のレコメンドシステム","ko":"Project Memory Setup Guide - AI 에이전트 도서 추천 시스템","es":"Guía de configuración de Project Memory - Recomendador de...","fr":"Guide de configuration de Project Memory - Système de rec...","de":"Konfigurationsleitfaden für Project Memory - Buchempfehlu...","pt":"Guia de Configuração do Project Memory - Sistema de Recom...","ru":"Настройка Project Memory - Система Рекомендации Книг ИИ А...","ar":"دليل إعداد مشروع الذاكرة - نظام توصية الكتب الذكي"},"description":{"en":"Discover how to configure project-memory for optimal performance. Learn to create memory infrastructure and leverage multi-tool support for your AI agent needs.","zh":"了解Project Memory的功能和配置方法，包括创建记忆基础设施、配置GEMINI.md和AGENTS.md等","ja":"Project Memoryの機能と設定方法を学び、記憶インフラストラクチャの作成、GEMINI.mdとAGENTS.mdの設定など","ko":"Project Memory의 기능과 설정 방법을 알아보며, 기억 인프라스트럭처 생성, GEMINI.md와 AGENTS.md 설정 등","es":"Aprende a configurar Project Memory, un sistema de recomendación de libros basado en AI. Descubre cómo crear infraestructura de memoria y configurar comporta...","fr":"Découvrez comment configurer Project Memory, un système de recommandation de livres basé sur l''IA. Apprenez à créer une infrastructure de mémoire et à config...","de":"Erfahren Sie, wie Sie Project Memory konfigurieren, ein Buchempfehlungssystem basierend auf KI. Entdecken Sie, wie Sie eine Speicherinfrastruktur erstellen u...","pt":"Aprenda a configurar o Project Memory, um sistema de recomendação de livros baseado em IA, com recursos de infraestrutura de memória e comportamento baseado ...","ru":"Узнайте, как настроить Project Memory, систему рекомендации книг на основе ИИ, с функциями инфраструктуры памяти и поведения на основе GEMINI.md","ar":"تعرف على كيفية إعداد مشروع الذاكرة، نظام توصية الكتب الذكي الذي يستند إلى الذكاء الاصطناعي، مع ميزات البنية التحتية للذاكرة وسلوك مبني على GEMINI.md"},"definition":{"en":"project-memory is an AI agent skill that enables the creation of a memory infrastructure for book recommendations.","zh":"Project Memory是一种AIエージェント书籍推荐系统，用于创建和管理记忆","ja":"Project MemoryはAIエージェントによる本のレコメンドシステムで、記憶の作成と管理に使用","ko":"Project Memory는 AI 에이전트 도서 추천 시스템으로, 기억을 생성하고 관리","es":"Project Memory es un sistema de recomendación de libros basado en AI que utiliza infraestructura de memoria para proporcionar recomendaciones personalizadas","fr":"Project Memory est un système de recommandation de livres basé sur l''IA qui utilise une infrastructure de mémoire pour fournir des recommandations personnalisées","de":"Project Memory ist ein Buchempfehlungssystem basierend auf KI, das eine Speicherinfrastruktur nutzt, um personalisierte Empfehlungen zu liefern","pt":"O Project Memory é um sistema de recomendação de livros que utiliza inteligência artificial para fornecer recomendações personalizadas.","ru":"Project Memory - это система рекомендации книг, которая использует искусственный интеллект для предоставления персонализированных рекомендаций.","ar":"مشروع الذاكرة هو نظام توصية الكتب الذي يستند إلى الذكاء الاصطناعي لتقديم توصيات personnalisée"},"features":{"en":["Initial Setup - Create Memory Infrastructure","Configure GEMINI.md for memory-aware behavior","Configure AGENTS.md for multi-tool support","Searching Memory Files for efficient data retrieval"],"zh":["创建记忆基础设施","配置GEMINI.md记忆行为","配置AGENTS.md多工具支持","搜索记忆文件","支持多种工具和技术"],"ja":["記憶インフラストラクチャの作成","GEMINI.md記憶行為の設定","AGENTS.md多ツールサポートの設定","記憶ファイルの検索","多種のツールと技術をサポート"],"ko":["기억 인프라스트럭처 생성","GEMINI.md 기억 행동 설정","AGENTS.md 다중 도구 지원 설정","기억 파일 검색","다중 도구와 기술 지원"],"es":["Creación de infraestructura de memoria","Configuración de comportamientos de memoria","Compatibil