INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('aget-framework/aget/aget-review-budget', 'aget-review-budget', 'aget-framework', 'aget', 'community', 'aget-review-budget aget-framework aget community The aget-review-budget skill provides financial analysis and optimization recommendations for AI agents, enabling data-driven budget decisions. It benefits developers and financial analysts by streamlining budget reviews. AGET Framework 代理人预算审查功能提供预算分配、投资回报率和资源分配分析 AGET Framework AIエージェントの予算レビュー機能は、予算割り当て、投資収益率、リソース配分を分析する AGET Framework AI 에이전트 예산 검토 기능은 예산 할당, 투자 수익률 및 리소스 분배를 분석합니다 aget-review-budget es una herramienta de análisis de presupuesto para agentes de codificación colaborativa que proporciona recomendaciones de optimización aget-review-budget est un outil d''analyse budgétaire pour les agents de codage collaboratif qui fournit des recommandations d''optimisation aget-review-budget ist ein Budgetanalyse-Tool für kollaborative Codierungsagenten, das Optimierungs-Empfehlungen liefert O aget-review-budget é uma ferramenta de análise de orçamento que fornece recomendações de otimização de recursos. Ele categoriza despesas, calcula ROI e fornece análise financeira. aget-review-budget - это инструмент анализа бюджета, который предоставляет рекомендации по оптимизации ресурсов. Он категоризирует расходы, рассчитывает ROI и предоставляет финансовый анализ для ИИ Агентов aget-review-budget هو أداة لمراجعة الميزانية توفر توصيات لتحسين الموارد. يقوم بتصنيف النفقات وحساب العائد على الاستثمار وتقديم تحليل مالي لأدوات الذكاء الاصطناعي how to use aget-review-budget aget-review-budget alternative aget-review-budget setup guide what is aget-review-budget aget-review-budget vs financial analysis tools aget-review-budget install financial analysis for AI agents budget optimization with aget-review-budget CLI-based financial analysis AGET Framework 代理人 预算审查 投资回报率分析 资源分配优化 CLI-based人工智能协作编码代理 AI代理人开发 预算管理工具 Gathers budget data, including planned allocation, actual expenditure, and time period scope Categorizes expenditures by type, department/project, and priority Calculates ROI, including investment amount, return measurement, and ROI percentage Provides financial analysis and optimization recommendations Supports CLI-based human-AI collaborative coding agents aget-review-budget is a canonical specification for CLI-based human-AI collaborative coding agents, providing financial analysis and optimization capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('srnnkls/tropos/bash-use', 'community', 'srnnkls', 'tropos', 'srnnkls/tropos', 'bash-use', 0, 0, 57, '2026-03-08T01:57:15.654Z', '2026-03-08T02:13:55.538Z', '125898359da06d6eab220a7a03f266d8b715da1af7d8a780fdc9ee29b83fcad1', '{"id":"srnnkls/tropos/bash-use","name":"bash-use","description":{"en":"The bash-use skill provides patterns for interactive bash commands, one-liners, and CLI usage, benefiting developers who need to construct shell commands and debug CLI interactions.","zh":"Bash Use提供了构造shell命令、写入one-liners和交互式CLI使用的功能","ja":"Bash Useはシェルコマンドの構築、one-linersの書き方、インタラクティブCLIの使用方法を提供します","ko":"Bash Use는 쉘 명령어 구축, one-liners 작성, 상호작용 CLI 사용 및 디버깅을 지원합니다","es":"bash-use es una habilidad para patrones de comandos interactivos de bash, líneas de comando y uso de CLI. Permite la construcción de comandos de shell y la depuración de comandos CLI.","fr":"bash-use est une compétence pour les modèles de commandes interactives bash, les lignes de commande et l''utilisation de CLI. Elle permet la construction de commandes shell et le débogage de commandes CLI.","de":"bash-use ist eine Fähigkeit für Muster interaktiver bash-Befehle, Befehlszeilen und CLI-Nutzung. Sie ermöglicht die Erstellung von Shell-Befehlen und die Fehlersuche bei CLI-Befehlen.","pt":"O skill bash-use fornece padrões para comandos Bash interativos, one-liners e uso de CLI.","ru":"Навык bash-use предоставляет шаблоны для интерактивных команд Bash, one-liners и использования CLI.","ar":"المهارة bash-use توفر أنماطا لأوامر Bash التفاعلية و one-liners واستخدام CLI."},"seo":{"title":{"en":"bash-use: Mastering Interactive Bash Commands | AI Agent ...","zh":"Bash Use Setup Guide: CLI 命令行工具","ja":"Bash Use ベストプラクティス: AIエージェントによるCLI操作","ko":"Bash Use 사용법: CLI 명령어 및 디버깅","es":"Guía de configuración de bash-use para comandos interactivos","fr":"Configurer bash-use pour les commandes interactives CLI","de":"Bash-use Einrichtungsleitfaden für interaktive Shell-Befehle","pt":"Guia de Uso de Bash: Melhores Práticas para Comandos Inte...","ru":"ИИ Агенты: Руководство по Использованию Bash для Интеракт...","ar":"دليل استخدام Bash: إرشادات لاستخدام أوامر Bash التفاعلية"},"description":{"en":"Unlock the full potential of bash-use! Learn how to construct shell commands, write one-liners, and debug CLI usage with our expert guide. Get started now!","zh":"了解Bash Use的功能和特点，包括构造shell命令、写入one-liners和交互式CLI使用","ja":"Bash Useの機能と特徴を紹介します。シェルコマンドの構築、one-linersの書き方、インタラクティブCLIの使用方法など","ko":"Bash Use의 기능과 특징을 살펴보세요. 쉘 명령어 구축, one-liners 작성, 상호작용 CLI 사용 및 디버깅","es":"Aprende a utilizar bash-use para construir comandos de shell, escribir líneas de comando y depurar comandos CLI con nuestra guía","fr":"Découvrez comment utiliser bash-use pour construire des commandes shell, écrire des lignes de commande et déboguer des commandes CLI avec notre guide","de":"Erfahren Sie, wie Sie bash-use verwenden können, um Shell-Befehle zu erstellen, Befehlszeilen zu schreiben und CLI-Befehle zu debuggen mit unserer Anleitung","pt":"Aprenda a usar comandos Bash interativos, one-liners e uso de CLI com nossas dicas e truques","ru":"Изучите интерактивные команды Bash, one-liners и использование CLI с помощью наших советов и хитростей","ar":"تعلم كيفية استخدام أوامر Bash التفاعلية و one-liners واستخدام CLI مع نصائحنا وأفكارنا"},"definition":{"en":"bash-use is a skill that enables efficient use of bash commands, including quoting paths with spaces, using relative paths with rm, and chaining commands.","zh":"Bash Use是一种用于构造shell命令和交互式CLI使用的技能","ja":"Bash Useはシェルコマンドの構築とインタラクティブCLIの使用を支援するAIエージェントのスキル","ko":"Bash Use는 쉘 명령어 구축과 상호작용 CLI 사용을 지원하는 스킬","es":"bash-use es una habilidad que proporciona patrones para comandos interactivos de bash y uso de CLI","fr":"bash-use est une compétence qui fournit des modèles pour les commandes interactives bash et l''utilisation de CLI","de":"bash-use ist eine Fähigkeit, die Muster für interaktive bash-Befehle und CLI-Nutzung bereitstellt","pt":"Bash-use é um skill que fornece padrões para comandos Bash interativos e uso de CLI.","ru":"Bash-use - это навык, который предоставляет шаблоны для интерактивных команд Bash и использования CLI.","ar":"Bash-use هي مهارة توفر أنماطا لأوامر Bash التفاعلية واستخدام CLI."},"features":{"en":["Constructs shell commands with quoted paths and spaces","Writes one-liners for efficient CLI usage","Supports interactive CLI usage with command debugging","Chains commands using && and ; operators","Uses relative paths with rm for efficient file management","Debugs and improves command performance"],"zh":["构造shell命令","写入one-liners","交互式CLI使用","命令调试和改进","支持相对路径和绝对路径","支持命令链式执行"],"ja":["シェルコマンドの構築","one-linersの書き方","インタラクティブCLIの使用","コマンドのデバッグと改善","相対パスと絶対パスのサポート","コマンドの連携実行"],"ko":["쉘 명령어 구축","one-liners 작성","상호작용 CLI 사용","명령어 디버깅과 개선","상대 경로와 절대 경로 지원","명령어 연속 실행"],"es":["Construcción de comandos de shell con bash","Uso de líneas de comando para tareas automatizadas","Depuración de comandos CLI con bash-use","Uso de rutas relativas con rm","Encadenamiento de comandos con && y ;"],"fr":["Construction de commandes shell avec bash","Utilisation de lignes de commande pour des tâches automatisées","Débogage de commandes CLI avec bash-use","Utilisation de chemins relatifs avec rm","Enchaînement de commandes avec && et ;"],"de":["Erstellung von Shell-Befehlen mit bash","Verwendung von Befehlszeilen für automatisierte Aufgaben","Fehlersuche bei CLI-Befehlen mit bash-use","Verwendung von relativen Pfaden mit rm","Verkettung von Befehlen mit && und ;"],"pt":["Construção de comandos shell","Uso de one-liners","Uso interativo de CLI","Depuração e melhoria de comandos","Citação de caminhos com espaços","Uso de caminhos relativos com rm"],"ru":["Конструкция команд shell","Использование one-liners","Интерактивное использование CLI","Отладка и улучшение команд","Цитирование путей с пробелами","Использование относительных путей с rm"],"ar":["بناء أوامر shell","استخدام one-liners","استخدام CLI التفاعلي","تصحيح الأخطاء وتحسين الأوامر","citation مسارات مع пробелات","استخدام مسارات نسبية مع rm"]},"keywords":{"en":["how to use bash-use","bash-use tutorial","bash-use alternative","bash-use vs zsh","bash-use install","bash-use setup guide","bash one-liners","interactive bash commands","CLI usage examples"],"zh":["Bash Use","CLI命令行工具","shell命令","one-liners","交互式CLI","命令调试","AIエージェント","CLI使用"],"ja":["Bash Use","AIエージェント","シェルコマンド","one-liners","インタラクティブCLI","コマンドのデバッグ","CLIの使用","シェルスクリプト"],"ko":["Bash Use","CLI 명령어","쉘 명령어","one-liners","상호작용 CLI","명령어 디버깅","AI 도구","CLI 사용"],"es":["bash-use","comandos interactivos de bash","líneas de comando","uso de CLI","construcción de comandos de shell","depuración de comandos CLI","herramientas de bash","comandos de shell","automatización de tareas"],"fr":["bash-use","commandes interactives bash","lignes de commande","utilisation de CLI","construction de commandes shell","débogage de commandes CLI","outils de bash","commandes shell","automatisation de tâches"],"de":["bash-use","interaktive bash-Befehle","Befehlszeilen","CLI-Nutzung","Erstellung von Shell-Befehlen","Fehlersuche bei CLI-Befehlen","bash-Tools","Shell-Befehle","Automatisierung von Aufgaben"],"pt":["bash use","comandos bash interativos","one-liners bash","uso de cli","construção de comandos shell","depuração de comandos","melhoria de comandos","citação de caminhos","caminhos relativos"],"ru":["bash use","интерактивные команды bash","one-liners bash","использование cli","конструкция команд shell","отладка команд","улучшение команд","цитирование путей","относительные пути"],"ar":["bash use","أوامر bash التفاعلية","one-liners bash","استخدام cli","بناء أوامر shell","تصحيح أخطاء الأوامر","تحسين الأوامر","citation مسارات","مسارات نسبية"]}},"owner":"srnnkls","repo":"tropos","repoPath":"srnnkls/tropos","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.654Z","topics":[],"category":"community","skillMd":{"name":"bash-use","description":"Ultra-concise bash command patterns. Use when constructing shell commands or one-liners.","bodyPreview":"# Bash Use Skill\n\nPatterns for interactive bash commands, one-liners, and CLI usage.\n\n---\n\n## When to Use\n\n- Constructing shell commands\n- Writing one-liners\n- Interactive CLI usage\n- Command debugging or improvement\n\n---\n\n## Quick Reference\n\n**Quote paths with spaces:**\n```bash\ncd \"/path with spaces/dir\"\n```\n\n**Relative paths with rm:**\n```bash\nrm -rf ./build  # Not $HOME/...\n```\n\n**Chain commands:**\n```bash\ncmd1 && cmd2 && cmd3  # Stop on failure\ncmd1; cmd2; cmd3      # Continue regardless\n```","body":"# Bash Use Skill\n\nPatterns for interactive bash commands, one-liners, and CLI usage.\n\n---\n\n## When to Use\n\n- Constructing shell commands\n- Writing one-liners\n- Interactive CLI usage\n- Command debugging or improvement\n\n---\n\n## Quick Reference\n\n**Quote paths with spaces:**\n```bash\ncd \"/path with spaces/dir\"\n```\n\n**Relative paths with rm:**\n```bash\nrm -rf ./build  # Not $HOME/...\n```\n\n**Chain commands:**\n```bash\ncmd1 && cmd2 && cmd3  # Stop on failure\ncmd1; cmd2; cmd3      # Continue regardless\n```\n\n**Command substitution:**\n```bash\nresult=$(command)  # Not `command`\n```\n\n**Check command exists:**\n```bash\ncommand -v jq &>/dev/null || echo \"not found\"\n```\n\n**Output redirection:**\n```bash\ncommand 2>&1        # Stderr to stdout\ncommand &>/dev/null # Suppress all\n```\n\n**Process substitution:**\n```bash\ndiff <(cmd1) <(cmd2)\n```\n\n---\n\n## Full Guidelines\n\n**Read:** `~/.claude/skills/code-implement/resources/loqui/languages/bash/reference/commands.md`\n\nUse Read tool to access (paths outside cwd require direct reads).\n\n---\n\n## Anti-Patterns Checklist\n\n- ✘ Unquoted paths with spaces\n- ✘ Absolute paths with `rm`\n- ✘ Using `;` when `&&` is needed\n- ✘ Backticks instead of `$()`\n\n---\n\n## Related Skills\n\n- **code-implement**: Language-specific patterns (includes bash)\n- **code-test**: TDD workflow\n"},"lastSynced":"2026-03-08T02:13:55.538Z","agentAnalysis":{"suitability":{"en":"Ideal for CLI-focused Agents needing advanced bash command construction and debugging capabilities.","zh":"适合需要高级bash命令构造和调试功能的CLI专注代理。","ja":"CLIに焦点を当てたエージェントが高度なbashコマンド構築およびデバッグ機能を必要とする場合に最適です。","ko":"고급 bash 명령어 생성 및 디버깅 기능이 필요한 CLI 중심 에이전트에 적합합니다.","es":"Ideal para agentes enfocados en CLI que necesitan una construcción de comandos bash avanzada y capacidades de depuración.","fr":"Idéal pour les agents axés sur CLI nécessitant une construction de commande bash avancée et des capacités de débogage.","de":"Ideal für CLI-fokussierte Agenten, die eine erweiterte bash-Befehlskonstruktion und Debugging-Fähigkeiten benötigen.","pt":"Ideal para Agentes focados em CLI que necessitam de construção avançada de comandos bash e capacidades de depuração.","ru":"Идеально для агентов, ориентированных на CLI, которым необходимы продвинутые возможности построения команд bash и отладки.","ar":"مثالي لعميل CLI الذي يحتاج إلى بناء أوامر bash متقدم وقدرات فحص أخطاء."},"recommendation":{"en":"Empowers agents to construct complex shell commands, utilize one-liners, and debug CLI interactions with precision, leveraging techniques like quoting paths with spaces and chaining commands with conditional execution.","zh":"赋予代理构造复杂shell命令、利用一行命令和使用诸如引号路径中的空格和条件执行的命令链等技术来调试CLI交互的能力。","ja":"エージェントに複雑なシェルコマンドを構築し、ワンライナーを利用し、パスの空白を引用符で囲むなどの技術や条件付き実行によるコマンドの連結などの手法を利用してCLIのやり取りを正確にデバッグする能力を付与します。","ko":"에이전트가 복잡한 쉘 명령어를 생성하고, 일라이너를 사용하며, 경로의 공백을 따옴표로囲む 등의 기술과 조건부 실행을 통한 명령어 연결 등을 사용하여 CLI 상호작용을 정밀하게 디버깅할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a construir comandos de shell complejos, utilizar uno-liners y depurar interacciones de CLI con precisión, aprovechando técnicas como citar rutas con espacios y encadenar comandos con ejecución condicional.","fr":"Permet aux agents de construire des commandes shell complexes, d''utiliser des one-liners et de déboguer les interactions CLI avec précision, en exploitant des techniques comme la citation de chemins avec des espaces et le chainage de commandes avec exécution conditionnelle.","de":"Ermächtigt Agenten, komplexe Shell-Befehle zu konstruieren, One-Liner zu nutzen und CLI-Interaktionen mit Präzision zu debuggen, indem Techniken wie das Zitieren von Pfaden mit Leerzeichen und das Verketteten von Befehlen mit bedingter Ausführung eingesetzt werden.","pt":"Habilita os agentes a construir comandos de shell complexos, utilizar one-liners e depurar interações CLI com precisão, aproveitando técnicas como citar caminhos com espaços e encadear comandos com execução condicional.","ru":"Позволяет агентам строить сложные команды оболочки, использовать один лайнер и отлаживать взаимодействия CLI с точностью, используя такие методы, как цитирование путей с пробелами и цепочечное выполнение команд с условной логикой.","ar":"يمكن للوكلاء بناء أوامر شل معقدة واستخدام واحد لاینر وتصحيح التفاعلات مع واجهة سطر الأوامر بدقة، مستفيداً من تقنيات مثل اقتباس المسارات مع الفواصل وربط الأوامر بتنفيذ مشروط."},"useCases":{"en":["Constructing dynamic shell commands","Debugging interactive CLI interactions","Writing efficient one-liners for automation"],"zh":["构造动态shell命令","调试交互式CLI交互","编写高效的一行命令以实现自动化"],"ja":["動的シェルコマンドの構築","対話式CLIのやり取りのデバッグ","自動化のための効率的なワンライナーの作成"],"ko":["동적 쉘 명령어 생성","대화식 CLI 상호작용 디버깅","자동화를 위한 효율적인 일라이너 작성"],"es":["Construir comandos de shell dinámicos","Depurar interacciones de CLI interactivas","Escribir one-liners eficientes para la automatización"],"fr":["Construire des commandes shell dynamiques","Déboguer les interactions CLI interactives","Écrire des one-liners efficaces pour l''automatisation"],"de":["Dynamische Shell-Befehle konstruieren","Interaktive CLI-Interaktionen debuggen","Effiziente One-Liner für die Automatisierung schreiben"],"pt":["Construir comandos de shell dinâmicos","Depurar interações CLI interativas","Escrever one-liners eficientes para automação"],"ru":["Строить динамические команды оболочки","Отлаживать интерактивные взаимодействия CLI","Писать эффективные один лайнер для автоматизации"],"ar":["بناء أوامر شل ديناميكية","تصحيح التفاعلات التفاعلية لواجهة سطر الأوامر","كتابة واحد لاینر فعالة للآليّة"]},"limitations":{"en":["Requires bash compatibility","Limited to command-line interface interactions"],"zh":["需要bash兼容性","仅限于命令行接口交互"],"ja":["bashの互換性が必要","コマンドラインインターフェースのやり取りのみに限定"],"ko":["bash 호환성이 필요","커맨드 라인 인터페이스 상호작용에만 제한"],"es":["Requiere compatibilidad con bash","Limitado a interacciones de interfaz de línea de comandos"],"fr":["Nécessite la compatibilité bash","Limité aux interactions d''interface de ligne de commande"],"de":["Benötigt bash-Kompatibilität","Begrenzt auf Kommandozeilen-Schnittstellen-Interaktionen"],"pt":["Requer compatibilidade com bash","Limitado a interações de interface de linha de comando"],"ru":["Требует совместимости с bash","Ограничен до взаимодействий с командной строкой"],"ar":["يتطلب توافقاً مع باش","محدود إلى تفاعلات واجهة سطر الأوامر"]},"version":4},"contentHash":"125898359da06d6eab220a7a03f266d8b715da1af7d8a780fdc9ee29b83fcad1","qualityScore":57}');
