INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('srnnkls/tropos/bash-use', 'bash-use', 'srnnkls', 'tropos', 'community', 'bash-use srnnkls tropos community The bash-use skill provides patterns for interactive bash commands, one-liners, and CLI usage, benefiting developers who need to construct shell commands and debug CLI interactions. Bash Use提供了构造shell命令、写入one-liners和交互式CLI使用的功能 Bash Useはシェルコマンドの構築、one-linersの書き方、インタラクティブCLIの使用方法を提供します Bash Use는 쉘 명령어 구축, one-liners 작성, 상호작용 CLI 사용 및 디버깅을 지원합니다 bash-use es una habilidad para patrones de comandos interactivos de bash, líneas de comando y uso de CLI. Permite la construcción de comandos de shell y la depuración de comandos CLI. bash-use est une compétence pour les modèles de commandes interactives bash, les lignes de commande et l''utilisation de CLI. Elle permet la construction de commandes shell et le débogage de commandes CLI. bash-use ist eine Fähigkeit für Muster interaktiver bash-Befehle, Befehlszeilen und CLI-Nutzung. Sie ermöglicht die Erstellung von Shell-Befehlen und die Fehlersuche bei CLI-Befehlen. O skill bash-use fornece padrões para comandos Bash interativos, one-liners e uso de CLI. Навык bash-use предоставляет шаблоны для интерактивных команд Bash, one-liners и использования CLI. المهارة bash-use توفر أنماطا لأوامر Bash التفاعلية و one-liners واستخدام CLI. how to use bash-use bash-use tutorial bash-use alternative bash-use vs zsh bash-use install bash-use setup guide bash one-liners interactive bash commands CLI usage examples Bash Use CLI命令行工具 shell命令 one-liners 交互式CLI 命令调试 AIエージェント CLI使用 Constructs shell commands with quoted paths and spaces Writes one-liners for efficient CLI usage Supports interactive CLI usage with command debugging Chains commands using && and ; operators Uses relative paths with rm for efficient file management Debugs and improves command performance bash-use is a skill that enables efficient use of bash commands, including quoting paths with spaces, using relative paths with rm, and chaining commands.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nibzard/skills-kit/brand-illustrator', 'community', 'nibzard', 'skills-kit', 'nibzard/skills-kit', 'brand-illustrator', 0, 0, 57, '2026-03-08T01:57:15.662Z', '2026-03-08T02:14:08.808Z', '197af8d48191ae6f770ce071fce3dac5e99bed430b9be69891f668a32f5c3a33', '{"id":"nibzard/skills-kit/brand-illustrator","name":"brand-illustrator","description":{"en":"The brand-illustrator Skill generates hand-drawn line illustrations that match a visual identity, producing icons with primary objects and bold accent colors. This benefits developers and designers seeking consistent branding.","zh":"品牌插画工具是一种生成手绘线条插图的工具，具有暖白色画布、自信的黑色墨线和大胆的强调色","ja":"ブランドイラストレーターは手描き線画イラストを生成するツールで、暖白色のキャンバス、自信のある黒色のインク線、そして大胆なアクセントカラーを備えています","ko":"브랜드 일러스트레이터는 수기 선화 일러스트를 생성하는 도구로 따뜻한 흰색 캔버스와 자신감 있는 검은색 잉크 선, 그리고 대담한 강조 색상을 갖추고 있습니다","es":"El ilustrador de marca es una colección de habilidades del agente que genera ilustraciones a mano alzada que se ajustan a la identidad visual","fr":"L''illustrateur de marque est un ensemble de compétences de l''agent qui génère des illustrations au trait qui correspondent à l''identité visuelle","de":"Der Markenillustrator ist eine Sammlung von Agentenfähigkeiten, die handgezeichnete Illustrationen erstellt, die zur visuellen Identität passen","pt":"O brand-illustrator é uma coleção de habilidades de agente que gera ilustrações de linha personalizadas que correspondem à identidade visual da Builder Methods.","ru":"Brand-illustrator - это коллекция навыков агента, генерирующая индивидуальные линейные иллюстрации, соответствующие визуальной идентичности Builder Methods.","ar":"أداة brand-illustrator هي مجموعة من مهارات الوكيل التي تولد رسومات خطية مخصصة تتوافق مع الهوية البصرية لشركة Builder Methods."},"seo":{"title":{"en":"brand-illustrator: Hand-Drawn Illustration Generation for...","zh":"品牌插画工具设置指南 - Brand Illustrator","ja":"ブランドイラストレーター設定ガイド - AIエージェント","ko":"브랜드 일러스트레이터 설정 가이드 - AI 도구","es":"Guía de configuración del ilustrador de marca","fr":"Guide de mise en place de l''illustrateur de marque","de":"Einrichtungsleitfaden für den Markenillustrator","pt":"Guia de Configuração do brand-illustrator para Ilustraçõe...","ru":"ИИ Агенты: Руководство по настройке brand-illustrator","ar":"إعداد أداةbrand-illustrator لرسومات العلامة التجارية"},"description":{"en":"Discover how brand-illustrator generates on-brand concepts with warm off-white canvas and confident black ink lines. Get started with this reusable Skill today!","zh":"了解品牌插画工具的功能和特点，包括生成手绘线条插图和一致的风格","ja":"ブランドイラストレーターの機能と特徴を紹介します - 手描き線画イラストと一貫したスタイル","ko":"브랜드 일러스트레이터의 기능과 특징을紹介합니다 - 수기 선화 일러스트와 일관된 스타일","es":"Aprende a utilizar el ilustrador de marca para generar ilustraciones a mano alzada que se ajusten a tu identidad visual","fr":"Découvrez comment utiliser l''illustrateur de marque pour générer des illustrations au trait qui correspondent à votre identité visuelle","de":"Erfahren Sie, wie Sie den Markenillustrator verwenden, um handgezeichnete Illustrationen zu erstellen, die zu Ihrer visuellen Identität passen","pt":"Aprenda a configurar o brand-illustrator para criar ilustrações de marca personalizadas com identidade visual única","ru":"Откройте для себя, как настроить brand-illustrator для создания индивидуальных иллюстраций бренда с уникальной визуальной идентичностью","ar":"تعرف على كيفية إعداد أداة brand-illustrator لإنشاء رسومات علامة تجارية مخصصة مع هوية بصرية فريدة"},"definition":{"en":"brand-illustrator is a reusable and procedural Skill that generates hand-drawn line illustrations with a warm off-white canvas, confident black ink lines, and one bold accent color.","zh":"品牌插画工具是一种用于生成手绘线条插图的AI工具","ja":"ブランドイラストレーターは手描き線画イラストを生成するAIエージェントの一種です","ko":"브랜드 일러스트레이터는 수기 선화 일러스트를 생성하는 AI 도구의 일종입니다","es":"Un ilustrador de marca es una herramienta de inteligencia artificial que genera ilustraciones a mano alzada","fr":"Un illustrateur de marque est un outil d''intelligence artificielle qui génère des illustrations au trait","de":"Ein Markenillustrator ist ein künstliches Intelligenz-Tool, das handgezeichnete Illustrationen erstellt","pt":"O brand-illustrator é uma habilidade de agente que gera ilustrações de marca personalizadas","ru":"Brand-illustrator - это навык агента, генерирующий индивидуальные иллюстрации бренда","ar":"أداة brand-illustrator هي مهارة وكيل تولد رسومات علامة تجارية مخصصة"},"features":{"en":["Generates hand-drawn line illustrations with a warm off-white canvas","Produces icons with primary objects and bold accent colors","Uses a style and color system for consistent branding","Allows for gathering requirements and proposing on-brand concepts","Enables generation of final images consistently using the style and color system"],"zh":["生成手绘线条插图","暖白色画布和自信的黑色墨线","一致的风格和色彩系统","支持生成图标和图像","可重用和程序化的设计"],"ja":["手描き線画イラストの生成","暖白色のキャンバスと自信のある黒色のインク線","一貫したスタイルと色彩システム","アイコンと画像の生成をサポート","再利用可能かつ程序化された設計"],"ko":["수기 선화 일러스트의 생성","따뜻한 흰색 캔버스와 자신감 있는 검은색 잉크 선","일관된 스타일과 색상 시스템","아이콘과 이미지의 생성을 지원","재사용 가능하고 프로그램화된 설계"],"es":["Genera ilustraciones a mano alzada que se ajustan a la identidad visual","Utiliza un estilo de línea de tinta negra confiada y un color de acento atrevido","Permite la generación de iconos con un objeto principal aislado","Se integra con el sistema de estilo y color","Es reutilizable y procedimental","Permite la selección de conceptos y la generación de imágenes finales"],"fr":["Génère des illustrations au trait qui correspondent à l''identité visuelle","Utilise un style de ligne d''encre noire confiante et une couleur d''accent audacieuse","Permet la génération d''icônes avec un objet principal isolé","S''intègre avec le système de style et de couleur","Est réutilisable et procédural","Permet la sélection de concepts et la génération d''images finales"],"de":["Erstellt handgezeichnete Illustrationen, die zur visuellen Identität passen","Verwendet einen Stil mit schwarzer Tusche und einem mutigen Akzentfarbe","Ermöglicht die Erstellung von Iconen mit einem isolierten Hauptobjekt","Integriert sich in das Style- und Farbsystem","Ist wiederverwendbar und prozedural","Ermöglicht die Auswahl von Konzepten und die Erstellung von Endbildern"],"pt":["Geração de ilustrações de linha personalizadas","Uso de identidade visual única da Builder Methods","Capacidade de criar ícones isolados","Uso de sistema de cores personalizadas","Geração de imagens finais consistentes","Proposta de três conceitos personalizados"],"ru":["Генерация индивидуальных линейных иллюстраций","Использование уникальной визуальной идентичности Builder Methods","Возможность создания изолированных иконок","Использование системы персонализированных цветов","Генерация финальных изображений с постоянным качеством","Предложение трех персонализированных концепций"],"ar":["توليد رسومات خطية مخصصة","استخدام الهوية البصرية الفريدة لشركة Builder Methods","قدرة على إنشاء أيقونات معزولة","استخدام نظام الألوان المخصص","توليد صور نهائية متسقة","اقتراح ثلاثة مفاهيم مخصصة"]},"keywords":{"en":["how to use brand-illustrator","brand-illustrator setup guide","brand-illustrator alternative","brand-illustrator vs illustration tools","brand-illustrator install","what is brand-illustrator","brand-illustrator tutorial","brand-illustrator for AI Agents","brand-illustrator procedural generation"],"zh":["品牌插画工具","AI工具","手绘线条插图","暖白色画布","自信的黑色墨线","一致的风格","色彩系统","图标生成","图像生成"],"ja":["ブランドイラストレーター","AIエージェント","手描き線画イラスト","暖白色のキャンバス","自信のある黒色のインク線","一貫したスタイル","色彩システム","アイコン生成","画像生成"],"ko":["브랜드 일러스트레이터","AI 도구","수기 선화 일러스트","따뜻한 흰색 캔버스","자신감 있는 검은색 잉크 선","일관된 스타일","색상 시스템","아이콘 생성","이미지 생성"],"es":["ilustrador de marca","herramientas de inteligencia artificial","ilustraciones a mano alzada","identidad visual","diseño gráfico","generación de iconos","sistema de estilo y color","agente de inteligencia artificial"],"fr":["illustrateur de marque","outils d''intelligence artificielle","illustrations au trait","identité visuelle","conception graphique","génération d''icônes","système de style et de couleur","agent d''intelligence artificielle"],"de":["Markenillustrator","künstliche Intelligenz-Tools","handgezeichnete Illustrationen","visuelle Identität","Grafikdesign","Erstellung von Iconen","Style- und Farbsystem","künstlicher Intelligenz-Agent"],"pt":["brand-illustrator","ilustrações de marca","identidade visual","Builder Methods","ícones personalizados","sistema de cores","ilustrações de linha","agente de ilustração","ferramentas de design"],"ru":["brand-illustrator","иллюстрации бренда","визуальная идентичность","Builder Methods","персонализированные иконки","система цветов","линейные иллюстрации","агент иллюстраций","инструменты дизайна"],"ar":["brand-illustrator","رسومات علامة تجارية","هوية بصرية","شركة Builder Methods","أيقونات مخصصة","نظام الألوان","رسومات خطية","وكيل رسومات","أدوات التصميم"]}},"owner":"nibzard","repo":"skills-kit","repoPath":"nibzard/skills-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.662Z","topics":[],"category":"community","skillMd":{"name":"brand-illustrator","description":"Generate Builder Methods hand-drawn line art illustrations (icons, scenes, periphery) with a single accent color (Coral/Teal/Indigo/Amber). Use for blog headers, thumbnails, course graphics, social posts, and on-brand UI/tech metaphors.","bodyPreview":"# Builder Methods Brand Illustrator\n\nGenerate hand-drawn line illustrations that match the Builder Methods visual identity:\nwarm off-white canvas, confident black ink lines, and one bold accent color.\n\nThis Skill is designed to be *reusable* and *procedural*:\n- you gather requirements\n- you propose three on-brand concepts\n- you get a selection\n- you generate final image(s) consistently using our style + color system\n\n## What this Skill produces\n\n- **Icon**: 1 primary object, isolated, quick punc","body":"# Builder Methods Brand Illustrator\n\nGenerate hand-drawn line illustrations that match the Builder Methods visual identity:\nwarm off-white canvas, confident black ink lines, and one bold accent color.\n\nThis Skill is designed to be *reusable* and *procedural*:\n- you gather requirements\n- you propose three on-brand concepts\n- you get a selection\n- you generate final image(s) consistently using our style + color system\n\n## What this Skill produces\n\n- **Icon**: 1 primary object, isolated, quick punctuation.\n- **Scene**: 2–4 objects, suggested environment, hero/header moments.\n- **Periphery**: 1–3 objects, used as corner/edge elements or decorative supports.\n\nSee `references/visual-world.md` for the world + constraints and `references/style.md` for rendering rules.\n\n## Requirements\n\n- **Python 3.8+** for running the generation script\n- **google-genai package**: `pip install google-genai`\n- **GEMINI_API_KEY environment variable**: Set your Google Gemini API key as `GEMINI_API_KEY` (alternatively `GOOGLE_API_KEY` or `GENAI_API_KEY`)\n\nGet an API key from: https://ai.google.dev/\n\n## Quick Start\n\n1. **Create a project folder** (recommended) in `projects/` with today''s date and a short slug.\n\n   Example:\n   ```bash\n   mkdir -p projects/2026-01-13-blog-hero\n   ```\n\n2. **Gather requirements** — use the AskUserQuestion tool for each missing piece *one at a time*.\n   Required inputs:\n   - **Content context**: topic + the core idea (insight), or paste article/transcript\n   - **Visual context**: where the illustration will live (page screenshot, layout notes), or “n/a”\n   - **Accent color**: `coral` | `teal` | `indigo` | `amber`\n   - **Image type**: `icon` | `scene` | `periphery`\n   - **Dimensions** (px): width × height\n\n   Defaults:\n   - scene: **1200×630**\n   - icon: **512×512**\n   - periphery: **500×500**\n\n3. **Generate 3 concept options** using `references/idea-mapping.md`:\n   - Present **Option A / B / C**\n   - Each option includes: connection type, category (Builder’s World / Metaphor / Digital Artifact),\n     object list, and why it fits the content.\n   - Keep options meaningfully different (object choice, metaphor, or mood), but all on-brand.\n\n4. **Get user choice** — use AskUserQuestion and let them pick A/B/C (or “Other” for feedback).\n\n5. **Document the project** — create `project.md` inside the project folder with:\n   - requirements\n   - A/B/C concepts\n   - chosen direction\n   - final prompt + parameters\n   - output filenames\n\n6. **Craft prompt and generate** once a concept is approved, saving outputs to the project folder.\n\n   Example:\n   ```bash\n   python3 ${CLAUDE_PLUGIN_ROOT}/skills/brand-illustrator/scripts/generate.py \\\n     --prompt \"A worn leather notebook open to a page with handwritten wireframe sketches\" \\\n     --color coral \\\n     --type scene \\\n     --width 1200 \\\n     --height 630 \\\n     --output projects/2026-01-13-blog-hero/illustration-v1.png\n   ```\n\n## Color System\n\nSee `references/colors.md` for all hex values (single source of truth).\n\n**Available accent colors:** Coral, Teal, Indigo, Amber\n\n### Rules\n- Use **ONE** accent color per illustration.\n- Most of the image is **warm off-white background** with **confident black lines**.\n- Accent color should fill **~20–30%** of the illustration.\n- Shadow/depth color is used **sparingly** (**~5–10%**), mostly as grounding.\n\n## Style Requirements (non-negotiable)\n\nThese are enforced by prompt + review. See `references/style.md` for full details.\n\n- Hand-drawn ink line art; no photorealism, no 3D, no gradients\n- Restrained compositions: focus objects over scenery\n- Suggest environment with a few cues; do not render full rooms\n- Leave negative space for text overlays when used as a hero image\n\n## Concepting Guidance\n\nUse the mapping doc to ensure every illustration is connected to the content:\n- `references/idea-mapping.md` — connection types, object lists, metaphors, quick reference by meaning\n- `references/visual-world.md` — what “belongs” in the Builder Methods world\n- `references/prompts.md` — prompt templates and proven patterns\n\n## Safety / Brand Guardrails\n\n- Avoid trademarks/logos/brand names on devices, mugs, screens, or apparel.\n- Avoid depicting real identifiable people.\n- Keep UI/terminal content generic (nonsense code is fine; no secrets).\n- No violence, gore, or sensitive themes—Builder Methods illustrations should feel calm and inviting.\n\n## Project Documentation Template\n\nCopy into `projects/<date>-<slug>/project.md`:\n\n```md\n# Project: <slug>\n\n## Requirements\n- Content context:\n- Core idea:\n- Visual context:\n- Accent color:\n- Image type:\n- Dimensions:\n\n## Concepts\n### Option A\n- Connection type:\n- Category:\n- Objects:\n- Rationale:\n\n### Option B\n...\n\n### Option C\n...\n\n## Selected Direction\n- Chosen option:\n- Notes / tweaks:\n\n## Final Prompt\n```text\n<final prompt here>\n```\n\n## Generation Params\n- color:\n- type:\n- width:\n- height:\n- output:\n\n## Outputs\n- illustration-v1.png\n- illustration-v2.png\n```\n"},"lastSynced":"2026-03-08T02:14:08.808Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing consistent branding through hand-drawn line illustrations.","zh":"非常适合需要通过手绘线条插图保持一致品牌形象的创意代理","ja":"創造的なエージェントが手描きの線画イラストを通じて一貫したブランディングを必要とする場合に最適","ko":"일관된 브랜딩을 위한 손으로 그린 선 일러스트레이션이 필요한 크리에이티브 에이전트에게 적합","es":"Perfecto para Agentes Creativos que necesitan una marca de identidad coherente a través de ilustraciones de líneas dibujadas a mano.","fr":"Parfait pour les agents créatifs ayant besoin d''une identité visuelle cohérente à travers des illustrations de lignes dessinées à la main.","de":"Perfekt für kreative Agenten, die eine konsistente Markenidentität durch handgezeichnete Linienillustrationen benötigen.","pt":"Perfeito para Agentes Criativos que necessitam de marcação de identidade consistente por meio de ilustrações de linha desenhadas à mão.","ru":"Идеально подходит для Креативных Агентов, которым требуется последовательная идентичность бренда через ручные линейные иллюстрации.","ar":"مثالي للوكلاء الإبداعيين الذين يحتاجون إلى تسويق العلامة التجارية المتسقة من خلال الرسومات الخطية المصممة باليد."},"recommendation":{"en":"Empowers agents to generate hand-drawn line illustrations with confident black ink lines and bold accent colors, producing icons in SVG format using a procedural style + color system, ideal for visual identity and branding purposes.","zh":"赋予代理生成手绘线条插图的能力，具有自信的黑色墨水线和大胆的强调颜色，使用程序化样式 + 颜色系统生成SVG格式的图标，适合用于视觉识别和品牌推广","ja":"自信のあるブラックインクの線とボールドなアクセントカラーを持つ手描きの線画イラストを生成するエージェントの能力を与え、プロセッャルスタイル + カラーシステムを使用してSVG形式のアイコンを生成し、視覚的アイデンティティとブランディングに最適","ko":"대리人が 손으로 그린 선 일러스트레이션을 생성할 수 있도록 해주는 능력, 대담한 강조 색상과 함께 자신감 있는 검은 잉크 선을 가지고, 프로시저 스타일 + 색상 시스템을 사용하여 SVG 형식의 아이콘을 생성하여 시각적 아이덴티티 및 브랜딩에 적합","es":"Habilita a los agentes a generar ilustraciones de líneas dibujadas a mano con líneas de tinta negra confiadas y colores de acento atrevidos, produciendo iconos en formato SVG utilizando un estilo procedural + sistema de color, ideal para fines de identidad visual y marca.","fr":"Autorise les agents à générer des illustrations de lignes dessinées à la main avec des lignes d''encre noire confiantes et des couleurs d''accent audacieuses, produisant des icônes au format SVG en utilisant un style procédural + système de couleur, idéal pour les fins d''identité visuelle et de marque.","de":"Ermöglicht es Agenten, handgezeichnete Linienillustrationen mit selbstbewussten schwarzen Tintenlinien und kräftigen Akzentfarben zu generieren, wodurch Icons im SVG-Format unter Verwendung eines prozeduralen Stils + Farbsystems erstellt werden, ideal für visuelle Identität und Marken-zwecke.","pt":"Habilita os agentes a gerar ilustrações de linha desenhadas à mão com linhas de tinta preta confiantes e cores de realce ousadas, produzindo ícones no formato SVG usando um estilo procedural + sistema de cores, ideal para fins de identidade visual e marcação de identidade.","ru":"Наделяет агентов возможностью генерировать ручные линейные иллюстрации с уверенными чернилами и смелыми акцентными цветами, производя иконки в формате SVG с использованием процедурного стиля + системы цвета, идеально подходящей для целей визуальной идентичности и брендинга.","ar":"يمنح الوكلاء القدرة على توليد رسومات خطية مصممة باليد بخطوط حبر أسود واضحة وألوان تأكيد جريئة ، لإنتاج الرموز في تنسيق SVG باستخدام نمط إجرائي + نظام ألوان ، مثالية لغرض الهوية البصرية والهوية العلامة التجارية."},"useCases":{"en":["Generating on-brand icons with primary objects and bold accent colors","Creating consistent visual identities for developers and designers","Producing hand-drawn line illustrations with warm off-white canvas and confident black ink lines"],"zh":["生成具有主要对象和大胆强调颜色的品牌图标","为开发人员和设计师创建一致的视觉身份","在温暖的米白色画布上生成手绘线条插图，具有自信的黑色墨水线"],"ja":["主なオブジェクトとボールドなアクセントカラーを持つブランドアイコンを生成する","開発者とデザイナーに一貫した視覚的アイデンティティを作成する","暖かいオフホワイトのキャンバス上で自信のあるブラックインクの線を持つ手描きの線画イラストを生成する"],"ko":["주요 객체와 대담한 강조 색상을 가진 브랜드 아이콘 생성","개발자 및 디자이너를 위한 일관된 시각적 아이덴티티 생성","따뜻한 오프화이트 캔버스에서 자신감 있는 검은 잉크 선을 가진 손으로 그린 선 일러스트레이션 생성"],"es":["Generar iconos con marca con objetos principales y colores de acento atrevidos","Crear identidades visuales coherentes para desarrolladores y diseñadores","Producir ilustraciones de líneas dibujadas a mano con una cálida canvas de color blanco apagado y líneas de tinta negra confiadas"],"fr":["Générer des icônes avec une marque avec des objets principaux et des couleurs d''accent audacieuses","Créer des identités visuelles cohérentes pour les développeurs et les designers","Produire des illustrations de lignes dessinées à la main avec une toile chaude de couleur blanc cassé et des lignes d''encre noire confiantes"],"de":["Erzeugen von Marken-Icons mit primären Objekten und kräftigen Akzentfarben","Erstellen von konsistenten visuellen Identitäten für Entwickler und Designer","Erstellen von handgezeichneten Linienillustrationen mit einer warmen, hellen Canvas und selbstbewussten schwarzen Tintenlinien"],"pt":["Gerar ícones com marca de identidade com objetos primários e cores de realce ousadas","Criar identidades visuais consistentes para desenvolvedores e designers","Produzir ilustrações de linha desenhadas à mão com uma tela de cor off-white quente e linhas de tinta preta confiantes"],"ru":["Генерировать иконки с идентичностью бренда с основными объектами и смелыми акцентными цветами","Создавать последовательные визуальные идентичности для разработчиков и дизайнеров","Производить ручные линейные иллюстрации с теплой белой холстом и уверенными чернилами"],"ar":["генерировать رموز مع هوية العلامة التجارية مع الكائنات الأساسية والألوان التأكيد الجريئة","إنشاء هويات بصرية متسقة للمطورين وال مصممين","إنتاج رسومات خطية مصممة باليد مع شاشة من اللون الأبيض الدافئ والخطوط الحبر الأسود الواضحة"]},"limitations":{"en":["Requires specific visual identity and branding guidelines","Limited to generating illustrations with one bold accent color","Dependent on procedural style + color system for consistency"],"zh":["需要特定的视觉身份和品牌指导方针","仅限于使用一种大胆的强调颜色生成插图","依赖于程序化样式 + 颜色系统以保持一致性"],"ja":["特定の視覚的アイデンティティとブランディングのガイドラインが必要","イラストを生成する際に一つのボールドなアクセントカラーに限定される","一貫性を維持するためにプロセッャルスタイル + カラーシステムに依存する"],"ko":["특정한 시각적 아이덴티티 및 브랜딩 지침이 필요","일러스트를 생성할 때 하나의 대담한 강조 색상으로 제한","일관성을 유지하기 위해 프로시저 스타일 + 색상 시스템에 의존"],"es":["Requiere directrices de identidad visual y marca específicas","Limitado a la generación de ilustraciones con un solo color de acento atrevido","Dependiente del estilo procedural + sistema de color para la coherencia"],"fr":["Nécessite des directives d''identité visuelle et de marque spécifiques","Limité à la génération d''illustrations avec une seule couleur d''accent audacieuse","Dépendant du style procédural + système de couleur pour la cohérence"],"de":["Erfordert spezifische Richtlinien für visuelle Identität und Marke","Begrenzt auf die Erzeugung von Illustrationen mit einer einzigen kräftigen Akzentfarbe","Abhängig vom prozeduralen Stil + Farbsystem für die Konsistenz"],"pt":["Exige diretrizes específicas de identidade visual e marcação de identidade","Limitado a gerar ilustrações com uma cor de realce ousada","Dependente do estilo procedural + sistema de cores para consistência"],"ru":["Требует конкретных руководств по визуальной идентичности и брендингу","Ограничен генерированием иллюстраций с одной смелой акцентной цветом","Зависит от процедурного стиля + системы цвета для последовательности"],"ar":["يتطلب إرشادات محددة للهوية البصرية والهوية العلامة التجارية","محدود بتوليد الرسومات مع لون تأكيد جريء واحد","يعتمد على نمط إجرائي + نظام الألوان للاتساق"]},"version":4},"contentHash":"197af8d48191ae6f770ce071fce3dac5e99bed430b9be69891f668a32f5c3a33","qualityScore":57}');
