INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nibzard/skills-kit/brand-illustrator', 'brand-illustrator', 'nibzard', 'skills-kit', 'community', 'brand-illustrator nibzard skills-kit community The brand-illustrator Skill generates hand-drawn line illustrations that match a visual identity, producing icons with primary objects and bold accent colors. This benefits developers and designers seeking consistent branding. 品牌插画工具是一种生成手绘线条插图的工具，具有暖白色画布、自信的黑色墨线和大胆的强调色 ブランドイラストレーターは手描き線画イラストを生成するツールで、暖白色のキャンバス、自信のある黒色のインク線、そして大胆なアクセントカラーを備えています 브랜드 일러스트레이터는 수기 선화 일러스트를 생성하는 도구로 따뜻한 흰색 캔버스와 자신감 있는 검은색 잉크 선, 그리고 대담한 강조 색상을 갖추고 있습니다 El ilustrador de marca es una colección de habilidades del agente que genera ilustraciones a mano alzada que se ajustan a la identidad visual L''illustrateur de marque est un ensemble de compétences de l''agent qui génère des illustrations au trait qui correspondent à l''identité visuelle Der Markenillustrator ist eine Sammlung von Agentenfähigkeiten, die handgezeichnete Illustrationen erstellt, die zur visuellen Identität passen O brand-illustrator é uma coleção de habilidades de agente que gera ilustrações de linha personalizadas que correspondem à identidade visual da Builder Methods. Brand-illustrator - это коллекция навыков агента, генерирующая индивидуальные линейные иллюстрации, соответствующие визуальной идентичности Builder Methods. أداة brand-illustrator هي مجموعة من مهارات الوكيل التي تولد رسومات خطية مخصصة تتوافق مع الهوية البصرية لشركة Builder Methods. how to use brand-illustrator brand-illustrator setup guide brand-illustrator alternative brand-illustrator vs illustration tools brand-illustrator install what is brand-illustrator brand-illustrator tutorial brand-illustrator for AI Agents brand-illustrator procedural generation 品牌插画工具 AI工具 手绘线条插图 暖白色画布 自信的黑色墨线 一致的风格 色彩系统 图标生成 图像生成 Generates hand-drawn line illustrations with a warm off-white canvas Produces icons with primary objects and bold accent colors Uses a style and color system for consistent branding Allows for gathering requirements and proposing on-brand concepts Enables generation of final images consistently using the style and color system brand-illustrator is a reusable and procedural Skill that generates hand-drawn line illustrations with a warm off-white canvas, confident black ink lines, and one bold accent color.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ahrav/Gossip-rs/simd-optimize', 'community', 'ahrav', 'Gossip-rs', 'ahrav/Gossip-rs', 'simd-optimize', 0, 0, 57, '2026-03-07T22:19:19Z', '2026-03-08T02:14:15.609Z', '3c171698db599bdbd326cae85098bab949999dee71887fc60512923a06000f3f', '{"id":"ahrav/Gossip-rs/simd-optimize","name":"simd-optimize","description":{"en":"The simd-optimize skill enables developers to optimize Rust code using vectorization, improving performance by detecting and analyzing hardware support and compiler auto-vectorization.","zh":"simd-optimize是一种Rust矢量化优化技术，通过检测硬件支持、分析编译器自动矢量化、选择合适的内在函数来提高性能","ja":"simd-optimizeはRustのSIMD最適化技術で、ハードウェアのサポートを検出して、コンパイラの自動ベクタ化を分析し、適切な内在関数を選択してパフォーマンスを向上させます","ko":"simd-optimize는 러스트의 SIMD 최적화 기술로 하드웨어 지원을 탐지하고 컴파일러의 자동 벡터화 분석을 통해 적절한 내장 함수를 선택하여 성능을 향상시킵니다","es":"simd-optimize es una técnica para optimizar código Rust mediante la vectorización, detectando y analizando el soporte de hardware y compilador","fr":"simd-optimize est une technique pour optimiser le code Rust par vectorisation, en détectant et en analysant le support matériel et compilateur","de":"simd-optimize ist eine Technik zur Optimierung von Rust-Code durch Vektorisierung, indem die Hardware- und Compiler-Unterstützung erkannt und analysiert wird","pt":"O simd-optimize é uma técnica para otimizar o desempenho do código Rust usando vectorização","ru":"simd-optimize - это техника для ускорения вычислений в Rust с помощью векторизации","ar":"simd-optimize هو تقنية لتحسين أداء رمز الرست باستخدام التوجيه"},"seo":{"title":{"en":"simd-optimize: Vectorization Setup Guide | AI Agent Skill","zh":"simd-optimize Setup Guide：Rust矢量化优化","ja":"simd-optimize ベストプラクティス：RustのSIMD最適化","ko":"simd-optimize 설정 가이드: Rust 벡터화 최적화","es":"Guía de configuración de simd-optimize para Rust","fr":"Mise en place de simd-optimize pour Rust","de":"Leitfaden für simd-optimize in Rust","pt":"Guia de Configuração do simd-optimize para Otimização de ...","ru":"ИИ Агенты: simd-optimize для Ускорения Вычислений","ar":"دليل إعدادsimd-optimize لتحسين الأداء"},"description":{"en":"Unlock performance gains with simd-optimize. Learn how to detect, analyze, and implement vectorization for Rust. Get started now!","zh":"simd-optimize 是一种Rust矢量化优化技术，通过检测、分析、实现、验证来提高性能，了解如何使用simd-optimize来优化您的代码","ja":"simd-optimizeはRustのSIMD最適化技術で、検出、分析、実装、検証によってパフォーマンスを向上させます。simd-optimizeの使い方を学びましょう","ko":"simd-optimize는 러스트 벡터화 최적화 기술로 탐지, 분석, 구현, 검증을 통해 성능을 향상시킵니다. simd-optimize를 사용하여 코드를 최적화하는 방법에 대해 알아보세요","es":"Aprende a optimizar tu código Rust con simd-optimize, detectando y analizando el soporte de hardware y compilador","fr":"Découvrez comment optimiser votre code Rust avec simd-optimize, en détectant et en analysant le support matériel et compilateur","de":"Erfahren Sie, wie Sie Ihren Rust-Code mit simd-optimize optimieren, indem Sie die Hardware- und Compiler-Unterstützung erkennen und analysieren","pt":"Aprenda a usar o simd-optimize para melhorar o desempenho do seu código Rust com vectorização","ru":"Узнайте, как использовать simd-optimize для ускорения вычислений в Rust","ar":"تعرف على كيفية استخدامsimd-optimize لتحسين أداء رمزك الرست"},"definition":{"en":"simd-optimize is a technique for optimizing Rust code using vectorization, following a philosophy of detect, analyze, implement, and validate to maximize performance gains.","zh":"simd-optimize是一种用于Rust的SIMD优化技术，旨在通过矢量化提高代码性能","ja":"simd-optimizeはRustのSIMD最適化技術の一種で、ベクタ化によってコードのパフォーマンスを向上させることを目的としています","ko":"simd-optimize는 러스트의 SIMD 최적화 기술의 하나로 벡터화 통해 코드의 성능을 향상시키는 것을 목적으로 합니다","es":"simd-optimize es una técnica de optimización que utiliza la vectorización para mejorar el rendimiento de código Rust","fr":"simd-optimize est une technique d''optimisation qui utilise la vectorisation pour améliorer les performances du code Rust","de":"simd-optimize ist eine Optimierungstechnik, die die Vektorisierung verwendet, um die Leistung von Rust-Code zu verbessern","pt":"simd-optimize é uma técnica de otimização que usa instruções SIMD para melhorar o desempenho","ru":"simd-optimize - это техника оптимизации, использующая инструкции SIMD для ускорения вычислений","ar":"simd-optimize هو تقنية تحسين تستخدم تعليمات SIMD لتحسين الأداء"},"features":{"en":["Detects hardware support for SIMD instructions","Analyzes compiler auto-vectorization to identify optimization opportunities","Implements vectorization using proper fallback chains","Validates correctness and performance of optimized code","Converts scalar loops to SIMD where profiling shows time is spent"],"zh":["检测硬件支持的SIMD指令","分析编译器自动矢量化的代码","选择合适的内在函数来优化性能","实现fallback链来确保兼容性","验证优化后的代码的正确性和性能"],"ja":["ハードウェアのサポートするSIMD命令の検出","コンパイラの自動ベクタ化コードの分析","パフォーマンスの最適化のために適切な内在関数の選択","fallbackチェーンの実装による互換性の確保","最適化されたコードの正しさとパフォーマンスの検証"],"ko":["하드웨어 지원 SIMD 명령어 탐지","컴파일러의 자동 벡터화 코드 분석","성능 최적화를 위한 적절한 내장 함수 선택","fallback 체인의 구현을 통한 호환성 보장","최적화된 코드의 정밀성과 성능의 검증"],"es":["Detección automática del soporte de hardware","Análisis de la vectorización automática del compilador","Implementación de intrínsecos para una optimización personalizada","Cadenas de fallback para garantizar la compatibilidad","Validación de la corrección y el rendimiento"],"fr":["Détection automatique du support matériel","Analyse de la vectorisation automatique du compilateur","Implémentation d''intrinsèques pour une optimisation personnalisée","Chaînes de fallback pour garantir la compatibilité","Validation de la correction et des performances"],"de":["Automatische Erkennung der Hardware-Unterstützung","Analyse der automatischen Vektorisierung des Compilers","Implementierung von Intrinsiken für eine benutzerdefinierte Optimierung","Fallback-Ketten für die Gewährleistung der Kompatibilität","Validierung der Korrektheit und Leistung"],"pt":["Detecção de suporte de hardware","Análise de auto-vectorização do compilador","Implementação de intrínsecos corretos","Cadeias de fallback adequadas","Validação de corretude e desempenho"],"ru":["Обнаружение поддержки аппаратного обеспечения","Анализ авто-векторизации компилятора","Реализация правильных интринсиков","Цепочки fallback","Проверка корректности и производительности"],"ar":["اكتشاف الدعم المادي","تحليل التوجيه التلقائي للمترجم","تنفيذ الدوال الداخلية الصحيحة","سلاسل الفallback المناسبة","التحقق من الصحة والأداء"]},"keywords":{"en":["how to use simd-optimize","simd-optimize setup guide","simd-optimize vs auto-vectorization","simd-optimize install for Rust","simd-optimize performance optimization","what is simd-optimize in Rust"],"zh":["simd-optimize","Rust矢量化优化","SIMD最適化","代码性能优化","Rust开发","simd优化技术"],"ja":["simd-optimize","RustのSIMD最適化","ベクタ化最適化","コードのパフォーマンス最適化","Rust開発","SIMD最適化技術"],"ko":["simd-optimize","러스트 벡터화 최적화","SIMD 최적화","코드 성능 최적화","러스트 개발","SIMD 최적화 기술"],"es":["simd-optimize","optimización de código Rust","vectorización","soporte de hardware","compilador","intrínsecos","cadenas de fallback","validación de rendimiento"],"fr":["simd-optimize","optimisation de code Rust","vectorisation","support matériel","compilateur","intrinsèques","chaînes de fallback","validation des performances"],"de":["simd-optimize","Optimierung von Rust-Code","Vektorisierung","Hardware-Unterstützung","Compiler","Intrinsiken","Fallback-Ketten","Leistungsvalidierung"],"pt":["simd-optimize","otimização de desempenho","Rust","vectorização","intrínsecos","fallback","validação de corretude","desempenho de código"],"ru":["simd-optimize","ИИ Агенты","ускорение вычислений","Rust","векторизация","интринсики","цепочки fallback","проверка корректности","производительность кода"],"ar":["simd-optimize","أدوات الذكاء الاصطناعي","تحسين الأداء","Rust","التوجيه","الدوال الداخلية","سلاسل الفallback","التحقق من الصحة","أداء الرمز"]}},"owner":"ahrav","repo":"Gossip-rs","repoPath":"ahrav/Gossip-rs","stars":0,"forks":0,"updatedAt":"2026-03-07T22:19:19Z","topics":[],"category":"community","skillMd":{"name":"simd-optimize","description":"SIMD vectorization for Rust — detects ISA features, identifies vectorizable patterns, generates platform-specific intrinsics (ARM NEON/SVE, x86 SSE/AVX/AVX-512), validates correctness and performance. Uses tiered research with baked-in references and /deep-research fallback.","bodyPreview":"# SIMD Optimize — Vectorization for Rust\n\n**Philosophy: Detect, analyze, implement, validate. Never guess the ISA.**\n\nEvery SIMD optimization starts by detecting what the hardware actually supports,\nanalyzing what the compiler already auto-vectorized (and what it missed),\nchoosing the right intrinsics from reference material, implementing with proper\nfallback chains, and validating correctness + performance.\n\n## When to Use\n\n- Converting scalar loops to SIMD where profiling shows time is spent o","body":"# SIMD Optimize — Vectorization for Rust\n\n**Philosophy: Detect, analyze, implement, validate. Never guess the ISA.**\n\nEvery SIMD optimization starts by detecting what the hardware actually supports,\nanalyzing what the compiler already auto-vectorized (and what it missed),\nchoosing the right intrinsics from reference material, implementing with proper\nfallback chains, and validating correctness + performance.\n\n## When to Use\n\n- Converting scalar loops to SIMD where profiling shows time is spent on data-parallel work\n- After `/performance-analyzer` identified a loop-heavy hot function\n- When `/asm-forge` shows the compiler failed to auto-vectorize a loop\n- Adding SIMD support that works across x86-64 and AArch64\n- Evaluating whether to use explicit intrinsics vs helping the auto-vectorizer\n- Understanding what SIMD capabilities the target hardware has\n\n## When NOT to Use\n\n- For non-data-parallel work (graph traversal, tree operations, hash table probing)\n- For I/O-bound code (disk, network — SIMD won''t help)\n- When the loop body has side effects or complex control flow that can''t be vectorized\n- When input sizes are tiny (<64 bytes) — SIMD setup overhead may dominate\n- For general codegen quality issues — use `/asm-forge` instead\n\n## Prerequisites\n\n### Required\n\n```bash\n# cargo-show-asm: inspect compiler output\ncargo install cargo-show-asm\n\n# jq: parse detection script output\nbrew install jq  # macOS\napt install jq   # Linux\n\n# Criterion benchmarks must exist for the target code\n```\n\n### Recommended\n\n```bash\n# proptest: property-based testing for SIMD vs scalar comparison\n# Add to [dev-dependencies]: proptest = \"1\"\n```\n\n## Invocation\n\n```\n/simd-optimize @file.rs \"description of what to vectorize\"\n```\n\nExamples:\n```\n/simd-optimize @crates/gossip-stdx/src/byte_slab.rs \"vectorize the slot search loop\"\n/simd-optimize @crates/gossip-stdx/src/inline_vec.rs \"add SIMD path for element search\"\n/simd-optimize @crates/scanner-engine/src/engine/simd_classify.rs \"SIMD byte classification across x86 and ARM\"\n```\n\n## Workflow Overview\n\n```\n/simd-optimize @file.rs \"target description\"\n    │\n    ├─ Phase 0: ISA Detection\n    │   └─ Run detect_simd.sh → JSON capability report\n    │\n    ├─ Phase 1: Analysis (3 parallel agents)\n    │   ├─ Agent A: Loop Analyzer — identify vectorizable patterns\n    │   ├─ Agent B: Autovec Auditor — what did rustc already vectorize?\n    │   └─ Agent C: Constraint Mapper — data layout, alignment, types\n    │\n    ├─ Phase 2: Research & Strategy\n    │   ├─ Load ISA-specific references (tiered: baked-in first)\n    │   ├─ Match patterns to reference implementations\n    │   ├─ If gap → invoke /deep-research for specific pattern\n    │   └─ Select strategy: intrinsics / help-autovec / portable-simd / crate\n    │\n    ├─ Phase 3: Implementation\n    │   ├─ Ensure scalar reference exists (for correctness testing)\n    │   ├─ Write SIMD implementation(s) with cfg gating\n    │   ├─ Wire runtime dispatch if needed\n    │   ├─ Handle remainder elements\n    │   └─ Add unsafe blocks with safety comments\n    │\n    └─ Phase 4: Validation (2 parallel agents)\n        ├─ Agent D: Correctness — proptest comparing SIMD vs scalar\n        └─ Agent E: Performance — /bench-compare against baseline\n```\n\n## Phase 0: ISA Detection\n\nRun the bundled detection script:\n\n```bash\nbash <skill_dir>/scripts/detect_simd.sh\n```\n\nThis outputs JSON like:\n\n```json\n{\n  \"arch\": \"aarch64\",\n  \"os\": \"darwin\",\n  \"rust_target\": \"aarch64-apple-darwin\",\n  \"cpu_model\": \"Apple M1 Pro\",\n  \"features\": {\n    \"aes\": true, \"crc\": true, \"neon\": true,\n    \"sha2\": true, \"sve\": false, \"sve2\": false\n  },\n  \"max_vector_width_bits\": 128,\n  \"recommended_baseline\": \"neon\",\n  \"recommended_fast_path\": null,\n  \"frequency_throttle_risk\": false\n}\n```\n\n**Key fields for subsequent phases:**\n- `recommended_baseline` — ISA level to target for the primary SIMD implementation\n- `recommended_fast_path` — optional higher ISA for runtime dispatch (e.g., \"avx512\")\n- `frequency_throttle_risk` — if true, warn about Intel AVX-512 downclocking\n\nPresent the capability report to the user before proceeding.\n\n## Phase 1: Analysis\n\nLaunch three parallel agents using the Task tool in a single message:\n\n### Agent A: Loop Analyzer\n\n```\nAnalyze the target code for vectorizable patterns. For each candidate loop:\n\n1. Classify the pattern:\n   - Map (element-wise transform)\n   - Reduction (sum, min, max, count, any/all)\n   - Search (find first/all matching elements)\n   - Scan (prefix sum, running accumulator)\n   - LUT (lookup table, classify/translate)\n   - Pack/unpack (narrow, widen, interleave)\n   - Filter (compress matching elements)\n\n2. Identify the iteration pattern:\n   - Trip count (fixed, bounded, data-dependent?)\n   - Memory access pattern (contiguous, strided, random?)\n   - Loop-carried dependencies (accumulator, state machine?)\n\n3. Estimate the vector-friendliness:\n   - HIGH: Pure map/search on contiguous arrays, no loop-carried deps\n   - MEDIUM: Reduction with associative op, or strided access\n   - LOW: Data-dependent iterations, random access, complex control flow\n\nOutput a ranked candidate list with pattern classification and confidence.\n```\n\n### Agent B: Autovec Auditor\n\n```\nCheck what the compiler already auto-vectorized using check_autovec.sh.\n\nRun: bash <skill_dir>/scripts/check_autovec.sh <crate> ''<function_path>''\n\nFor each candidate function from the Loop Analyzer:\n1. Report whether rustc generated SIMD instructions\n2. If yes: what width? What percentage of the loop is vectorized?\n3. If no: what likely blocked auto-vectorization?\n   - Function calls in loop body\n   - Loop-carried dependencies\n   - Complex control flow\n   - Non-contiguous memory access\n   - Iterator chain that inhibits vectorization\n\nSummarize: which functions need manual SIMD, which are already handled.\n```\n\n### Agent C: Constraint Mapper\n\n```\nAnalyze data layout and constraints that affect SIMD implementation:\n\n1. Data layout: AoS (array of structs) or SoA (struct of arrays)?\n   - AoS needs deinterleaving (vld2/vzip) or transpose\n   - SoA is directly SIMD-friendly\n\n2. Alignment: Are buffers aligned to 16/32/64 bytes?\n   - Check allocator usage, struct layout, slice origins\n   - If unknown, must use unaligned loads\n\n3. Element types: u8, u16, u32, u64, f32, f64?\n   - Narrower types = more elements per vector = higher speedup\n   - Mixed types need widening/narrowing\n\n4. Memory access pattern: contiguous, strided, gathered?\n   - Contiguous: simple vector load\n   - Strided: may need shuffle after load\n   - Gathered: expensive on most ISAs (prefer restructuring)\n\n5. Aliasing: Do input and output buffers overlap?\n   - If yes: must process in correct order or use temporary\n\nOutput a constraint report that guides implementation choices.\n```\n\n## Phase 2: Research & Strategy\n\n### Step 1: Load References (tiered)\n\nBased on Phase 0 ISA detection and Phase 1 pattern analysis:\n\n```\nIF arch == \"x86_64\":\n    LOAD references/x86-sse-avx.md\n    IF features.avx512f == true:\n        LOAD references/x86-avx512.md\n\nELIF arch == \"aarch64\":\n    LOAD references/arm-neon.md\n    IF features.sve == true OR features.sve2 == true:\n        LOAD references/arm-sve.md\n\nALWAYS LOAD:\n    references/simd-patterns.md      (cross-platform pattern cookbook)\n    references/portability-guide.md   (dispatch, fallback chains)\n    references/pitfalls.md            (bugs to avoid)\n```\n\n### Step 2: Match Patterns to References\n\nFor each vectorizable candidate from Phase 1:\n1. Find the matching pattern in `simd-patterns.md`\n2. Check the ISA-specific reference for the right intrinsics\n3. Note any pitfalls from `pitfalls.md` that apply\n\n### Step 3: Gap Check\n\nIf a pattern isn''t covered by the baked-in references:\n```\nInvoke /deep-research with query:\n\"Rust SIMD implementation of [pattern description] using\n[ISA: AVX2/NEON/etc] intrinsics from std::arch::[arch].\nInclude complete code example with #[target_feature] and unsafe.\"\n```\n\n### Step 4: Strategy Selection\n\nChoose the implementation approach:\n\n| Strategy | When to Use | Tradeoff |\n|----------|-------------|----------|\n| **Direct intrinsics** (`std::arch`) | Maximum control needed, complex patterns | Most effort, best performance |\n| **Help auto-vectorizer** | Simple loops, compiler almost got it | Least effort, fragile |\n| **Portable SIMD** (`std::simd`) | Portability > peak performance, nightly OK | Moderate effort, portable |\n| **Crate** (`wide`, `pulp`, `multiversion`) | Need stable Rust + portability | Easy, some overhead |\n\nDefault recommendation: **Direct intrinsics** for hot paths, **help auto-vectorizer**\nfor secondary paths.\n\n## Phase 3: Implementation\n\n### Step 1: Ensure Scalar Reference Exists\n\nBefore writing SIMD code, verify a correct scalar implementation exists. This is\nthe ground truth for correctness testing. If one doesn''t exist, write it first.\n\n### Step 2: Write SIMD Implementation\n\nFollow this template:\n\n```rust\n#[cfg(target_arch = \"x86_64\")]\n#[target_feature(enable = \"avx2\")]\nunsafe fn process_avx2(data: &[u8]) -> Result {\n    // SAFETY:\n    // - Caller ensures `is_x86_feature_detected!(\"avx2\")` returned true\n    // - `data.len() >= 32` checked by caller (or handled by remainder loop)\n    // - Unaligned loads used (no alignment requirement)\n\n    use core::arch::x86_64::*;\n\n    let mut i = 0;\n    let len = data.len();\n\n    // Main SIMD loop: process 32 bytes at a time\n    while i + 32 <= len {\n        let chunk = _mm256_loadu_si256(data.as_ptr().add(i) as *const __m256i);\n        // ... SIMD operations ...\n        i += 32;\n    }\n\n    // Remainder: scalar fallback for last <32 bytes\n    while i < len {\n        // ... scalar processing ...\n        i += 1;\n    }\n\n    result\n}\n\n#[cfg(target_arch = \"aarch64\")]\n#[target_feature(enable = \"neon\")]\nunsafe fn process_neon(data: &[u8]) -> Result {\n    // SAFETY:\n    // - NEON is always available on AArch64 (no runtime check needed)\n    // - `data.len() >= 16` checked by caller\n    // - vld1q_u8 handles unaligned loads\n\n    use core::arch::aarch64::*;\n\n    let mut i = 0;\n    let len = data.len();\n\n    while i + 16 <= len {\n        let chunk = vld1q_u8(data.as_ptr().add(i));\n        // ... NEON operations ...\n        i += 16;\n    }\n\n    // Remainder\n    while i < len {\n        i += 1;\n    }\n\n    result\n}\n\n/// Scalar fallback — always correct, used as reference and fallback\nfn process_scalar(data: &[u8]) -> Result {\n    // ... straightforward scalar implementation ...\n}\n\n/// Public dispatch function\npub fn process(data: &[u8]) -> Result {\n    #[cfg(target_arch = \"x86_64\")]\n    {\n        if is_x86_feature_detected!(\"avx2\") {\n            return unsafe { process_avx2(data) };\n        }\n    }\n\n    #[cfg(target_arch = \"aarch64\")]\n    {\n        // NEON is always available on AArch64\n        return unsafe { process_neon(data) };\n    }\n\n    process_scalar(data)\n}\n```\n\n### Step 3: Implementation Checklist\n\n- [ ] Each SIMD function has `#[target_feature(enable = \"...\")]`\n- [ ] Each SIMD function is `unsafe fn` with a `// SAFETY:` comment\n- [ ] Safety comment documents: feature availability, bounds, alignment\n- [ ] Remainder/tail elements handled (scalar loop, overlap, or masked)\n- [ ] No panicking paths in the SIMD loop (no indexing with `[]`)\n- [ ] `cfg(target_arch)` gates each platform-specific function\n- [ ] Dispatch function selects the best available implementation\n- [ ] For x86: runtime detection with `is_x86_feature_detected!`\n- [ ] For AArch64: NEON is always available, no runtime check needed\n\n### Step 4: Match Project Patterns\n\nWhen adding SIMD to this project, follow existing patterns:\n\n- Check `crates/gossip-stdx/src/` for data structures that may already use\n  unsafe pointer operations that could benefit from SIMD\n- Check `crates/scanner-engine/src/lsm/set_associative_cache.rs` and\n  `crates/scanner-engine/src/engine/simd_classify.rs` for existing SIMD patterns\n- Use `cfg(target_arch)` dispatch with separate functions per ISA\n- Follow the project''s `// SAFETY:` comment convention for all unsafe blocks\n\n## Phase 4: Validation\n\nLaunch two parallel agents:\n\n### Agent D: Correctness Validator\n\n```\nWrite property tests comparing SIMD implementation against scalar reference.\n\nUse proptest with these test vectors:\n1. Empty input (length 0)\n2. Single element\n3. Exactly one vector width (16 bytes for NEON/SSE, 32 for AVX2)\n4. One less than vector width (15, 31)\n5. One more than vector width (17, 33)\n6. Random lengths up to 10000\n7. All zeros (0x00)\n8. All ones (0xFF)\n9. Alternating patterns (0xAA, 0x55)\n10. Maximum values for the element type\n11. Values at type boundaries (127/128, 255/0 for u8)\n\nTemplate:\n```rust\nuse proptest::prelude::*;\n\nproptest! {\n    #[test]\n    fn simd_matches_scalar(data in prop::collection::vec(any::<u8>(), 0..10000)) {\n        let simd_result = process(&data);    // uses dispatch (SIMD when available)\n        let scalar_result = process_scalar(&data);\n        prop_assert_eq!(simd_result, scalar_result);\n    }\n}\n```\n\nRun tests and report results.\n```\n\n### Agent E: Performance Validator\n\n```\nInvoke /bench-compare to measure SIMD vs scalar performance.\n\nIf Criterion benchmarks exist for the target function:\n  Run: cargo bench --bench <name> -- --save-baseline simd-before\n  Apply SIMD changes\n  Run: cargo bench --bench <name> -- --baseline simd-before\n\nIf no benchmarks exist:\n  Create a minimal Criterion benchmark comparing scalar vs SIMD dispatch.\n\nReport:\n- Throughput improvement (bytes/sec or ops/sec)\n- Latency reduction (ns per call)\n- Speedup factor (e.g., 4.2x for AVX2 on a byte-search pattern)\n- Whether speedup matches theoretical expectation (vector_width / scalar_width)\n```\n\n## Output Format\n\nAfter all phases complete, present:\n\n```markdown\n## SIMD Optimization Report\n\n### Machine Capabilities\n- Arch: [x86_64 / aarch64]\n- CPU: [model]\n- Baseline ISA: [sse2 / avx2 / neon]\n- Fast path: [avx512 / sve2 / none]\n\n### Patterns Found\n| Pattern | Function | Strategy | Expected Speedup |\n|---------|----------|----------|------------------|\n| Byte search | find_byte() | Direct intrinsics (AVX2 + NEON) | 8-16x |\n| Horizontal sum | reduce_sum() | Help auto-vectorizer | 2-4x |\n\n### Implementation Summary\n- Files modified: [list]\n- Lines added: [N]\n- SIMD paths: [x86_64 AVX2, aarch64 NEON, scalar fallback]\n\n### Validation\n- Correctness: [X/Y proptest strategies passing]\n- Performance: [Nx speedup measured, Z bytes/sec throughput]\n\n### Remaining Opportunities\n[Any patterns not addressed and why]\n```\n\n## Tips\n\n### ISA-Specific Notes\n\n**x86-64:**\n- SSE2 is baseline (always available) — 128-bit vectors\n- AVX2 is the sweet spot — 256-bit vectors, no throttling\n- AVX-512 gives 512-bit but beware Intel frequency throttling\n- `_mm256_shuffle_epi8` shuffles within 128-bit lanes, NOT across them\n- Use `_mm256_permutevar8x32_epi32` for cross-lane permutes\n\n**AArch64:**\n- NEON is always available — no feature detection needed\n- 128-bit vectors (32 registers — less pressure than x86''s 16)\n- `vmaxvq_u8` for horizontal max (single instruction, unlike x86''s movemask)\n- NEON compares return full-width masks (all-1s), not bitmasks like x86\n- No frequency throttling ever — 128-bit SIMD is free\n\n### When to Escalate to /deep-research\n\nInvoke `/deep-research` when:\n- The pattern isn''t in `simd-patterns.md` (e.g., custom hash, crypto, compression)\n- You need performance data for a specific microarchitecture\n- The intrinsic you need may not be in stable Rust yet\n- You''re evaluating whether `std::simd` covers the pattern\n\n### Common Mistakes\n\n1. Forgetting the scalar remainder loop → UB on non-multiple-of-width inputs\n2. Using aligned loads on unaligned data → segfault on x86\n3. Missing `#[target_feature]` → SIMD instructions not emitted\n4. Testing only on the dev machine → breaks on CI with different ISA\n5. Not comparing against the scalar reference → SIMD result silently wrong\n\n## Related Skills\n\n- `/asm-forge` — Post-SIMD assembly audit (verify codegen quality)\n- `/performance-analyzer` — Static hotspot analysis; identify what functions to vectorize (run first)\n- `/bench-compare` — Quick before/after benchmark comparison\n- `/deep-research` — Research specific SIMD patterns not in references\n- `/linux-perf-profile` — Hardware counter analysis for SIMD bottlenecks\n"},"lastSynced":"2026-03-08T02:14:15.609Z","agentAnalysis":{"suitability":{"en":"Perfect for Performance Optimization Agents needing advanced Rust vectorization capabilities.","zh":"适合需要高级Rust向量化能力的性能优化代理。","ja":"パフォーマンス最適化エージェントが高度なRustベクトル化機能を必要とする場合に最適です。","ko":"고급 Rust 벡터화 기능이 필요한 성능 최적화 에이전트에 적합합니다.","es":"Perfecto para agentes de optimización de rendimiento que necesitan capacidades de vectorización avanzadas de Rust.","fr":"Parfait pour les agents d''optimisation de performance ayant besoin de capacités de vectorisation avancées de Rust.","de":"Perfekt für Leistungs-Optimierungsagenten, die erweiterte Rust-Vektorisierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes de Otimização de Desempenho que precisam de capacidades avançadas de vectorização Rust.","ru":"Идеально подходит для агентов оптимизации производительности, которым необходимы расширенные возможности векторизации Rust.","ar":"مثالي لعميل تحسين الأداء الذي يحتاج إلى قدرات متقدمة لترجمة Rust."},"recommendation":{"en":"Empowers agents to detect and analyze hardware support, implement compiler auto-vectorization, and validate correctness plus performance using vectorization and intrinsics, optimizing Rust code for improved execution speed.","zh":"赋予代理检测和分析硬件支持、实现编译器自动向量化、并使用向量化和内在函数验证正确性和性能，从而优化Rust代码以提高执行速度。","ja":"ハードウェアのサポートを検出して分析し、コンパイラの自動ベクトル化を実装し、ベクトル化とイントリンスを使用して正しさとパフォーマンスを検証することで、エージェントにRustコードの実行速度を向上させる最適化を実行する力を与えます。","ko":"하드웨어 지원을 감지하고 분석하며 컴파일러 자동 벡터화를 구현하고 벡터화 및 기본 함수를 사용하여 올바름과 성능을 검증하여 에이전트가 Rust 코드의 실행 속도를 개선하기 위한 최적화를 수행할 수 있도록 합니다.","es":"Habilita a los agentes para detectar y analizar el soporte de hardware, implementar la auto-vectorización del compilador y validar la corrección y el rendimiento utilizando la vectorización y los intrínsecos, optimizando el código Rust para una velocidad de ejecución mejorada.","fr":"Permet aux agents de détecter et d''analyser le support matériel, de mettre en œuvre l''auto-vectorisation du compilateur et de valider la correction et les performances en utilisant la vectorisation et les intrinsèques, en optimisant le code Rust pour une vitesse d''exécution améliorée.","de":"Ermöglicht es den Agenten, die Hardware-Unterstützung zu erkennen und zu analysieren, die Compiler-Auto-Vektorisierung zu implementieren und die Korrektheit und Leistung unter Verwendung von Vektorisierung und Intrinsiken zu überprüfen, wodurch der Rust-Code für eine verbesserte Ausführungsgeschwindigkeit optimiert wird.","pt":"Habilita os agentes a detectar e analisar o suporte de hardware, implementar a auto-vectorização do compilador e validar a correção e o desempenho usando vectorização e intrínsecos, otimizando o código Rust para uma velocidade de execução aprimorada.","ru":"Наделяет агентов возможностью обнаруживать и анализировать поддержку аппаратного обеспечения, реализовывать автоматическую векторизацию компилятора и проверять правильность и производительность с помощью векторизации и интринсиков, оптимизируя код Rust для улучшения скорости выполнения.","ar":"يمكن للعميل الكشف عن دعم الأجهزة وتحليله، وتنفيذ التجميع التلقائي للجهاز، و التحقق من صحة الأداء باستخدام التجميع والتركيب، و تحسين كود Rust من أجل تحسين سرعة التشغيل."},"useCases":{"en":["Converting scalar loops to SIMD for performance-critical sections","Analyzing compiler auto-vectorization to identify optimization opportunities","Validating correctness and performance of vectorized code"],"zh":["将标量循环转换为SIMD以优化关键部分的性能","分析编译器自动向量化以确定优化机会","验证向量化代码的正确性和性能"],"ja":["パフォーマンスクリティカルなセクションの性能を最適化するためにスカラー ループをSIMDに変換する","コンパイラの自動ベクトル化を分析して最適化の機会を特定する","ベクトル化コードの正しさとパフォーマンスを検証する"],"ko":["성능에 중요한 섹션의 성능을 최적화하기 위해 스칼라 루프를 SIMD로 변환하는 것","컴파일러 자동 벡터화를 분석하여 최적화 기회를 식별하는 것","벡터화 코드의 올바름과 성능을 검증하는 것"],"es":["Convertir bucles escalares en SIMD para secciones críticas de rendimiento","Analizar la auto-vectorización del compilador para identificar oportunidades de optimización","Validar la corrección y el rendimiento del código vectorizado"],"fr":["Convertir les boucles scalaires en SIMD pour les sections critiques de performance","Analyser l''auto-vectorisation du compilateur pour identifier les opportunités d''optimisation","Valider la correction et les performances du code vectorisé"],"de":["Skalare Schleifen in SIMD für performance-kritische Abschnitte umwandeln","Die Compiler-Auto-Vektorisierung analysieren, um Optimierungsmöglichkeiten zu identifizieren","Die Korrektheit und Leistung des vectorisierten Codes überprüfen"],"pt":["Converter laços escalares para SIMD para seções críticas de desempenho","Analisar a auto-vectorização do compilador para identificar oportunidades de otimização","Validar a correção e o desempenho do código vectorizado"],"ru":["Преобразование скалярных циклов в SIMD для критических к производительности секций","Анализ автоматической векторизации компилятора для выявления возможностей оптимизации","Проверка правильности и производительности векторизированного кода"],"ar":["تحويل الحلقات المركبة إلى SIMD لقطاعات حرجة للأداء","تحليل التجميع التلقائي للجهاز لتحديد فرص التحسين","التحقق من صحة الأداء للكود المتجمد"]},"limitations":{"en":["Requires Rust programming knowledge","Dependent on hardware support for SIMD instructions","Needs compiler support for auto-vectorization"],"zh":["需要Rust编程知识","依赖于SIMD指令的硬件支持","需要编译器对自动向量化的支持"],"ja":["Rustプログラミングの知識が必要","SIMD命令をサポートするハードウェアに依存する","コンパイラが自動ベクトル化をサポートする必要がある"],"ko":["Rust 프로그래밍 지식이 필요함","SIMD 명령어를 지원하는 하드웨어에 의존함","컴파일러가 자동 벡터화를 지원해야 함"],"es":["Requiere conocimientos de programación en Rust","Depende del soporte de hardware para instrucciones SIMD","Necesita soporte del compilador para la auto-vectorización"],"fr":["Nécessite des connaissances en programmation Rust","Dépend du support matériel pour les instructions SIMD","Nécessite un support du compilateur pour l''auto-vectorisation"],"de":["Benötigt Rust-Programmierkenntnisse","Hängt von der Hardware-Unterstützung für SIMD-Anweisungen ab","Benötigt Compiler-Unterstützung für die Auto-Vektorisierung"],"pt":["Requer conhecimento de programação Rust","Depende do suporte de hardware para instruções SIMD","Necessita de suporte do compilador para auto-vectorização"],"ru":["Требует знаний языка программирования Rust","Зависит от поддержки аппаратного обеспечения для инструкций SIMD","Требует поддержки компилятора для автоматической векторизации"],"ar":["يتط