INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Patrickjoshanedez/CMS-V2/zustand', 'zustand', 'Patrickjoshanedez', 'CMS-V2', 'community', 'zustand Patrickjoshanedez CMS-V2 community zustand is a state management solution that enables efficient UI component interactions through public actions and internal actions. It benefits developers building complex applications. zustand是一种高效的状态管理工具，提供Public Actions和Internal Actions两种接口。通过zustand，开发者可以优化应用的状态管理 zustandは効率的な状態管理ツールであり、Public ActionsとInternal Actionsの2つのインターフェイスを提供します。zustandを使用することで、開発者はアプリの状態管理を最適化できます zustand는 효율적인 상태 관리 도구로 Public Actions와 Internal Actions 두 가지 인터페이스를 제공합니다. Zustand를 통해 개발자는 애플리케이션의 상태 관리를 최적화할 수 있습니다 Zustand es una biblioteca de gestión de estado que proporciona una forma sencilla de administrar el estado de tus aplicaciones. Ofrece una jerarquía de tipos de acciones para una gestión eficiente. Zustand est une bibliothèque de gestion d''état qui offre une façon simple de gérer l''état de vos applications. Elle propose une hiérarchie de types d''actions pour une gestion efficace. Zustand ist eine Bibliothek für Statusmanagement, die eine einfache Möglichkeit bietet, den Status Ihrer Anwendungen zu verwalten. Sie bietet eine Hierarchie von Aktionsarten für ein effizientes Management. O Zustand é uma biblioteca de gerenciamento de estado que fornece uma abordagem simples e escalável para gerenciar o estado da aplicação Zustand - это библиотека управления состоянием, которая предоставляет простой и масштабируемый подход к управлению состоянием приложения - ИИ Агенты Zustand هو مكتبة لإدارة الحالة توفر نهجًا بسيطًا وقابل للتوسيع لإدارة حالة التطبيق - أدوات الذكاء الاصطناعي how to use zustand zustand state management zustand vs mobx zustand install zustand setup guide zustand alternative what is zustand zustand documentation zustand tutorial zustand 状态管理 JavaScript状态管理 Public Actions Internal Actions 状态管理优化 AIエージェント JavaScript库 Implements public actions with verb form naming (e.g., createTopic, sendMessage) Utilizes internal actions with internal_ prefix for core business logic implementation Supports optimistic updates and service calls through internal actions Enforces parameter validation and flow orchestration through public actions Provides dispatch methods for seamless UI interactions zustand is a state management system that utilizes a hierarchical action type structure, including public actions and internal actions, to manage application state.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ahrav/scratch-scanner-rs/safe-over-unsafe', 'community', 'ahrav', 'scratch-scanner-rs', 'ahrav/scratch-scanner-rs', 'safe-over-unsafe', 2, 0, 57, '2026-03-02T14:29:47Z', '2026-03-06T07:09:56.925Z', '1a214090c0672f9ad2962d65b67a5890909d85d482b76bdc6ffae4302acb14e8', '{"id":"ahrav/scratch-scanner-rs/safe-over-unsafe","name":"safe-over-unsafe","description":{"en":"The safe-over-unsafe skill helps developers design safe APIs over unsafe Rust modules, ensuring module privacy and soundness. It benefits developers working with MaybeUninit, raw pointers, or FFI.","zh":"安全API设计是确保Rust代码安全性的关键，使用私有字段和安全的公共API实现模块内的安全性","ja":"安全なAPI設計は、Rustコードの安全性を確保するための重要な要素です。モジュール内での安全性を実現するために、プライベートフィールドと安全なパブリックAPIを使用します","ko":"안전한 API 설계는 러스트 코드의 안전성을 보장하는 핵심입니다. 모듈 내에서의 안전성을 구현하기 위해、私有 필드와 안전한 공개 API를 사용합니다","es":"Safe-over-unsafe es una técnica para diseñar API seguras, utilizando módulos privados y evitando el uso de código inseguro","fr":"Safe-over-unsafe est une technique pour concevoir des API sûres, en utilisant des modules privés et en évitant les codes non sécurisés","de":"Safe-over-unsafe ist eine Technik zum Entwerfen sicherer APIs, indem private Module verwendet und unsicherer Code vermieden wird","pt":"O padrão safe-over-unsafe é uma abordagem de design de API que prioriza a segurança em Rust. Ele usa módulos privados e APIs públicas seguras para proteger o código.","ru":"Шаблон safe-over-unsafe - это подход к дизайну API, который отдает приоритет безопасности в Rust. Он использует приватные модули и безопасные публичные API для защиты кода.","ar":"نمط safe-over-unsafe هو نهج لتصميم واجهات برمجة التطبيقات يؤثر على الأمان في لغة Rust. يستخدم الوحدات الخاصة وواجهات برمجة التطبيقات العامة الآمنة لحماية الكود."},"seo":{"title":{"en":"safe-over-unsafe: Mastering Safe API Design for Rust | AI...","zh":"安全API设计优于不安全的Rust - 安全机制指南","ja":"安全なAPI設計のベストプラクティス - unsafe Rustを超えて","ko":"안전한 API 설계 - unsafe Rust를 위한 가이드","es":"Guía de configuración de safe-over-unsafe para API seguras","fr":"Guide de mise en place de safe-over-unsafe pour des API s...","de":"Sichere API-Design mit safe-over-unsafe: Eine Einrichtung...","pt":"Guia de Configuração para safe-over-unsafe: Desenvolvendo...","ru":"ИИ Агенты: Настройка safe-over-unsafe для Безопасного Диз...","ar":"دليل الإعداد ل safe-over-unsafe: تصميم واجهات برمجة تطبيق..."},"description":{"en":"Discover how to ensure module privacy and soundness with safe-over-unsafe. Learn to design safe APIs and review unsafe code for performance and security","zh":"了解安全API设计的重要性和最佳实践，使用MaybeUninit、原始指针和FFI实现高性能","ja":"安全なAPI設計の重要性とベストプラクティスを学び、unsafe Rustを超えた高性能なコードを実現する","ko":"안전한 API 설계의 중요성과 가이드를 익히고, MaybeUninit, 원시 포인터 및 FFI를 사용하여 높은 성능을 달성하십시오","es":"Aprende a diseñar API seguras con safe-over-unsafe, evitando el uso de código inseguro y mejorando el rendimiento","fr":"Découvrez comment concevoir des API sûres avec safe-over-unsafe, en évitant les codes non sécurisés et en améliorant les performances","de":"Erfahren Sie, wie Sie mit safe-over-unsafe sichere APIs entwerfen, unsicheren Code vermeiden und die Leistung verbessern","pt":"Aprenda a desenvolver APIs seguras com Rust usando o padrão safe-over-unsafe. Descubra como proteger seu código com módulos privados e APIs públicas seguras.","ru":"Узнайте, как разработать безопасный API с помощью Rust и шаблона safe-over-unsafe. Откройте для себя, как защитить ваш код с помощью приватных модулей и безо...","ar":"تعلم كيفية تصميم واجهات برمجة تطبيقات آمنة باستخدام لغة Rust ونمط safe-over-unsafe. اكتشف كيفية حماية كودك باستخدام الوحدات الخاصة وواجهات برمجة تطبيقات عامة..."},"definition":{"en":"safe-over-unsafe is a design approach that prioritizes module privacy and soundness over the use of unsafe keywords in Rust programming","zh":"安全API设计是指使用私有字段和安全的公共API确保Rust代码的安全性","ja":"安全なAPI設計とは、プライベートフィールドと安全なパブリックAPIを使用して、Rustコードの安全性を確保すること","ko":"안전한 API 설계란、私有 필드와 안전한 공개 API를 사용하여 러스트 코드의 안전성을 보장하는 것을 말합니다","es":"Safe-over-unsafe es una técnica de diseño de API que prioriza la seguridad sobre la flexibilidad","fr":"Safe-over-unsafe est une technique de conception d''API qui donne la priorité à la sécurité plutôt qu''à la flexibilité","de":"Safe-over-unsafe ist eine API-Design-Technik, die Sicherheit über Flexibilität stellt","pt":"O que é safe-over-unsafe? É uma abordagem de design de API que usa módulos privados e APIs públicas seguras para proteger o código em Rust.","ru":"Что такое safe-over-unsafe? Это подход к дизайну API, который использует приватные модули и безопасные публичные API для защиты кода в Rust.","ar":"ما هو safe-over-unsafe؟ هو نهج لتصميم واجهات برمجة التطبيقات يستخدم الوحدات الخاصة وواجهات برمجة التطبيقات العامة الآمنة لحماية الكود في لغة Rust."},"features":{"en":["Designs new types backed by MaybeUninit for secure data handling","Adds unsafe blocks to existing code for performance optimization","Reviews unsafe code for soundness and security vulnerabilities","Implements Send, Sync, and Drop traits for custom types","Ensures private fields behind a safe public API within a module or crate"],"zh":["使用MaybeUninit实现高性能","添加unsafe块以提高代码性能","实现Send/Sync/Drop类型的安全性","使用私有字段和安全的公共API确保模块内的安全性","安全地设计新的类型以支持FFI","Reviewing不安全代码以确保安全性"],"ja":["MaybeUninitを使用して高性能を実現","unsafeブロックを追加してコードのパフォーマンスを向上させる","Send/Sync/Dropタイプの安全性を実現","プライベートフィールドと安全なパブリックAPIを使用してモジュール内での安全性を確保","FFIをサポートする新しいタイプの安全な設計","不安全なコードをレビューして安全性を確保"],"ko":["MaybeUninit를 사용하여 높은 성능을 달성","unsafe 블록을 추가하여 코드 성능을 향상","Send/Sync/Drop 유형의 안전성 구현","개인 필드와 안전한 공개 API를 사용하여 모듈 내에서의 안전성 보장","FFI를 지원하는 새로운 유형의 안전한 설계","비안전 코드를 검토하여 안전성 보장"],"es":["Diseño de tipos seguros utilizando MaybeUninit","Uso de punteros raw y FFI de manera segura","Implementación de Send/Sync/Drop para tipos personalizados","Revisión de código inseguro para garantizar la seguridad","Mejora del rendimiento mediante el uso de código seguro"],"fr":["Conception de types sûrs en utilisant MaybeUninit","Utilisation de pointeurs raw et FFI de manière sûre","Implémentation de Send/Sync/Drop pour des types personnalisés","Révision de code non sécurisé pour garantir la sécurité","Amélioration des performances en utilisant du code sûr"],"de":["Entwurf sicherer Typen mit MaybeUninit","Sichere Verwendung von Raw-Pointern und FFI","Implementierung von Send/Sync/Drop für benutzerdefinierte Typen","Überprüfung von unsicherem Code zur Gewährleistung der Sicherheit","Leistungsverbesserung durch den Einsatz von sicherem Code"],"pt":["Uso de módulos privados para proteger o código","Implementação de APIs públicas seguras com Rust","Desenvolvimento de tipos personalizados com MaybeUninit e ponteiros brutos","Adição de blocos unsafe para melhorar o desempenho","Revisão de código unsafe para garantir a segurança","Implementação de Send/Sync/Drop para tipos personalizados"],"ru":["Использование приватных модулей для защиты кода","Реализация безопасных публичных API с помощью Rust","Разработка пользовательских типов с помощью MaybeUninit и сырых указателей","Добавление блоков unsafe для улучшения производительности","Проверка кода unsafe для обеспечения безопасности","Реализация Send/Sync/Drop для пользовательских типов"],"ar":["استخدام الوحدات الخاصة لحماية الكود","تنفيذ واجهات برمجة تطبيقات عامة آمنة باستخدام لغة Rust","تصميم أنواع مخصصة باستخدام MaybeUninit và مؤشرات خام","إضافة كتلة غير آمنة لتحسين الأداء","مراجعة كود غير آمن لضمان الأمان","تنفيذ Send/Sync/Drop لأنواع مخصصة"]},"keywords":{"en":["how to use safe-over-unsafe","safe-over-unsafe vs unsafe Rust","safe-over-unsafe install guide","what is safe-over-unsafe","safe-over-unsafe alternative to raw pointers","safe-over-unsafe setup for MaybeUninit","safe-over-unsafe best practices for FFI","safe-over-unsafe tutorial for Rust developers"],"zh":["安全API设计","Rust安全性","MaybeUninit","原始指针","FFI","unsafe代码","Send/Sync/Drop","私有字段","安全的公共API","模块内安全性"],"ja":["安全なAPI設計","Rustの安全性","MaybeUninit","生のポインター","FFI","unsafeコード","Send/Sync/Drop","プライベートフィールド","安全なパブリックAPI","モジュール内での安全性"],"ko":["안전한 API 설계","러스트 안전성","MaybeUninit","원시 포인터","FFI","unsafe 코드","Send/Sync/Drop","개인 필드","안전한 공개 API","모듈 내에서의 안전성"],"es":["diseño de API seguras","safe-over-unsafe","Rust","MaybeUninit","punteros raw","FFI","Send","Sync","Drop"],"fr":["conception d''API sûres","safe-over-unsafe","Rust","MaybeUninit","pointeurs raw","FFI","Send","Sync","Drop"],"de":["sichere API-Design","safe-over-unsafe","Rust","MaybeUninit","Raw-Pointer","FFI","Send","Sync","Drop"],"pt":["safe-over-unsafe","desenvolvimento de API segura","Rust","módulos privados","APIs públicas seguras","MaybeUninit","ponteiros brutos","blocos unsafe","Send","Sync","Drop"],"ru":["safe-over-unsafe","разработка безопасного API","Rust","приватные модули","безопасные публичные API","MaybeUninit","сырые указатели","блоки unsafe","Send","Sync","Drop"],"ar":["safe-over-unsafe","تصميم واجهات برمجة تطبيقات آمنة","Rust","الوحدات الخاصة","واجهات برمجة تطبيقات عامة آمنة","MaybeUninit","مؤشرات خام","كتلة غير آمنة","Send","Sync","Drop"]}},"owner":"ahrav","repo":"scratch-scanner-rs","repoPath":"ahrav/scratch-scanner-rs","stars":2,"forks":0,"updatedAt":"2026-03-02T14:29:47Z","topics":[],"category":"community","skillMd":{"name":"safe-over-unsafe","description":"Use when designing safe public APIs that wrap unsafe Rust code, adding unsafe blocks to existing types, reviewing unsafe code for soundness, or creating new types backed by raw pointers, MaybeUninit, or FFI","bodyPreview":"# Safe API Design Over Unsafe Rust\n\nModule privacy is the soundness boundary — not the `unsafe` keyword. The\n`unsafe {}` block is a syntax marker; the real safety mechanism is private\nfields behind a safe public API, within a module (or crate) where all code\nis trusted.\n\n## When to Use\n\n- Designing a new type backed by `MaybeUninit`, raw pointers, or FFI\n- Adding `unsafe` blocks to existing code for performance\n- Reviewing unsafe code for soundness\n- Implementing `Send`/`Sync`/`Drop` for types w","body":"# Safe API Design Over Unsafe Rust\n\nModule privacy is the soundness boundary — not the `unsafe` keyword. The\n`unsafe {}` block is a syntax marker; the real safety mechanism is private\nfields behind a safe public API, within a module (or crate) where all code\nis trusted.\n\n## When to Use\n\n- Designing a new type backed by `MaybeUninit`, raw pointers, or FFI\n- Adding `unsafe` blocks to existing code for performance\n- Reviewing unsafe code for soundness\n- Implementing `Send`/`Sync`/`Drop` for types with unsafe internals\n\n## Design Checklist\n\nFollow every step. Skipping any step is how soundness bugs happen.\n\n### 1. Establish the Safety Boundary\n\n- **Private fields, private module, safe public API.** Every public method\n  — safe or not — is part of the soundness proof. Changing `<` to `<=` in\n  a safe bounds check can make all unsafe blocks unsound.\n- **Consider crate-level isolation.** Consumer crate uses\n  `#![forbid(unsafe_code)]`; unsafe lives in a dedicated crate.\n- **Enable lints at the crate root:**\n  ```rust\n  #![deny(unsafe_op_in_unsafe_fn)]\n  #![deny(clippy::undocumented_unsafe_blocks)]\n  ```\n\n### 2. Document Invariants at the Type Level\n\nTwo kinds of invariants exist — conflating them causes bugs:\n\n- **Validity invariant**: Must hold at ALL times. Violation is instant UB\n  even if the value is never \"used.\" (Example: `bool` must be 0 or 1.)\n- **Safety invariant**: Must hold at API boundaries. May be temporarily\n  violated internally. (Example: `Vec`''s `len <= cap`.)\n\nDocument both in a module-level `//!` or struct-level `///` doc comment:\n```rust\n/// # Invariants\n/// - `len <= CAPACITY` (safety)\n/// - Slots `[head..head+len)` (mod cap) are initialized (safety)\n/// - Initialized slots contain valid `T` values (validity)\n```\n\n### 3. Enforce at Compile Time First\n\nEvery invariant should be evaluated: can this be a const assertion,\na NonZero type, or a typestate transition instead of a runtime check?\n\n```rust\nconst { assert!(N > 0 && N.is_power_of_two()) }; // compile-time\n```\n\nCompile-time enforcement eliminates entire bug classes. Runtime\n`debug_assert!` is the fallback — use `assert!` in public API\npreconditions that guard unsafe code in the implementation.\n\n### 4. Write SAFETY Comments as Proof Sketches\n\nEvery `// SAFETY:` comment must argue invariant preservation, not just\nstate a fact. Use this structure:\n\n```rust\n// SAFETY: [what unsafe operation is being performed]\n// Invariant: [which safety invariant holds here — and WHY from the code path]\n// Implies: [which validity invariant this satisfies for the unsafe op]\n// Preserved: [what invariants remain intact after this operation]\n```\n\nBad: `// SAFETY: index is in bounds`\nGood: `// SAFETY: physical = idx & MASK, so physical < CAPACITY (mask clears\n// high bits). The element is initialized because idx < self.len, and our\n// safety invariant guarantees slots [head..head+len) are initialized.\n// This satisfies assume_init_ref''s requirement that the value is valid T.`\n\nFor `unsafe fn`, use `# Safety` doc sections documenting caller obligations.\n\n### 5. Get Variance, PhantomData, and Send/Sync Right\n\n**Incorrect Send/Sync is the #1 real-world unsafe soundness bug** (tokio\nRUSTSEC-2025-0023, lock_api RUSTSEC-2020-0070, windows RUSTSEC-2022-0008).\n\n| Situation | Action |\n|-----------|--------|\n| Type uses `[MaybeUninit<T>; N]` | Auto-derive is correct. No PhantomData needed. |\n| Type uses raw pointers | Add `PhantomData<T>` for owned data (covariant, correct Send/Sync). |\n| Need manual Send/Sync | **Red flag.** Bound generics: `unsafe impl<T: Send + Sync> Sync for MyType<T> {}` |\n| Unsure about variance | If the type *owns* T, it should be covariant (like Vec). Use `PhantomData<T>`. |\n\nAlways prefer auto-derivation. Add compile-time assertions:\n```rust\nconst _: () = {\n    fn assert_send<T: Send>() { fn requires_send<S: Send>() {} requires_send::<MyType<T>>(); }\n    fn assert_sync<T: Sync>() { fn requires_sync<S: Sync>() {} requires_sync::<MyType<T>>(); }\n};\n```\n\n### 6. Handle Panic Safety\n\nIf an operation modifies state in multiple steps and any step can panic\n(e.g., `T::drop()`, `T::clone()`), use the **decrement-before-drop** or\n**guard** pattern:\n\n```rust\n// Decrement-before-drop: len reflects reality even if drop panics\nwhile self.len > 0 {\n    self.len -= 1;\n    unsafe { self.buf[self.len].assume_init_drop(); }\n}\n```\n\nTest with a deliberately-panicking `Drop` impl via `catch_unwind`.\n\n### 7. Defend Against Generic Parameters\n\nUnsafe code cannot trust safe trait implementations. `T::drop()` can\npanic. `T::clone()` can panic. `Ord` impls can be inconsistent. Write\ndefensively so broken trait impls cause wrong results, never UB.\n\n## Verification Layers\n\nAll three are required. No single tool is sufficient.\n\n| Layer | Tool | What It Catches | Required |\n|-------|------|----------------|----------|\n| Dynamic UB | `cargo +nightly miri test` | Aliasing, uninit, alignment, use-after-free | **Every test run** |\n| Aliasing model | `MIRIFLAGS=\"-Zmiri-tree-borrows\" cargo +nightly miri test` | Tree Borrows violations | **CI** |\n| Reference model | proptest vs known-correct safe impl (e.g., VecDeque) | Logic errors, edge cases | **Every test run** |\n| Drop correctness | `DropTracker` with `Arc<AtomicUsize>` | Double-drop, leaks | **Every test run** |\n| Bounded proof | Kani proof harnesses | Exhaustive invariant verification | **Critical code** |\n\n## Risk Checklist\n\nBefore declaring unsafe code \"done,\" verify each:\n\n- [ ] No manual `unsafe impl Send/Sync` without restrictive bounds on generics\n- [ ] All values crossing safe→unsafe boundary are validated\n- [ ] `MaybeUninit`: using `write()` for init, tracking init state, never `mem::uninitialized`\n- [ ] Multi-step operations handle panics (guard/decrement-before-drop pattern)\n- [ ] `len`/`capacity` updated atomically with the memory operation\n- [ ] Public API preconditions use `assert!` (not just `debug_assert!`)\n- [ ] PhantomData matches ownership semantics (covariant for owned data)\n- [ ] Miri passes under both Stacked Borrows and Tree Borrows\n\n## Pattern Catalog\n\n| Pattern | When to Use | Exemplar |\n|---------|------------|----------|\n| Private fields + safe API | Always | std Vec |\n| Crate-level `#![forbid(unsafe_code)]` | Multi-crate projects | Fuchsia, gossip-rs |\n| Compile-time const assertions | Numeric invariants | RingBuffer power-of-2 |\n| `MaybeUninit` + init tracking | Uninitialized storage | std MaybeUninit docs |\n| PhantomData for variance | Raw pointer containers | Rustonomicon Vec |\n| Guard struct for panic safety | Multi-step mutations | hashbrown HashMap |\n| Typestate (generic state param) | State-dependent operations | serde Serializer |\n| Sealed trait | Fixed impl set | zerocopy |\n| `unsafe trait` as capability gate | External impls needed | bytemuck Pod |\n| Lifetime-encoded validity | Temporal access control | crossbeam-epoch Guard |\n\n## References\n\n1. [Rustonomicon: Working with Unsafe](https://doc.rust-lang.org/nomicon/working-with-unsafe.html)\n2. [Ralf Jung: The Scope of Unsafe](https://www.ralfj.de/blog/2016/01/09/the-scope-of-unsafe.html)\n3. [Unsafe Code Guidelines: Glossary](https://rust-lang.github.io/unsafe-code-guidelines/glossary.html)\n4. [std::mem::MaybeUninit](https://doc.rust-lang.org/std/mem/union.MaybeUninit.html)\n5. [Miri](https://github.com/rust-lang/miri)\n6. [Kani Rust Verifier](https://model-checking.github.io/kani/)\n7. [Stacked Borrows (POPL 2020)](https://plv.mpi-sws.org/rustbelt/stacked-borrows/)\n8. [Tree Borrows](https://www.ralfj.de/blog/2023/06/02/tree-borrows.html)\n9. [Fuchsia Unsafe Guidelines](https://fuchsia.dev/fuchsia-src/development/languages/rust/unsafe)\n10. [Rust API Guidelines](https://rust-lang.github.io/api-guidelines/)\n11. [RustSec Advisory Database](https://rustsec.org/advisories/)\n"},"lastSynced":"2026-03-06T07:09:56.925Z","agentAnalysis":{"suitability":{"en":"Ideal for Rust-focused AI Agents requiring secure API design over unsafe modules, such as those utilizing MaybeUninit, raw pointers, or FFI.","zh":"适合需要在不安全模块上设计安全API的Rust专注AI代理，例如那些使用MaybeUninit、原始指针或FFI的模块。","ja":"MaybeUninit、生ポインタ、またはFFIを使用するような、安全なAPI設計が必要なRustに特化したAIエージェントに適しています。","ko":"MaybeUninit, 원시 포인터 또는 FFI를 사용하는 것과 같은 안전하지 않은 모듈에서 안전한 API를 설계해야 하는 Rust 중심의 AI 에이전트에 적합합니다.","es":"Ideal para agentes de inteligencia artificial enfocados en Rust que requieren un diseño de API seguro sobre módulos inseguros, como aquellos que utilizan MaybeUninit, punteros crudos o FFI.","fr":"Idéal pour les agents d''intelligence artificielle axés sur Rust nécessitant une conception d''API sécurisée sur des modules non sécurisés, tels que ceux utilisant MaybeUninit, des pointeurs bruts ou FFI.","de":"Ideal für Rust-fokussierte KI-Agents, die ein sicheres API-Design über unsichere Module benötigen, wie z.B. solche, die MaybeUninit, Rohzeiger oder FFI verwenden.","pt":"Ideal para agentes de IA focados em Rust que exigem design de API seguro sobre módulos inseguros, como aqueles que utilizam MaybeUninit, ponteiros brutos ou FFI.","ru":"Идеально для агентов ИИ, ориентированных на Rust, требующих безопасного проектирования API поверх небезопасных модулей, таких как те, которые используют MaybeUninit, сырые указатели или FFI.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يركز على Rust ويحتاج إلى تصميم واجهة برمجة تطبيقات آمنة أكثر من الوحدات غير الآمنة، مثل تلك التي تستخدم MaybeUninit أو المؤشرات الخام أو FFI."},"recommendation":{"en":"Empowers agents to enforce module privacy and soundness by designing safe public APIs over unsafe Rust modules, leveraging the soundness boundary for secure development, and ensuring compliance with Send/Sync/Drop implementations.","zh":"赋予代理人设计安全的公共API以强制模块隐私和健全性，利用健全性边界进行安全开发，并确保符合Send/Sync/Drop实现。","ja":"エージェントは、安全なパブリックAPIを設計してモジュールのプライバシーと健全性を強制し、健全性の境界を利用してセキュアな開発を行い、Send/Sync/Dropの実装に準拠させることができます。","ko":"에이전트가 안전한 공개 API를 설계하여 모듈 개인 정보 및健全성을 강제하고,健全성 경계를 활용하여 보안 개발을 수행하며, Send/Sync/Drop 구현을 준수하도록 합니다.","es":"Habilita a los agentes a aplicar privacidad y solidez de módulos diseñando API públicas seguras sobre módulos inseguros de Rust, aprovechando el límite de solidez para el desarrollo seguro y garantizando el cumplimiento de las implementaciones Send/Sync/Drop.","fr":"Permet aux agents d''appliquer la confidentialité et la solidité des modules en concevant des API publiques sécurisées sur des modules non sécurisés de Rust, en exploitant la limite de solidité pour le développement sécurisé et en garantissant la conformité avec les implémentations Send/Sync/Drop.","de":"Ermächtigt die Agents, Modulprivatsphäre und -solidez durchzusetzen, indem sie sichere öffentliche APIs über unsichere Rust-Module entwerfen, die Soliditätsgrenze für die sichere Entwicklung nutzen und die Einhaltung von Send/Sync/Drop-Implementierungen sicherstellen.","pt":"Habilita os agentes a impor privacidade e solidez de módulo, projetando APIs públicas seguras sobre módulos Rust inseguros, aproveitando a fronteira de solidez para desenvolvimento seguro e garantindo conformidade com implementações Send/Sync/Drop.","ru":"Наделяет агентов возможностью обеспечить конфиденциальность и правильность модулей, проектируя безопасные публичные API поверх небезопасных модулей Rust, используя границу правильности для безопасной разработки и обеспечивая соответствие реализациям Send/Sync/Drop.","ar":"يمنح العميل القدرة على فرض خصوصية وصدق الوحدات من خلال تصميم واجهات برمجة تطبيقات عامة آمنة أكثر من الوحدات غير الآمنة في Rust، واستخدام حد الصدق لتطوير آمن وتأكيد الامتثال لتطبيقات Send/Sync/Drop."},"useCases":{"en":["Designing secure APIs for new types backed by MaybeUninit or raw pointers","Reviewing and optimizing existing unsafe code for soundness and performance","Implementing Send/Sync/Drop for custom types to ensure thread safety"],"zh":["为MaybeUninit或原始指针支持的新类型设计安全API","检查和优化现有的不安全代码以实现健全性和性能","为自定义类型实现Send/Sync/Drop以确保线程安全"],"ja":["MaybeUninitまたは生ポインタをサポートする新しいタイプのための安全なAPIを設計する","健全性とパフォーマンスのために既存の不安全なコードをレビューおよび最適化する","カスタムタイプのためのSend/Sync/Dropを実装してスレッドセーフティを確保する"],"ko":["MaybeUninit 또는 원시 포인터를 지원하는 새로운 타입을 위한 안전한 API를 설계하는 것","健全성 및 성능을 위해 기존의 안전하지 않은 코드를 검토 및 최적화하는 것","사용자 정의 타입을 위한 Send/Sync/Drop을 구현하여 스레드 안전성을 보장하는 것"],"es":["Diseñar API seguras para nuevos tipos respaldados por MaybeUninit o punteros crudos","Revisar y optimizar el código inseguro existente para solidez y rendimiento","Implementar Send/Sync/Drop para tipos personalizados para garantizar la seguridad entre subprocesos"],"fr":["Concevoir des API sécurisées pour de nouveaux types pris en charge par MaybeUninit ou des pointeurs bruts","Réviser et optimiser le code non sécurisé existant pour la solidité et les performances","Implémenter Send/Sync/Drop pour des types personnalisés pour garantir la sécurité entre threads"],"de":["Sichere APIs für neue Typen zu entwerfen, die von MaybeUninit oder Rohzeigern unterstützt werden","Vorhandenen unsicheren Code zu überprüfen und zu optimieren, um Solidität und Leistung zu verbessern","Send/Sync/Drop für benutzerdefinierte Typen zu implementieren, um die Threadsicherheit zu gewährleisten"],"pt":["Projetar APIs seguras para novos tipos com suporte a MaybeUninit ou ponteiros brutos","Revisar e otimizar código inseguro existente para solidez e desempenho","Implementar Send/Sync/Drop para tipos personalizados para garantir segurança de thread"],"ru":["Проектировать безопасные API для новых типов, поддерживающих MaybeUninit или сырые указатели","Просматривать и оптимизировать существующий небезопасный код для правильности и производительности","Реализовывать Send/Sync/Drop для пользовательских типов для обеспечения безопасности потоков"],"ar":["تصميم واجهات برمجة تطبيقات آمنة للأنواع الجديدة المدعومة من قبل MaybeUninit أو المؤشرات الخام","مراجعة وتحسين الكود غير الآمن الحالي لضمان الصدق والأداء","تنفيذ Send/Sync/Drop لأنواع مخصصة لضمان سلامة الخيط"]},"limitations":{"en":["Requires Rust programming knowledge","Focused on Rust ecosystem, not applicable to other programming languages"],"zh":["需要Rust编程知识","专注于Rust生态系统，不适用于其他编程语言"],"ja":["Rustプログラミングの知識が必要","Rustエコシステムに焦点を当てているため、他のプログラミング言語には適用されません"],"ko":["Rust 프로그래밍 지식이 필요합니다.","Rust 생태계에 중점을 두고 있으므로 다른 프로그래밍 언어에는 적용되지 않습니다."],"es":["Requiere conocimientos de programación en Rust","Se centra en el ecosistema de Rust, no es aplicable a otros lenguajes de programación"],"fr":["Nécessite des connaissances en programmation Rust","Se concentre sur l''écosystème Rust, n''est pas applicable à d''autres langages de programmation"],"de":["Benötigt Rust-Programmierkenntnisse","Konzentriert sich auf das Rust-Ökosystem, nicht anwendbar auf andere Programmiersprachen"],"pt":["Exige conhecimento de programação em Rust","Focado no ecossistema Rust, não se aplica a outras linguagens de programação"],"ru":["Требует знаний программирования на Rust","Ориентирован на экосистему Rust, не применимо к другим языкам программирования"],"ar":["يتطلب معرفة بالبرمجة بلغة Rust","يركز على نظام Rust، لا ينطبق على لغات البرمجة الأخرى"]},"version":4},"contentHash":"1a214090c0672f9ad2962d65b67a5890909d85d482b76bdc6ffae4302acb14e8","qualityScore":57}');
