INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ahrav/scratch-scanner-rs/safe-over-unsafe', 'safe-over-unsafe', 'ahrav', 'scratch-scanner-rs', 'community', 'safe-over-unsafe ahrav scratch-scanner-rs community The safe-over-unsafe skill helps developers design safe APIs over unsafe Rust modules, ensuring module privacy and soundness. It benefits developers working with MaybeUninit, raw pointers, or FFI. 安全API设计是确保Rust代码安全性的关键，使用私有字段和安全的公共API实现模块内的安全性 安全なAPI設計は、Rustコードの安全性を確保するための重要な要素です。モジュール内での安全性を実現するために、プライベートフィールドと安全なパブリックAPIを使用します 안전한 API 설계는 러스트 코드의 안전성을 보장하는 핵심입니다. 모듈 내에서의 안전성을 구현하기 위해、私有 필드와 안전한 공개 API를 사용합니다 Safe-over-unsafe es una técnica para diseñar API seguras, utilizando módulos privados y evitando el uso de código inseguro Safe-over-unsafe est une technique pour concevoir des API sûres, en utilisant des modules privés et en évitant les codes non sécurisés Safe-over-unsafe ist eine Technik zum Entwerfen sicherer APIs, indem private Module verwendet und unsicherer Code vermieden wird O padrão safe-over-unsafe é uma abordagem de design de API que prioriza a segurança em Rust. Ele usa módulos privados e APIs públicas seguras para proteger o código. Шаблон safe-over-unsafe - это подход к дизайну API, который отдает приоритет безопасности в Rust. Он использует приватные модули и безопасные публичные API для защиты кода. نمط safe-over-unsafe هو نهج لتصميم واجهات برمجة التطبيقات يؤثر على الأمان في لغة Rust. يستخدم الوحدات الخاصة وواجهات برمجة التطبيقات العامة الآمنة لحماية الكود. how to use safe-over-unsafe safe-over-unsafe vs unsafe Rust safe-over-unsafe install guide what is safe-over-unsafe safe-over-unsafe alternative to raw pointers safe-over-unsafe setup for MaybeUninit safe-over-unsafe best practices for FFI safe-over-unsafe tutorial for Rust developers 安全API设计 Rust安全性 MaybeUninit 原始指针 FFI unsafe代码 Send/Sync/Drop 私有字段 安全的公共API 模块内安全性 Designs new types backed by MaybeUninit for secure data handling Adds unsafe blocks to existing code for performance optimization Reviews unsafe code for soundness and security vulnerabilities Implements Send, Sync, and Drop traits for custom types Ensures private fields behind a safe public API within a module or crate safe-over-unsafe is a design approach that prioritizes module privacy and soundness over the use of unsafe keywords in Rust programming');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lawless-m/Gwen/Reverse Proxy Deployment', 'community', 'lawless-m', 'Gwen', 'lawless-m/Gwen', 'Reverse Proxy Deployment', 0, 0, 57, '2026-03-07T12:46:33.423Z', '2026-03-07T12:52:58.852Z', '4953cd51d5e885379697cc5c9ce3bd717b616462555b73bcc6ba8e1685c3ae95', '{"id":"lawless-m/Gwen/Reverse Proxy Deployment","name":"Reverse Proxy Deployment","description":{"en":"Reverse Proxy Deployment enables developers to deploy web applications behind the Apache reverse proxy on rivsprod01. This skill covers frontend relative URL patterns and Apache ProxyPass configuration.","zh":"本指南介绍如何使用Apache反向代理部署Web应用程序，包括前端相对URL模式和ProxyPass配置","ja":"このガイドでは、Apacheのリバースプロキシを使用してWebアプリケーションをデプロイする方法について説明します。フロントエンドの相対URLパターンとProxyPassの設定を含みます","ko":"이 가이드는 Apache 리버스 프록시를 사용하여 웹 애플리케이션을 배포하는 방법에 대해 설명합니다. 프론트엔드 상대 URL 패턴과 ProxyPass 구성이 포함됩니다","es":"El proxy inverso permite que tus aplicaciones web se ejecuten detrás de un servidor Apache, utilizando URL relativas y configuración de ProxyPass","fr":"Le proxy inverse permet d''exécuter vos applications web derrière un serveur Apache, en utilisant des URL relatives et une configuration de ProxyPass","de":"Der Reverse-Proxy ermöglicht es, Webanwendungen hinter einem Apache-Server auszuführen, indem relative URLs und ProxyPass-Konfigurationen verwendet werden","pt":"Configuração de proxy reverso para aplicações web com Apache e rivsprod01, incluindo padrões de URL relativos e configuração de ProxyPass.","ru":"Настройка обратного прокси для веб-приложений с Apache и rivsprod01, включая относительные шаблоны URL и конфигурацию ProxyPass для ИИ Агентов.","ar":"إعداد بروكسي عكسي لتقنيات الويب مع Apache و rivsprod01، بما في ذلك أنماط URL النسبية وتكوين ProxyPass"},"seo":{"title":{"en":"Reverse Proxy Deployment: Setup Guide for AI Agents","zh":"反向代理部署设置指南","ja":"リバースプロキシデプロイメントベストプラクティス","ko":"리버스 프록시 배포 설정 가이드","es":"Guía de Configuración de Proxy Inverso para Desarrolladores","fr":"Guide de Configuration de Proxy Inverse pour les Développ...","de":"Reverse-Proxy-Setup-Leitfaden für Entwickler","pt":"Guia de Configuração de Proxy Reverso para Desenvolvedores","ru":"Руководство по настройке обратного прокси для разработчик...","ar":"دليل إعداد بروكسي عكسي لمطوري الأدوات الذكية"},"description":{"en":"Learn how to deploy web applications behind Apache reverse proxy on rivsprod01. Get started with our step-by-step guide and master Reverse Proxy Deployment t...","zh":"使用Apache反向代理部署Web应用程序，了解前端相对URL模式和ProxyPass配置","ja":"Apacheのリバースプロキシを使用してWebアプリケーションをデプロイする方法、フロントエンドの相対URLパターンとProxyPassの設定について","ko":"Apache 리버스 프록시를 사용하여 웹 애플리케이션을 배포하는 방법, 프론트엔드 상대 URL 패턴과 ProxyPass 구성에 대해 알아보기","es":"Aprende a implementar un proxy inverso con Apache para tus aplicaciones web, incluyendo patrones de URL relativa y configuración de ProxyPass","fr":"Découvrez comment mettre en place un proxy inverse avec Apache pour vos applications web, y compris les modèles d''URL relative et la configuration de ProxyPass","de":"Erfahren Sie, wie Sie einen Reverse-Proxy mit Apache für Ihre Webanwendungen implementieren, einschließlich relativer URL-Muster und ProxyPass-Konfiguration","pt":"Aprenda a configurar um proxy reverso para suas aplicações web com Apache e rivsprod01","ru":"Узнайте, как настроить обратный прокси для ваших веб-приложений с Apache и rivsprod01 для ИИ Агентов","ar":"تعرف على كيفية إعداد بروكسي عكسي لتقنيات الويب الخاصة بك مع Apache و rivsprod01"},"definition":{"en":"Reverse Proxy Deployment is a technique for deploying web applications behind a reverse proxy server, such as Apache, to manage incoming requests and improve security.","zh":"反向代理部署是一种使用Apache反向代理服务器部署Web应用程序的方法","ja":"リバースプロキシデプロイメントは、Apacheのリバースプロキシサーバーを使用してWebアプリケーションをデプロイする方法です","ko":"리버스 프록시 배포는 Apache 리버스 프록시 서버를 사용하여 웹 애플리케이션을 배포하는 방법입니다","es":"Un proxy inverso es un servidor que actúa como intermediario entre un cliente y un servidor, redirigiendo solicitudes y respuestas","fr":"Un proxy inverse est un serveur qui agit comme intermédiaire entre un client et un serveur, redirigeant les requêtes et les réponses","de":"Ein Reverse-Proxy ist ein Server, der als Vermittler zwischen einem Client und einem Server agiert, indem er Anfragen und Antworten umleitet","pt":"Proxy reverso é uma técnica de encaminhamento de tráfego de rede que esconde a identidade do servidor.","ru":"Обратный прокси - это техника перенаправления сетевого трафика, которая скрывает идентичность сервера для ИИ Агентов.","ar":"البروكسي العكسي هو تقنية لإعادة توجيه حركة المرور الشبكية التي تخفي هوية الخادم"},"features":{"en":["Uses relative URLs in frontend code for compatibility behind the proxy","Configures Apache ProxyPass on rivsprod01 for seamless request forwarding","Supports deployment of web applications on dw.ramsden-international.com","Covers frontend relative URL patterns for optimal proxy performance","Requires Apache config creation for ProxyPass setup"],"zh":["使用相对URL的前端代码","Apache ProxyPass配置","支持rivsprod01（dw.ramsden-international.com）","反向代理服务器部署","Web应用程序安全性增强"],"ja":["相対URLを使用したフロントエンドコード","Apache ProxyPassの設定","rivsprod01（dw.ramsden-international.com）への対応","リバースプロキシサーバーのデプロイ","Webアプリケーションのセキュリティ強化"],"ko":["상대 URL을 사용하는 프론트엔드 코드","Apache ProxyPass 구성","rivsprod01（dw.ramsden-international.com） 지원","리버스 프록시 서버 배포","웹 애플리케이션 보안 강화"],"es":["Uso de URL relativas en el código frontend","Configuración de ProxyPass en Apache","Compatibilidad con patrones de URL relativa","Implementación de proxy inverso en rivsprod01","Soporte para aplicaciones web detrás de un servidor Apache"],"fr":["Utilisation d''URL relatives dans le code frontend","Configuration de ProxyPass dans Apache","Compatibilité avec les modèles d''URL relative","Mise en place de proxy inverse sur rivsprod01","Prise en charge des applications web derrière un serveur Apache"],"de":["Verwendung relativer URLs im Frontend-Code","Konfiguration von ProxyPass in Apache","Kompatibilität mit relativen URL-Mustern","Implementierung von Reverse-Proxy auf rivsprod01","Unterstützung für Webanwendungen hinter einem Apache-Server"],"pt":["Utilização de URLs relativos","Configuração de ProxyPass no Apache","Compatibilidade com rivsprod01","Suporte a aplicações web","Encaminhamento de tráfego de rede"],"ru":["Использование относительных URL","Конфигурация ProxyPass в Apache","Совместимость с rivsprod01","Поддержка веб-приложений для ИИ Агентов","Перенаправление сетевого трафика"],"ar":["استخدام عناوين URL النسبية","تكوين ProxyPass في Apache","التوافق مع rivsprod01","دعم تقنيات الويب","إعادة توجيه حركة المرور الشبكية"]},"keywords":{"en":["how to use Reverse Proxy Deployment","Reverse Proxy Deployment setup guide","Apache reverse proxy configuration","Reverse Proxy Deployment vs NGINX","what is Reverse Proxy Deployment","Reverse Proxy Deployment install on rivsprod01","Reverse Proxy Deployment tutorial for AI agents","dw.ramsden-international.com deployment","Apache ProxyPass configuration example"],"zh":["反向代理部署","Apache反向代理","Web应用程序部署","相对URL","ProxyPass配置","rivsprod01","dw.ramsden-international.com","AIエージェント","AI工具"],"ja":["リバースプロキシデプロイメント","Apacheリバースプロキシ","Webアプリケーションデプロイ","相対URL","ProxyPassの設定","rivsprod01","dw.ramsden-international.com","AIエージェント","AIツール"],"ko":["리버스 프록시 배포","Apache 리버스 프록시","웹 애플리케이션 배포","상대 URL","ProxyPass 구성","rivsprod01","dw.ramsden-international.com","AI 에이전트","AI 도구"],"es":["proxy inverso","apache proxy","url relativa","proxypass","desarrollo web","seguridad web","configuración de servidor","rivsprod01","dw.ramsden-international.com"],"fr":["proxy inverse","apache proxy","url relative","proxypass","développement web","sécurité web","configuration de serveur","rivsprod01","dw.ramsden-international.com"],"de":["reverse-proxy","apache-proxy","relative url","proxypass","webentwicklung","web-sicherheit","server-konfiguration","rivsprod01","dw.ramsden-international.com"],"pt":["proxy reverso","apache","rivsprod01","desenvolvimento web","segurança de rede","configuração de proxy","urls relativos","proxy pass"],"ru":["обратный прокси","apache","rivsprod01","разработка веб-приложений","безопасность сети","конфигурация прокси","относительные url","proxy pass для ИИ Агентов"],"ar":["البروكسي العكسي","apache","rivsprod01","تطوير الويب","أمان الشبكة","تكوين بروكسي","عناوين url النسبية","بروكسي باس"]}},"owner":"lawless-m","repo":"Gwen","repoPath":"lawless-m/Gwen","stars":0,"forks":0,"updatedAt":"2026-03-07T12:46:33.423Z","topics":[],"category":"community","skillMd":{"name":"Reverse Proxy Deployment","description":"Deploy web applications behind Apache reverse proxy on rivsprod01 with relative URLs and proper path configuration","bodyPreview":"# Reverse Proxy Deployment\n\nGuide for deploying web applications behind the Apache reverse proxy on rivsprod01 (dw.ramsden-international.com). Covers frontend relative URL patterns and Apache ProxyPass configuration.\n\n## Instructions\n\nWhen deploying a web application that will be accessed through the reverse proxy:\n\n1. **Use Relative URLs**: Frontend code must use relative URLs (not absolute localhost URLs) to work behind the proxy\n2. **Configure ProxyPass on rivsprod01**: Create Apache config i","body":"# Reverse Proxy Deployment\n\nGuide for deploying web applications behind the Apache reverse proxy on rivsprod01 (dw.ramsden-international.com). Covers frontend relative URL patterns and Apache ProxyPass configuration.\n\n## Instructions\n\nWhen deploying a web application that will be accessed through the reverse proxy:\n\n1. **Use Relative URLs**: Frontend code must use relative URLs (not absolute localhost URLs) to work behind the proxy\n2. **Configure ProxyPass on rivsprod01**: Create Apache config in `/etc/apache2/proxy-conf.d/` with proper path stripping\n3. **Order Matters**: More specific paths must come before general paths in Apache config\n4. **Test Locally First**: Verify services are accessible from rivsprod01 before configuring proxy\n5. **Use Trailing Slashes**: Both source and target URLs need trailing slashes for path stripping to work\n\n## Examples\n\n### Example 1: Deploy Web Application with API Backend\n\n```\nUser: I have a web app with frontend on port 9273 and API on port 8765. Deploy it behind the proxy at /myapp/\n\nClaude: I''ll set up your application for reverse proxy deployment:\n\n1. **Update Frontend URLs**: Change API calls to use relative URLs\n   - Before: `fetch(''http://localhost:8765/api/status'')`\n   - After: `fetch(''api/status'')`  // Relative to current path\n\n2. **Create Apache Config**: SSH to rivsprod01 and create `/etc/apache2/proxy-conf.d/myapp.conf`\n   - API path: `/myapp/api/` → backend on port 8765\n   - Frontend path: `/myapp/` → frontend on port 9273\n   - API location must come FIRST (more specific)\n\n3. **Reload Apache**: `sudo systemctl reload apache2`\n\n[Provides implementation using the ProxyPass Configuration pattern below]\n```\n\n### Example 2: Frontend Uses Absolute URLs\n\n```\nUser: My frontend has `fetch(''http://localhost:3000/api/data'')` hardcoded. How do I make it work behind a proxy?\n\nClaude: Absolute URLs won''t work behind a reverse proxy. You need to update the frontend to use relative URLs:\n\n**Options:**\n1. **Best: Use relative URLs** - `fetch(''api/data'')` - works anywhere\n2. **Alternative: Use base path** - Store base path in config, prepend to all API calls\n3. **Hidden input method** - Store proxy path in HTML, read in JavaScript\n\nFor option 1 (recommended):\n- Replace all `http://localhost:3000/api/` with `api/`\n- The browser resolves relative to current page path\n- If page is at `/myapp/`, API call goes to `/myapp/api/`\n\n[Shows the Relative URL Pattern implementation below]\n```\n\n### Example 3: Multiple Services on Same Machine\n\n```\nUser: I have 3 services running on ports 8001, 8002, 8003. Deploy all at /service1/, /service2/, /service3/\n\nClaude: I''ll configure all three services in a single Apache config file:\n\n1. **Create single config file**: `/etc/apache2/proxy-conf.d/services.conf`\n2. **Add ProxyPass for each**: More specific paths first (doesn''t matter here since no overlap)\n3. **Each service gets clean URLs**: Paths are stripped before forwarding\n4. **Reload once**: All services go live together\n\n[Provides implementation using the Multi-Service Configuration pattern below]\n```\n\n### Example 4: API Calls Return 404\n\n```\nUser: My frontend loads but API calls return 404. Frontend is at /rabbit/, API should be at /rabbit/api/\n\nClaude: The issue is likely ProxyPass configuration. Let me check:\n\n1. **Verify services are reachable**: From rivsprod01, can you curl the backend directly?\n   - `curl http://10.99.0.3:8765/status` should work\n\n2. **Check ProxyPass order**: API location must come BEFORE frontend location\n   - Wrong order: frontend `/rabbit/` catches `/rabbit/api/` requests\n   - Right order: API `/rabbit/api/` catches first, then frontend `/rabbit/`\n\n3. **Verify trailing slashes**: Both paths need trailing slashes for stripping\n   - `ProxyPass /rabbit/api/ http://10.99.0.3:8765/`\n   - Without trailing slash, path isn''t stripped properly\n\n[Shows debugging steps from Troubleshooting section below]\n```\n\n---\n\n# Reference Implementation Details\n\nThe sections below contain proven working configurations from production deployments.\n\n**Reference Files in This Folder**:\n- `rabbit.conf` - Example Apache config from Invoice OCR deployment\n\n## Relative URL Pattern\n\n**Purpose**: Make frontend work behind any reverse proxy path without hardcoding URLs\n\n### HTML Method (Recommended for Simple Cases)\n\n```html\n<!-- Hidden input stores the API base path -->\n<input type=\"hidden\" id=\"serverUrl\" value=\"api\">\n\n<script>\nfunction getServerUrl() {\n    return document.getElementById(''serverUrl'').value.trim();\n}\n\n// Use in fetch calls\nasync function checkStatus() {\n    const res = await fetch(`${getServerUrl()}/status`);\n    const data = await res.json();\n    // ...\n}\n</script>\n```\n\n**Key Points**:\n- Value is `\"api\"` (relative) not `\"http://localhost:8765\"` (absolute)\n- Browser resolves `api/status` relative to current page\n- If page is at `https://example.com/rabbit/`, request goes to `https://example.com/rabbit/api/status`\n- Proxy strips `/rabbit/` and forwards to backend\n\n### JavaScript Config Method (For Complex Applications)\n\n```javascript\n// config.js\nconst CONFIG = {\n    API_BASE: ''api'',  // Relative to current path\n    WS_BASE: ''ws''     // WebSocket endpoint if needed\n};\n\n// Use throughout app\nfetch(`${CONFIG.API_BASE}/endpoint`)\n```\n\n**When to use**:\n- Multiple API endpoints\n- Different base paths for dev/staging/prod\n- Need to change paths without editing HTML\n\n## ProxyPass Configuration Pattern\n\n**Purpose**: Configure Apache to forward requests from public path to internal service\n\n### Basic Single-Service Configuration\n\n**File**: `/etc/apache2/proxy-conf.d/myservice.conf`\n\n```apache\n# Single service on custom path\nProxyPass /myservice/ http://10.99.0.3:8080/\nProxyPassReverse /myservice/ http://10.99.0.3:8080/\n```\n\n**Key Points**:\n- Simple ProxyPass directives (no `<Location>` blocks needed)\n- Trailing slashes on both source and target strip the path prefix\n- Request to `/myservice/page` becomes `/page` at backend\n- `ProxyPassReverse` rewrites response headers (redirects, etc.)\n\n### API + Frontend Configuration\n\n**File**: `/etc/apache2/proxy-conf.d/service-with-api.conf`\n\n```apache\n# Backend API - Must come FIRST (more specific path)\nProxyPass /rabbit/api/ http://10.99.0.3:8765/\nProxyPassReverse /rabbit/api/ http://10.99.0.3:8765/\n\n# Frontend - Comes SECOND (less specific path)\nProxyPass /rabbit/ http://10.99.0.3:9273/\nProxyPassReverse /rabbit/ http://10.99.0.3:9273/\n```\n\n**Key Points**:\n- API location MUST be listed first (more specific)\n- If frontend is listed first, it catches API requests → 404\n- Both locations strip their prefix before forwarding\n- Request flow:\n  - `GET /rabbit/api/status` → matches first rule → `GET /status` to port 8765\n  - `GET /rabbit/index.html` → matches second rule → `GET /index.html` to port 9273\n\n### Large File Upload Configuration\n\n```apache\n# Service that handles file uploads (PDFs, images, etc.)\nProxyPass /uploads/ http://10.99.0.3:7000/\nProxyPassReverse /uploads/ http://10.99.0.3:7000/\n\n# Important for large PDF uploads\n<Location /uploads/>\n    ProxyPass http://10.99.0.3:7000/\n    ProxyPassReverse http://10.99.0.3:7000/\n\n    # Allow 50MB uploads\n    LimitRequestBody 52428800\n</Location>\n```\n\n**When to use**:\n- File upload services\n- PDF/image processing\n- Any endpoint that receives large request bodies\n\n## Multi-Service Configuration Pattern\n\n**Purpose**: Deploy multiple independent services in one config file\n\n**File**: `/etc/apache2/proxy-conf.d/all-services.conf`\n\n```apache\n# Service 1: API Gateway\nProxyPass /api/ http://10.99.0.3:8001/\nProxyPassReverse /api/ http://10.99.0.3:8001/\n\n# Service 2: Admin Dashboard\nProxyPass /admin/ http://10.99.0.3:8002/\nProxyPassReverse /admin/ http://10.99.0.3:8002/\n\n# Service 3: Public Website\nProxyPass /site/ http://10.99.0.3:8003/\nProxyPassReverse /site/ http://10.99.0.3:8003/\n```\n\n**Key Points**:\n- Each service is completely independent\n- Order doesn''t matter if paths don''t overlap\n- All go live together when Apache reloads\n- Can comment out individual services to disable temporarily\n\n## Deployment Workflow\n\n**Standard deployment process for new service:**\n\n### 1. Verify Local Service Accessibility\n\n```bash\n# From local machine where service runs\ncurl http://10.99.0.3:8765/status  # Test your port\n\n# From rivsprod01 (SSH in)\nssh rivsprod01 \"curl -s http://10.99.0.3:8765/status\"\n```\n\n**Expected**: JSON response or HTML, not connection refused\n\n### 2. Create Apache Configuration\n\n```bash\n# SSH to rivsprod01\nssh rivsprod01\n\n# Create config file (as root or with sudo)\nsudo nano /etc/apache2/proxy-conf.d/myservice.conf\n\n# Add ProxyPass configuration (see patterns above)\n\n# Verify syntax (optional, but recommended)\n# apache2ctl configtest   # May not be available\n# Just proceed to reload if command not found\n```\n\n### 3. Reload Apache\n\n```bash\nsudo systemctl reload apache2\n\n# Verify Apache is still running\nsudo systemctl status apache2\n```\n\n### 4. Test Public Access\n\n```bash\n# From any machine\ncurl https://dw.ramsden-international.com/myservice/\n\n# Or open in browser\n```\n\n## Troubleshooting\n\n### 404 Not Found - Service Works Locally\n\n**Cause**: ProxyPass configuration issue\n\n**Diagnostic Steps**:\n1. Verify service is accessible from rivsprod01:\n   ```bash\n   ssh rivsprod01 \"curl -s http://10.99.0.3:PORT/endpoint\"\n   ```\n\n2. Check Apache config order:\n   ```bash\n   ssh rivsprod01 \"cat /etc/apache2/proxy-conf.d/myservice.conf\"\n   ```\n   - API paths must come before frontend paths\n   - Verify trailing slashes on both source and target\n\n3. Check Apache error logs:\n   ```bash\n   ssh rivsprod01 \"sudo tail -50 /var/log/apache2/error.log | grep myservice\"\n   ```\n\n**Solution**:\n- Fix ProxyPass order (more specific first)\n- Add missing trailing slashes\n- Reload Apache: `sudo systemctl reload apache2`\n\n### 404 on API Calls, Frontend Works\n\n**Cause**: Frontend path is catching API requests\n\n**Example of Wrong Configuration**:\n```apache\n# WRONG - Frontend catches everything\nProxyPass /app/ http://10.99.0.3:9000/\nProxyPass /app/api/ http://10.99.0.3:8000/\n```\n\n**Solution - Put API First**:\n```apache\n# CORRECT - API catches specific path first\nProxyPass /app/api/ http://10.99.0.3:8000/\nProxyPass /app/ http://10.99.0.3:9000/\n```\n\n### Connection Refused from rivsprod01\n\n**Cause**: Service not listening on accessible IP\n\n**Diagnostic**:\n```bash\n# On machine running service\nnetstat -tlnp | grep PORT\n# or\nss -tlnp | grep PORT\n```\n\n**Look for**:\n- `127.0.0.1:PORT` - Only listening on localhost (wrong)\n- `10.99.0.3:PORT` - Listening on network IP (correct)\n- `0.0.0.0:PORT` - Listening on all interfaces (also correct)\n\n**Solution**: Configure service to bind to `0.0.0.0` or specific IP `10.99.0.3`\n\n### Service Stops Working After Apache Reload\n\n**Cause**: Configuration syntax error\n\n**Diagnostic**:\n```bash\nssh rivsprod01 \"sudo systemctl status apache2\"\n```\n\n**Solution**:\n1. Check for typos in ProxyPass URLs\n2. Verify no missing quotes or slashes\n3. Look at error log: `sudo tail /var/log/apache2/error.log`\n4. Fix config and reload again\n\n### CORS Errors in Browser Console\n\n**Cause**: Backend not configured for CORS, or wrong origin\n\n**Solution (Backend)**: Enable CORS in your service\n\n```python\n# FastAPI example\nfrom fastapi.middleware.cors import CORSMiddleware\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=[\"*\"],  # Or specific domain\n    allow_credentials=True,\n    allow_methods=[\"*\"],\n    allow_headers=[\"*\"],\n)\n```\n\n**Note**: Proxy handles forwarding; backend sees requests from proxy IP, not client\n\n## IP Addresses Reference\n\n| Hostname | IP Address | Purpose |\n|----------|-----------|---------|\n| rivsprod01 | 10.99.0.2 | Reverse proxy server (Apache) |\n| pogs (local) | 10.99.0.3 | Development machine running services |\n\n**Service Configuration**:\n- Services should bind to `10.99.0.3` or `0.0.0.0` to be accessible from rivsprod01\n- Use `http://10.99.0.3:PORT` in ProxyPass target URLs\n- Never use `localhost` or `127.0.0.1` in ProxyPass targets\n\n## File Locations on rivsprod01\n\n| Path | Purpose |\n|------|---------|\n| `/etc/apache2/proxy-conf.d/*.conf` | Proxy configurations (add yours here) |\n| `/etc/apache2/sites-available/default-ssl.conf` | Main SSL site config (includes proxy-conf.d) |\n| `/var/log/apache2/error.log` | Apache error log |\n| `/var/log/apache2/access.log` | Access log (if needed) |\n\n**Important**: Configs in `/etc/apache2/proxy-conf.d/` are automatically included by the SSL site configuration.\n\n## Best Practices Summary\n\n1. **Always use relative URLs** in frontend code for proxy compatibility\n2. **Test service accessibility** from rivsprod01 before configuring proxy\n3. **Put specific paths first** in Apache config (API before frontend)\n4. **Use trailing slashes** on both ProxyPass source and target for path stripping\n5. **Reload Apache** after config changes: `sudo systemctl reload apache2`\n6. **Keep configs organized** - one file per application or related service group\n7. **Document your paths** - add comments explaining what each ProxyPass does\n8. **Test both frontend and API** after deployment to verify routing\n"},"lastSynced":"2026-03-07T12:52:58.852Z","agentAnalysis":{"suitability":{"en":"Ideal for DevOps Automation Agents managing web application deployments and Apache server configuration.","zh":"适用于管理 Web 应用程序部署和 Apache 服务器配置的 DevOps Automation Agents。","ja":"Web アプリケーションのデプロイと Apache サーバーの構成を管理する DevOps Automation Agents に適しています。","ko":"웹 애플리케이션 배포 및 Apache 서버 구성 관리를 위한 DevOps Automation Agents 에 적합합니다.","es":"Ideal para agentes de automatización de DevOps que gestionan implementaciones de aplicaciones web y configuración del servidor Apache.","fr":"Idéal pour les agents d''automatisation DevOps gérant les déploiements d''applications web et la configuration du serveur Apache.","de":"Ideal für DevOps-Automatisierungsagenten, die die Bereitstellung von Webanwendungen und die Apache-Serverkonfiguration verwalten.","pt":"Ideal para Agentes de Automação DevOps que gerenciam implantações de aplicativos web e configuração do servidor Apache.","ru":"Идеально для агентов автоматизации DevOps, управляющих развертыванием веб-приложений и конфигурацией сервера Apache.","ar":"مثالي لعميل تطبيق التلقائي DevOps لإدارة توزيعات تطبيقات الويب وتكوين خادم Apache."},"recommendation":{"en":"Enables agents to automate Apache reverse proxy configurations on rivsprod01 servers using ProxyPass directives. Provides deployment guidance for frontend applications requiring relative URL patterns to function correctly behind reverse proxies.","zh":"使代理能够使用 ProxyPass 指令在 rivsprod01 服务器上自动化 Apache 反向代理配置。为需要相对 URL 模式才能在反向代理后面正确运行的前端应用程序提供部署指南。","ja":"ProxyPass ディレクティブを使用して、rivsprod01 サーバー上の Apache のリバースプロキシ構成を自動化するためにエージェントを有効にします。リバースプロキシの後で正常に機能するために相対 URL パターンを必要とするフロントエンド アプリケーションのデプロイ ガイダンスを提供します。","ko":"ProxyPass 지시문을 사용하여 rivsprod01 서버上的 Apache 역방향 프록시 구성을 자동화할 수 있도록 에이전트를 활성화합니다. 역방향 프록시 뒤에서 올바르게 작동하기 위해 상대 URL 패턴을 필요로 하는 프론트엔드 애플리케이션에 대한 배포 지침을 제공합니다.","es":"Permite a los agentes automatizar las configuraciones del proxy inverso de Apache en los servidores rivsprod01 utilizando directivas ProxyPass. Proporciona orientación sobre la implementación para aplicaciones frontend que requieren patrones de URL relativos para funcionar correctamente detrás de proxies inversos.","fr":"Permet aux agents d''automatiser les configurations du proxy inverse Apache sur les serveurs rivsprod01 en utilisant des directives ProxyPass. Fournit des conseils de déploiement pour les applications frontend nécessitant des modèles d''URL relatifs pour fonctionner correctement derrière les proxies inverses.","de":"Ermöglicht es den Agenten, die Apache-Reverse-Proxy-Konfigurationen auf rivsprod01-Servern mithilfe von ProxyPass-Direktiven zu automatisieren. Bietet Bereitstellungsrichtlinien für Frontend-Anwendungen, die relative URL-Muster benötigen, um ordnungsgemäß hinter Reverse-Proxys zu funktionieren.","pt":"Permite que os agentes automatem as configurações do proxy reverso do Apache nos servidores rivsprod01 usando diretivas ProxyPass. Fornece orientação de implantação para aplicativos frontend que requerem padrões de URL relativos para funcionar corretamente atrás de proxies reversos.","ru":"Позволяет агентам автоматизировать конфигурацию обратного прокси-сервера Apache на серверах rivsprod01 с использованием директив ProxyPass. Предоставляет рекомендации по развертыванию для frontend-приложений, требующих относительных шаблонов URL для правильной работы за обратными прокси.","ar":"يسمح للعملاء التلقائي بتحويل تكوين بروكسي أباتشي العكسي على خوادم rivsprod01 باستخدام توجيهات ProxyPass. يوفر إرشادات النشر للتطبيقات الأمامية التي تتطلب أنماط URL 相対ية للعمل بشكل صحيح خلف البروكسي العكسي."},"useCases":{"en":["Automating Apache ProxyPass configuration deployment","Validating frontend relative URL patterns for proxy compatibility","Deploying web applications to rivsprod01 production servers"],"zh":["自动化 Apache ProxyPass 配置部署","验证前端相对 URL 模式的代理兼容性","将 Web 应用程序部署到 rivsprod01 生产服务器"],"ja":["Apache ProxyPass 構成のデプロイを自動化する","フロントエンドの相対 URL パターンのプロキシ互換性を検証する","Web アプリケーションを rivsprod01 プロダクション サーバーにデプロイする"],"ko":["Apache ProxyPass 구성 배포 자동화","프론트엔드 상대 URL 패턴의 프록시 호환성 검증","웹 애플리케이션을 rivsprod01 프로덕션 서버에 배포"],"es":["Automatización de la implementación de la configuración de Apache ProxyPass","Validación de patrones de URL relativos de frontend para la compatibilidad con proxies","Implementación de aplicaciones web en servidores de producción rivsprod01"],"fr":["Automatisation du déploiement de la configuration de proxy Apache ProxyPass","Validation des modèles d''URL relatifs frontend pour la compatibilité des proxies","Déploiement d''applications web sur les serveurs de production rivsprod01"],"de":["Automatisierung der Bereitstellung der Apache-ProxyPass-Konfiguration","Validierung von relativen URL-Mustern für Frontend-Kompatibilität mit Proxys","Bereitstellung von Webanwendungen auf rivsprod01-Produktionsservern"],"pt":["Automatizar implantação de configuração ProxyPass do Apache","Validar padrões de URL relativos do frontend para compatibilidade com proxy","Implantar aplicativos web em servidores de produção rivsprod01"],"ru":["Автоматизация развертывания конфигурации ProxyPass Apache","Проверка относительных шаблонов URL frontend на совместимость с прокси","Развертывание веб-приложений на серверах производственной среды rivsprod01"],"ar":["تحويل توزيع تكوين بروكسي أباتشي العكسي","تحقق من أنماط URL 相対ية للتطبيقات الأمامية للتأكد من التوافق مع البروكسي","نشر تطبيقات الويب على خوادم الإنتاج rivsprod01"]},"limitations":{"en":["Specific to Apache web server configuration","Requires access to rivsprod01 server","Limited to ProxyPass directive implementation"],"zh":["特定于 Apache Web 服务器配置","需要访问 rivsprod01 服务器","仅限于 ProxyPass 指令实现"],"ja":["Apache Web サーバーの構成に特定の","rivsprod01 サーバーへのアクセスが必要","ProxyPass ディレクティブの実装に限定"],"ko":["Apache 웹 서버 구성에 특정","rivsprod01 서버에 대한 액세스가 필요","ProxyPass 지시문의 구현에 한정"],"es":["Específico de la configuración del servidor web Apache","Requiere acceso al servidor rivsprod01","Limitado a la implementación de la directiva ProxyPass"],"fr":["Spécifique à la configuration du serveur web Apache","Nécessite un accès au serveur rivsprod01","Limité à la mise en œuvre de la directive ProxyPass"],"de":["Spezifisch für die Apache-Webserver-Konfiguration","Erfordert Zugriff auf den rivsprod01-Server","Begrenzt auf die Implementierung der ProxyPass-Direktive"],"pt":["Específico para configuração do servidor web Apache","Requer acesso ao servidor rivsprod01","Limitado à implementação da diretiva ProxyPass"],"ru":["Конкретно для конфигурации веб-сервера Apache","Требует доступа к серверу rivsprod01","Ограничен реализацией директивы ProxyPass"],"ar":["محدد لتكوين خادم الويب أباتشي","يتطلب الوصول إلى خادم rivsprod01","محدود بتنفيذ توجيه ProxyPass"]},"version":4},"contentHash":"4953cd51d5e885379697cc5c9ce3bd717b616462555b73bcc6ba8e1685c3ae95","qualityScore":57}');
