INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lawless-m/Gwen/Reverse Proxy Deployment', 'Reverse Proxy Deployment', 'lawless-m', 'Gwen', 'community', 'Reverse Proxy Deployment lawless-m Gwen community Reverse Proxy Deployment enables developers to deploy web applications behind the Apache reverse proxy on rivsprod01. This skill covers frontend relative URL patterns and Apache ProxyPass configuration. 本指南介绍如何使用Apache反向代理部署Web应用程序，包括前端相对URL模式和ProxyPass配置 このガイドでは、Apacheのリバースプロキシを使用してWebアプリケーションをデプロイする方法について説明します。フロントエンドの相対URLパターンとProxyPassの設定を含みます 이 가이드는 Apache 리버스 프록시를 사용하여 웹 애플리케이션을 배포하는 방법에 대해 설명합니다. 프론트엔드 상대 URL 패턴과 ProxyPass 구성이 포함됩니다 El proxy inverso permite que tus aplicaciones web se ejecuten detrás de un servidor Apache, utilizando URL relativas y configuración de ProxyPass Le proxy inverse permet d''exécuter vos applications web derrière un serveur Apache, en utilisant des URL relatives et une configuration de ProxyPass Der Reverse-Proxy ermöglicht es, Webanwendungen hinter einem Apache-Server auszuführen, indem relative URLs und ProxyPass-Konfigurationen verwendet werden Configuração de proxy reverso para aplicações web com Apache e rivsprod01, incluindo padrões de URL relativos e configuração de ProxyPass. Настройка обратного прокси для веб-приложений с Apache и rivsprod01, включая относительные шаблоны URL и конфигурацию ProxyPass для ИИ Агентов. إعداد بروكسي عكسي لتقنيات الويب مع Apache و rivsprod01، بما في ذلك أنماط URL النسبية وتكوين ProxyPass how to use Reverse Proxy Deployment Reverse Proxy Deployment setup guide Apache reverse proxy configuration Reverse Proxy Deployment vs NGINX what is Reverse Proxy Deployment Reverse Proxy Deployment install on rivsprod01 Reverse Proxy Deployment tutorial for AI agents dw.ramsden-international.com deployment Apache ProxyPass configuration example 反向代理部署 Apache反向代理 Web应用程序部署 相对URL ProxyPass配置 rivsprod01 dw.ramsden-international.com AIエージェント AI工具 Uses relative URLs in frontend code for compatibility behind the proxy Configures Apache ProxyPass on rivsprod01 for seamless request forwarding Supports deployment of web applications on dw.ramsden-international.com Covers frontend relative URL patterns for optimal proxy performance Requires Apache config creation for ProxyPass setup Reverse Proxy Deployment is a technique for deploying web applications behind a reverse proxy server, such as Apache, to manage incoming requests and improve security.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Metavibez4L/openclaw-workspace/github', 'community', 'Metavibez4L', 'openclaw-workspace', 'Metavibez4L/openclaw-workspace', 'github', 0, 0, 57, '2026-03-06T12:59:22.125Z', '2026-03-06T13:13:28.187Z', '7114fd5b3ac5a9ec6d69c79e15b3b4eb3acfb9544667b28d15dbaa2ed79d1e6d', '{"id":"Metavibez4L/openclaw-workspace/github","name":"github","description":{"en":"The github skill provides a full-featured GitHub CLI wrapper for managing repositories, issues, and CI/CD workflows, benefiting developers and DevOps teams.","zh":"OpenClaw 代理工作空间中的 GitHub 技能提供了对仓库、问题、拉取请求、CI/CD 工作流程和发布的全面管理","ja":"OpenClaw エージェントワークスペースの GitHub スキルは、リポジトリ、Issue、プルリクエスト、CI/CD ワークフロー、リリースの管理を提供する","ko":"OpenClaw 에이전트 워크스페이스의 GitHub 스킬은 리포지토리, 이슈, 풀 리퀘스트, CI/CD 워크플ロー, 릴리스에 대한 종합적인 관리를 제공합니다","es":"GitHub Skill es un wrapper de CLI de GitHub para gestionar repositorios, problemas y solicitudes de extracción de manera eficiente.","fr":"GitHub Skill est un wrapper de CLI de GitHub pour gérer les référentiels, les problèmes et les demandes d''extraction de manière efficace.","de":"GitHub Skill ist ein GitHub-CLI-Wrapper für die effiziente Verwaltung von Repositorys, Problemen und Pull-Requests.","pt":"O GitHub Skill é uma ferramenta completa para gerenciar repositórios, problemas, solicitações de pull, fluxos de trabalho de CI/CD e lançamentos no GitHub.","ru":"ИИ Агенты GitHub - это полнофункциональный инструмент для управления репозиториями, проблемами, запросами на включение, рабочими процессами CI/CD и выпусками на GitHub.","ar":"مهارة GitHub هي أداة كاملة لادارة المستودعات والمشاكل وطلبات السحب وعمليات العمل في CI/CD والإصدارات على منصة GitHub."},"seo":{"title":{"en":"github: GitHub CLI Wrapper Setup Guide | AI Agent Skill","zh":"GitHub Setup Guide: CLI Wrapper for Repository Management","ja":"GitHub を使った CI/CD ワークフロー: AIエージェントのベストプラクティス","ko":"