INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('petbrains/mvp-builder/backend-zod', 'backend-zod', 'petbrains', 'mvp-builder', 'community', 'backend-zod petbrains mvp-builder community ai-agents automation claude-code code-generator developer-tools document-driven-development llm mvp prompt-engineering spec-driven tdd backend-zod是一个Document-Driven Development框架，用于Claude Code，提供结构化的规范、TDD循环、反馈循环和技能系统 backend-zodはClaude Code用のDocument-Driven Developmentフレームワークで、構造化された仕様、TDDサイクル、フィードバックループ、スキルシステムを提供します backend-zod는 Claude Code를 위한 문서 기반 개발 프레임워크로 구조화된 규격, TDD 사이클, 피드백 루프 및 스킬 시스템을 제공합니다 backend-zod es un framework de desarrollo dirigido por documentos para Claude Code, que ofrece especificaciones estructuradas, ciclos de TDD y un sistema de habilidades backend-zod est un framework de développement piloté par des documents pour Claude Code, qui propose des spécifications structurées, des cycles de TDD et un système de compétences backend-zod ist ein framework für dokumentengetriebene Entwicklung für Claude Code, das strukturierte Spezifikationen, TDD-Zyklen und ein Fähigkeitensystem bietet O backend-zod é um framework de desenvolvimento orientado a documentos para Claude Code, com especificações estruturadas e ciclos de TDD Backend-zod — это фреймворк разработки, ориентированный на документы для Claude Code, со структурированными спецификациями и циклами TDD backend-zod هو إطار عمل لتطوير التطبيقات الخلفية باستخدام وثائق Claude Code، مع مواصفات مهيكلة ودورات التطوير المستندة إلى الاختبار Document-Driven Development framework for Claude Code — structured specs, TDD cycles, feedback loops, and skills system AI智能开发框架 如何使用backend-zod 什么是Document-Driven Development backend-zod替代方案 backend-zod安装 Claude Code开发工具 Document-Driven Development framework for Claude Code — structured specs, TDD cycles, feedback loops, and skills system');
